// GENERADO por tools/embed-roblox.mjs a partir de la carpeta roblox/. No editar a mano.
export interface RobloxFile { path: string; code: string }
export const ROBLOX_PROJECT: { readme: string; files: RobloxFile[] } = {"readme":"# Mundo Catrucho\n\nParque de Tegucigalpa, 18 departamentos y cinco minijuegos hechos con piezas de Roblox. ¡Dale viaje!\n\n## Abrilo en Studio\n\n1. Instalá Rojo 7.7.1 y su complemento para Studio.\n2. Desde esta carpeta, ejecutá `rojo build -o MundoCatrucho.rbxl`.\n3. Abrí `MundoCatrucho.rbxl` en Roblox Studio y presioná **Play**. El servidor construye el mundo al arrancar.\n4. Para editar con sincronización, ejecutá `rojo serve` y conectá el complemento al puerto 34872.\n5. Publicá con **File > Publish to Roblox**. En **Game Settings > Security**, activá **Enable Studio Access to API Services** para probar guardado.\n6. Configurá el acceso público en Creator Dashboard. Probá salas privadas en la experiencia publicada.\n\nSin API en Studio, el progreso queda en memoria hasta cerrar el servidor. Si falla la carga en producción, se rechaza el ingreso para proteger los datos.\n\n## Carpetas\n\n```text\nroblox/\n├── default.project.json\n├── MundoCatrucho.rbxl\n├── src/\n│   ├── server/\n│   │   ├── Main.server.luau\n│   │   ├── Services/       Datos, progreso, red, tienda, salas y rondas\n│   │   ├── Minigames/      Carrera, fútbol, feria, exploradores y pulpería\n│   │   ├── World/          Lobby, mapa, zonas y monumentos\n│   │   └── Avatar/         Atuendos con piezas\n│   ├── client/Main.client.luau\n│   └── shared/             Configuración, tipos, red y lógica pura\n├── tests/run.luau\n├── scripts/verify.sh\n└── docs/                   Resultados y límites de verificación\n```\n\n## Datos compartidos\n\nRojo monta `../shared/data` directamente en `ReplicatedStorage.Shared.Data`. Los cinco JSON se convierten en ModuleScripts. `GameData` los consulta sin copiar su contenido a Luau.\n\n- `departments`: los 18 departamentos, centros, contornos, biomas, lugares, recuerdos y datos culturales.\n- `minigames`: duración, medallas, puestos de feria y sitios de exploración.\n- `rewards`: Lempiritas, premios y XP. Cada nivel requiere `base + (nivel - 1) * perLevel`.\n- `shop`: catálogo, precios, colores y avatar inicial.\n- `progress`: logros, tres misiones diarias y nombres de bots de ejemplo del ranking sin API.\n\nConservá la carpeta `../shared/data` al mover el proyecto. Los objetos culturales adicionales están en `shared/Content/Explorer.luau`.\n\n## Controles\n\nUsá WASD y Espacio en PC, o el control y salto de Roblox en celular. Acercate a los portales y usá **E** o el aviso táctil. **M** abre el mapa.\n\nEn fútbol, **F** patea hacia donde mira el personaje. En la feria, apuntá con el mouse y hacé clic. En celular, usá la cruz central y **Tirar**. **R**, las teclas **1–5** o **Fuerza** ajustan la argolla. Cambiá entre Copán, Yojoa y Roatán desde **Minijuegos**. El mismo menú permite abandonar sin premio.\n\nLa tienda vende artículos; **Personaje** aplica prendas y colores. Los emotes se usan desde esas pantallas. **Misiones** permite cobrar premios. **Ajustes** incluye salas privadas por código.\n\n## Validación del servidor\n\nEl servidor controla saldo, propiedad, colores permitidos, premios, XP, misiones y logros. Los remotos tienen límites de frecuencia. Las rondas usan reloj del servidor y rechazan marcadores imposibles. La carrera exige puestos en orden, tiempo mínimo por tramo y desplazamientos razonables. La feria comprueba dirección, fuerza, distancia y cantidad de tiros. Los goles y hallazgos se detectan en el servidor.\n\nEl DataStore usa reintentos, caché, candado de sesión, renovación, autoguardado y `BindToClose`. Cada minijuego tiene un OrderedDataStore. Los rankings sin API incluyen bots marcados con un robot.\n\n## Verificá el proyecto\n\nEjecutá `./scripts/verify.sh`. Podés cambiar la ruta de herramientas con `ROBLOX_TOOLS`.\n\nLa entrega pasó análisis estático, compilación Rojo y pruebas Lune. Lune abrió el `.rbxl`, comprobó los JSON, generó el mundo base y probó lógica y persistencia simulada. Consultá [el registro de verificación](docs/verificacion.md).\n\nRoblox Studio no se ejecutó en Linux. Falta probar física, cámara, saltos, interfaz táctil, emotes, multijugador, DataStores reales y teletransportes publicados. La feria usa aciertos matemáticos y efectos breves; los bots de fútbol son figuras simples. No hay música ni sonidos externos.\n","files":[{"path":"default.project.json","code":"{\n  \"name\": \"MundoCatrucho\",\n  \"tree\": {\n    \"$className\": \"DataModel\",\n    \"ReplicatedStorage\": {\n      \"$className\": \"ReplicatedStorage\",\n      \"Shared\": {\n        \"$path\": \"src/shared\",\n        \"Data\": {\n          \"$path\": \"../shared/data\"\n        }\n      }\n    },\n    \"ServerScriptService\": {\n      \"$className\": \"ServerScriptService\",\n      \"Server\": {\n        \"$path\": \"src/server\"\n      }\n    },\n    \"StarterPlayer\": {\n      \"$className\": \"StarterPlayer\",\n      \"$properties\": {\n        \"LoadCharacterAppearance\": false,\n        \"CharacterWalkSpeed\": 16,\n        \"CharacterJumpPower\": 50,\n        \"CharacterUseJumpPower\": true,\n        \"CameraMaxZoomDistance\": 40\n      },\n      \"StarterPlayerScripts\": {\n        \"$className\": \"StarterPlayerScripts\",\n        \"Client\": {\n          \"$path\": \"src/client\"\n        }\n      }\n    },\n    \"Workspace\": {\n      \"$className\": \"Workspace\",\n      \"$properties\": {\n        \"StreamingEnabled\": false,\n        \"FallenPartsDestroyHeight\": -150,\n        \"Gravity\": 196.2\n      }\n    },\n    \"Lighting\": {\n      \"$className\": \"Lighting\",\n      \"$properties\": {\n        \"ClockTime\": 14.5,\n        \"Brightness\": 2.6,\n        \"GlobalShadows\": true,\n        \"Ambient\": [0.45, 0.47, 0.5],\n        \"OutdoorAmbient\": [0.55, 0.57, 0.6],\n        \"EnvironmentDiffuseScale\": 0.6,\n        \"EnvironmentSpecularScale\": 0.4\n      }\n    },\n    \"SoundService\": {\n      \"$className\": \"SoundService\"\n    },\n    \"Players\": {\n      \"$className\": \"Players\",\n      \"$properties\": {\n        \"CharacterAutoLoads\": true\n      }\n    }\n  }\n}\n"},{"path":"src/client/Main.client.luau","code":"--!nonstrict\nlocal Players = game:GetService(\"Players\")\nlocal UIS = game:GetService(\"UserInputService\")\nlocal CAS = game:GetService(\"ContextActionService\")\nlocal GuiService = game:GetService(\"GuiService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Shared\")\nlocal Net = require(Shared.Net)\nlocal Data = require(Shared.GameData)\nlocal Shop = require(Shared.Logic.Shop)\nlocal Progression = require(Shared.Logic.Progression)\nlocal Rewards = require(Shared.Logic.Rewards)\nlocal Explorer = require(Shared.Content.Explorer)\nlocal player = Players.LocalPlayer\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"MundoCatrucho\"; gui.ResetOnSpawn = false; gui.IgnoreGuiInset = false\ngui.ScreenInsets = Enum.ScreenInsets.DeviceSafeInsets\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal profile, currentGame, _activePanel = nil, \"\", nil\nlocal power = 0.5\nlocal crosshair\nlocal navy, blue, cream = Color3.fromHex(\"#13375b\"), Color3.fromHex(\"#008ebc\"), Color3.fromHex(\"#fff5df\")\nlocal function frame(parent, size, position)\n\tlocal f = Instance.new(\"Frame\"); f.Size = size; f.Position = position or UDim2.new(); f.BackgroundColor3 = navy; f.BorderSizePixel = 0; f.Parent = parent\n\tlocal corner = Instance.new(\"UICorner\"); corner.CornerRadius = UDim.new(0, 10); corner.Parent = f\n\treturn f\nend\nlocal function label(parent, text, height)\n\tlocal l = Instance.new(\"TextLabel\"); l.Size = UDim2.new(1, 0, 0, height or 36); l.BackgroundTransparency = 1\n\tl.Text = text; l.TextColor3 = cream; l.TextSize = 17; l.Font = Enum.Font.GothamMedium; l.TextWrapped = true; l.Parent = parent\n\treturn l\nend\nlocal toast = label(gui, \"¡Bienvenido a Mundo Catrucho!\", 70)\ntoast.Size = UDim2.new(0.7, 0, 0, 70); toast.Position = UDim2.fromScale(0.15, 0.72); toast.BackgroundColor3 = navy; toast.BackgroundTransparency = 0.1; toast.ZIndex = 20\nlocal toastToken = 0\nlocal function notify(text)\n\ttoastToken += 1; local token = toastToken\n\ttoast.Text = text; toast.Visible = true\n\ttask.delay(7, function() if token == toastToken then toast.Visible = false end end)\nend\nlocal function invoke(name, ...)\n\tlocal ok, result = pcall(function(...) return Net.func(name):InvokeServer(...) end, ...)\n\tif not ok then notify(\"Se cortó la conexión. Probá otra vez.\"); return { ok = false } end\n\tif result and result.msg then notify(result.msg) end\n\treturn result or { ok = false }\nend\nlocal function button(parent, text, callback)\n\tlocal b = Instance.new(\"TextButton\"); b.Size = UDim2.new(1, 0, 0, 44); b.BackgroundColor3 = blue; b.BorderSizePixel = 0\n\tb.Text = text; b.TextColor3 = cream; b.TextSize = 16; b.Font = Enum.Font.GothamBold; b.TextWrapped = true; b.Parent = parent\n\tlocal c = Instance.new(\"UICorner\"); c.CornerRadius = UDim.new(0, 7); c.Parent = b\n\tb.Activated:Connect(function() task.spawn(callback) end)\n\treturn b\nend\nlocal hud = frame(gui, UDim2.new(0.55, 0, 0, 58), UDim2.fromOffset(8, 8))\nlocal hudText = label(hud, \"Cargando tus datos…\", 38)\nlocal bar = frame(hud, UDim2.new(0, 0, 0, 5), UDim2.new(0, 0, 1, -7)); bar.BackgroundColor3 = Color3.fromHex(\"#ffc93c\")\nlocal gameHud = label(gui, \"\", 74); gameHud.Size = UDim2.new(0.6, 0, 0, 74); gameHud.Position = UDim2.new(0.2, 0, 0, 70)\ncrosshair = label(gui, \"+\", 32); crosshair.Size = UDim2.fromOffset(32, 32); crosshair.AnchorPoint = Vector2.new(0.5, 0.5); crosshair.Position = UDim2.fromScale(0.5, 0.5); crosshair.Visible = false\nlocal menu = frame(gui, UDim2.fromOffset(132, 400), UDim2.fromOffset(8, 90))\nlocal menuLayout = Instance.new(\"UIListLayout\"); menuLayout.Padding = UDim.new(0, 5); menuLayout.Parent = menu\nlocal panel = frame(gui, UDim2.fromScale(0.68, 0.72), UDim2.fromScale(0.29, 0.2)); panel.Visible = false\nlocal heading = label(panel, \"\", 40); heading.Size = UDim2.new(1, -55, 0, 40)\nlocal close = button(panel, \"×\", function() panel.Visible = false; _activePanel = nil end); close.Size = UDim2.fromOffset(44, 36); close.Position = UDim2.new(1, -48, 0, 3)\nlocal content = Instance.new(\"ScrollingFrame\"); content.Size = UDim2.new(1, -20, 1, -52); content.Position = UDim2.fromOffset(10, 46)\ncontent.BackgroundTransparency = 1; content.BorderSizePixel = 0; content.AutomaticCanvasSize = Enum.AutomaticSize.Y; content.CanvasSize = UDim2.new(); content.ScrollBarThickness = 5; content.Parent = panel\nlocal function clear()\n\tfor _, child in content:GetChildren() do child:Destroy() end\n\tlocal layout = Instance.new(\"UIListLayout\"); layout.Padding = UDim.new(0, 7); layout.Parent = content\n\tcontent.CanvasPosition = Vector2.zero\nend\nlocal open\nlocal function travel(id)\n\tif invoke(\"TravelTo\", id).ok then panel.Visible = false end\nend\nlocal function entry(text) return label(content, text, 64) end\nopen = function(id)\n\t_activePanel = id; clear(); panel.Visible = true\n\theading.Text = ({ jugar = \"¡Dale viaje!\", mapa = \"Explorá Honduras\", minijuegos = \"Minijuegos\", personaje = \"Tu personaje\", tienda = \"Pulpería Doña Toña\", misiones = \"Misiones y logros\", ranking = \"Los más pilas\", ajustes = \"Ajustes y salas\" })[id] or id\n\tif id == \"jugar\" then\n\t\tentry(\"Bienvenido, maje. Explorá el país, jugá y ganá Lempiritas.\")\n\t\tbutton(content, \"Minijuegos\", function() open(\"minijuegos\") end)\n\t\tbutton(content, \"Explorar los 18 departamentos\", function() open(\"mapa\") end)\n\t\tbutton(content, \"Volver al parque\", function() travel(\"lobby\") end)\n\telseif id == \"mapa\" then\n\t\tlocal map = frame(content, UDim2.new(1, 0, 0, 220)); map.BackgroundColor3 = blue\n\t\tfor _, dept in Data.departments do\n\t\t\tlocal dot = button(map, \"●\", function() travel(dept.id) end)\n\t\t\tdot.Size = UDim2.fromOffset(24, 24); dot.AnchorPoint = Vector2.new(0.5, 0.5)\n\t\t\tdot.Position = UDim2.fromScale(dept.map.center[1] / Data.viewBox[1], dept.map.center[2] / Data.viewBox[2])\n\t\t\tdot.BackgroundColor3 = Color3.fromHex(dept.colors[1])\n\t\tend\n\t\tfor _, dept in Data.departments do\n\t\t\tbutton(content, (if profile and profile.visited[dept.id] then \"✓ \" else \"\") .. dept.name .. \" · \" .. dept.cabecera, function() travel(dept.id) end)\n\t\tend\n\telseif id == \"minijuegos\" then\n\t\tif currentGame == \"exploradores\" then\n\t\t\tfor _, site in Data.rules(\"exploradores\").sites do button(content, \"Viajar: \" .. Explorer.siteNames[site], function() invoke(\"ExplorerTravel\", site); panel.Visible = false end) end\n\t\tend\n\t\tif currentGame ~= \"\" then button(content, \"Salir de la partida\", function() Net.event(\"MinigameQuit\"):FireServer(); panel.Visible = false end) end\n\t\tfor _, info in Data.minigames do\n\t\t\tentry(info.name .. \"\\n\" .. info.desc)\n\t\t\tbutton(content, \"Jugar · \" .. info.name, function() if invoke(\"MinigameStart\", info.id).ok then panel.Visible = false end end)\n\t\tend\n\telseif id == \"tienda\" or id == \"personaje\" then\n\t\tif not profile then entry(\"Cargando…\"); return end\n\t\tif id == \"personaje\" then\n\t\t\tfor field, listName in Data.colorFields do\n\t\t\t\tlocal names = { skin = \"Piel\", hairColor = \"Cabello\", shirtColor = \"Camisa\", pantsColor = \"Pantalón\", hatColor = \"Sombrero\", accColor = \"Accesorio\" }\n\t\t\t\tbutton(content, \"Color: \" .. names[field], function()\n\t\t\t\t\tlocal list = Data.shop[listName]; local index = table.find(list, profile.avatar[field]) or 0\n\t\t\t\t\tinvoke(\"AvatarSet\", { [field] = list[index % #list + 1] })\n\t\t\t\tend)\n\t\t\tend\n\t\tend\n\t\tfor _, item in Data.shop.items do\n\t\t\tlocal owned = Shop.owns(profile, item.id)\n\t\t\tif id == \"personaje\" and not owned then continue end\n\t\t\tlocal action = if not owned then `Comprar · {item.price} Lempiritas` elseif item.cat == \"emote\" then \"Usar\" else \"Poner\"\n\t\t\tbutton(content, item.name .. \" · \" .. action, function()\n\t\t\t\tif not Shop.owns(profile, item.id) then invoke(\"ShopBuy\", item.id)\n\t\t\t\telseif item.cat == \"emote\" then Net.event(\"EmoteRequest\"):FireServer(item.id)\n\t\t\t\telse invoke(\"AvatarSet\", { [Data.slotByCat[item.cat]] = item.id }) end\n\t\t\tend)\n\t\tend\n\telseif id == \"misiones\" then\n\t\tif not profile then return end\n\t\tfor _, dm in profile.daily.missions do\n\t\t\tlocal mission = Data.missionById[dm.id]\n\t\t\tbutton(content, `{mission.text} · {dm.progress}/{mission.count} · {if dm.claimed then \"Cobrado\" else \"Cobrar\"}`, function() invoke(\"ClaimMission\", dm.id) end)\n\t\tend\n\t\tfor _, a in Data.achievements do entry((if profile.achievements[a.id] then \"✓ \" else \"○ \") .. a.name .. \"\\n\" .. a.desc) end\n\t\tfor _, object in Explorer.objects do if profile.facts[object.id] then entry(object.name .. \" · \" .. object.fact) end end\n\telseif id == \"ranking\" then\n\t\tfor _, info in Data.minigames do\n\t\t\tbutton(content, info.name, function()\n\t\t\t\tlocal result = invoke(\"GetLeaderboard\", info.id)\n\t\t\t\tclear(); entry(info.name)\n\t\t\t\tfor i, row in result.entries or {} do entry(`{i}. {row.name} · {row.label}`) end\n\t\t\tend)\n\t\tend\n\telseif id == \"ajustes\" then\n\t\tif profile then\n\t\t\tfor _, setting in { { \"lowFx\", \"Efectos reducidos\" }, { \"names\", \"Mostrar nombres\" }, { \"sfx\", \"Avisos visuales extra\" } } do\n\t\t\t\tbutton(content, setting[2] .. \": \" .. (if profile.settings[setting[1]] then \"Sí\" else \"No\"), function() invoke(\"SettingsSet\", { [setting[1]] = not profile.settings[setting[1]] }) end)\n\t\t\tend\n\t\t\tbutton(content, \"Tamaño de interfaz: \" .. profile.settings.uiScale, function() invoke(\"SettingsSet\", { uiScale = if profile.settings.uiScale >= 1.3 then 0.8 else profile.settings.uiScale + 0.1 }) end)\n\t\tend\n\t\tlocal code = Instance.new(\"TextBox\"); code.Size = UDim2.new(1, 0, 0, 44); code.PlaceholderText = \"Código de sala (6 letras)\"; code.Text = \"\"; code.TextSize = 18; code.Parent = content\n\t\tbutton(content, \"Crear sala privada\", function() local r = invoke(\"RoomCreate\"); if r.code then notify(\"Tu código: \" .. r.code) end end)\n\t\tbutton(content, \"Entrar con código\", function() invoke(\"RoomJoin\", code.Text) end)\n\t\tlocal info = invoke(\"RoomInfo\"); entry(if info.private then \"Sala privada · \" .. (info.code or \"cargando código\") else \"Servidor público · invitá a tus amigos\")\n\tend\nend\nfor _, item in { { \"Jugar\", \"jugar\" }, { \"Explorar / Mapa\", \"mapa\" }, { \"Minijuegos\", \"minijuegos\" }, { \"Personaje\", \"personaje\" }, { \"Tienda\", \"tienda\" }, { \"Misiones\", \"misiones\" }, { \"Ranking\", \"ranking\" }, { \"Ajustes / Salas\", \"ajustes\" } } do button(menu, item[1], function() open(item[2]) end) end\nlocal scale = Instance.new(\"UIScale\"); scale.Parent = gui\nlocal function applySettings()\n\tlocal viewport = workspace.CurrentCamera.ViewportSize\n\tlocal inset = GuiService:GetGuiInset()\n\tscale.Scale = math.clamp((viewport.Y - inset.Y) / 720, 0.65, 1) * (if profile then profile.settings.uiScale else 1)\n\tif profile then\n\t\tfor _, p in Players:GetPlayers() do\n\t\t\tlocal h = p.Character and p.Character:FindFirstChildOfClass(\"Humanoid\")\n\t\t\tif h then h.DisplayDistanceType = if profile.settings.names then Enum.HumanoidDisplayDistanceType.Viewer else Enum.HumanoidDisplayDistanceType.None end\n\t\tend\n\t\tfor _, obj in workspace:GetDescendants() do if obj:IsA(\"Sparkles\") then obj.Enabled = not profile.settings.lowFx end end\n\tend\nend\nNet.event(\"ProfileSync\").OnClientEvent:Connect(function(p)\n\tprofile = p; hudText.Text = `{p.coins} Lempiritas · Nivel {p.level} · {p.xp}/{Progression.need(p.level)} XP`\n\tbar.Size = UDim2.new(math.clamp(p.xp / Progression.need(p.level), 0, 1), 0, 0, 5)\n\tapplySettings()\nend)\nNet.event(\"Toast\").OnClientEvent:Connect(function(text) notify(text) end)\nNet.event(\"OpenPanel\").OnClientEvent:Connect(open)\nNet.event(\"MinigameState\").OnClientEvent:Connect(function(state)\n\tcurrentGame = state.id\n\tcrosshair.Visible = state.id == \"feria\" and UIS.TouchEnabled\n\tgameHud.Text = if state.id == \"\" then \"\" else `{Data.minigameById[state.id].name} · {Rewards.fmtClock(state.remaining)} · {state.score}\\n{state.hint or \"\"}`\nend)\nNet.event(\"MinigameResult\").OnClientEvent:Connect(function(result)\n\topen(\"resultado\"); heading.Text = \"¡Terminaste, catracho!\"\n\tentry(Data.minigameById[result.id].name .. \"\\n\" .. result.label)\n\tentry(string.rep(\"★\", result.stars) .. `\\n+{result.coins} Lempiritas · +{result.xp} XP`)\n\tbutton(content, \"Otra vez\", function() if invoke(\"MinigameStart\", result.id).ok then panel.Visible = false end end)\nend)\nlocal emotes = {}\nlocal animatedJoints = {}\nNet.event(\"EmotePlay\").OnClientEvent:Connect(function(userId, id) emotes[userId] = { at = os.clock(), id = id } end)\nRunService.PreSimulation:Connect(function()\n\tfor joint in animatedJoints do if joint.Parent then joint.Transform = CFrame.identity end end\n\ttable.clear(animatedJoints)\n\tfor userId, emote in emotes do\n\t\tlocal p = Players:GetPlayerByUserId(userId)\n\t\tlocal c = p and p.Character\n\t\tlocal t = os.clock() - emote.at\n\t\tif t > 4 or not c then emotes[userId] = nil; continue end\n\t\tfor _, joint in c:GetDescendants() do\n\t\t\tif joint:IsA(\"Motor6D\") and (joint.Name == \"Waist\" or joint.Name == \"RootJoint\" or string.find(joint.Name, \"Shoulder\")) then\n\t\t\t\tanimatedJoints[joint] = true\n\t\t\t\tjoint.Transform = CFrame.Angles(0, math.sin(t * 8) * 0.15, math.sin(t * 10) * 0.3)\n\t\t\tend\n\t\tend\n\tend\nend)\nNet.event(\"Effect\").OnClientEvent:Connect(function(kind)\n\tif kind == \"moneda\" and profile and profile.settings.sfx then notify(\"+1 Lempirita\") end\nend)\nlocal function shoot()\n\tif currentGame ~= \"feria\" then return end\n\tlocal camera = workspace.CurrentCamera\n\tlocal pointer = if UIS.TouchEnabled then camera.ViewportSize / 2 else UIS:GetMouseLocation() - GuiService:GetGuiInset()\n\tlocal ray = camera:ViewportPointToRay(pointer.X, pointer.Y)\n\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\tif root then\n\t\tlocal point = ray.Origin + ray.Direction * 60\n\t\tNet.event(\"FeriaShoot\"):FireServer((point - root.Position).Unit, power)\n\tend\nend\nCAS:BindAction(\"Patear\", function(_, state) if state == Enum.UserInputState.Begin and currentGame == \"futbol\" then Net.event(\"FutbolKick\"):FireServer() end end, true, Enum.KeyCode.F)\nCAS:SetTitle(\"Patear\", \"Patear\"); CAS:SetPosition(\"Patear\", UDim2.new(1, -170, 1, -160))\nCAS:BindAction(\"Tirar\", function(_, state) if state == Enum.UserInputState.End and not panel.Visible then shoot() end end, true, Enum.KeyCode.ButtonR2)\nCAS:SetTitle(\"Tirar\", \"Tirar\"); CAS:SetPosition(\"Tirar\", UDim2.new(1, -245, 1, -160))\nCAS:BindAction(\"Fuerza\", function(_, state) if state == Enum.UserInputState.Begin then power = (math.round(power * 5) % 5 + 1) / 5; notify(`Fuerza: {math.round(power * 100)}%`) end end, true, Enum.KeyCode.R)\nCAS:SetTitle(\"Fuerza\", \"Fuerza\"); CAS:SetPosition(\"Fuerza\", UDim2.new(1, -245, 1, -220))\nUIS.InputEnded:Connect(function(input, processed)\n\tif not processed and input.UserInputType == Enum.UserInputType.MouseButton1 and not panel.Visible then shoot() end\nend)\nUIS.InputBegan:Connect(function(input, processed)\n\tif processed then return end\n\tif input.KeyCode == Enum.KeyCode.M then open(\"mapa\") end\n\tlocal index = table.find({ Enum.KeyCode.One, Enum.KeyCode.Two, Enum.KeyCode.Three, Enum.KeyCode.Four, Enum.KeyCode.Five }, input.KeyCode)\n\tif index then power = index / 5; notify(`Fuerza: {index * 20}%`) end\nend)\nworkspace.CurrentCamera:GetPropertyChangedSignal(\"ViewportSize\"):Connect(applySettings)\napplySettings()\ntask.spawn(function()\n\tlocal result = invoke(\"GetProfile\")\n\tif result.profile then\n\t\tprofile = result.profile\n\t\thudText.Text = `{profile.coins} Lempiritas · Nivel {profile.level}`\n\t\tbar.Size = UDim2.new(profile.xp / Progression.need(profile.level), 0, 0, 5)\n\t\tapplySettings()\n\tend\nend)\n"},{"path":"src/server/Avatar/Outfit.luau","code":"--!strict\n-- Viste al personaje con piezas hechas por código (sin assets externos): colores de cuerpo,\n-- cabello, rostro, detalles de camisa y pantalón, sombrero y accesorio. Funciona en R15 y R6.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Types = require(Shared.Types)\n\nlocal Outfit = {}\n\nlocal V3 = Vector3.new\nlocal CF = CFrame.new\nlocal ANG = CFrame.Angles\nlocal rad = math.rad\nlocal hex = Color3.fromHex\n\nlocal WHITE, BLACK = hex(\"#f7f4ec\"), hex(\"#1d1d1f\")\nlocal FLAG_BLUE = hex(\"#00a3d7\")\nlocal MANTA = hex(\"#efe3c8\")\nlocal JUNCO = hex(\"#e6cf8b\")\n\n-- Color base de las prendas que no se tiñen.\nlocal FIXED_SHIRT: { [string]: Color3 } = {\n\tcamisa_h = WHITE,\n\tcamisa_h_azul = hex(\"#0d47a1\"),\n\tguayabera = WHITE,\n\tcamisa_manta = MANTA,\n\tblusa_tipica = WHITE,\n}\nlocal FIXED_PANTS: { [string]: Color3 } = {\n\tjeans = hex(\"#3b6ea5\"),\n\tpantalon_manta = MANTA,\n}\n\ntype Maker = (size: Vector3, offset: CFrame, color: Color3, material: Enum.Material?, shape: Enum.PartType?) -> Part\n\n-- Devuelve una función que crea piezas soldadas a `base`.\nlocal function maker(model: Model, base: BasePart): Maker\n\treturn function(size, offset, color, material, shape)\n\t\tlocal p = Instance.new(\"Part\")\n\t\tp.Size = size\n\t\tp.Color = color\n\t\tp.Material = material or Enum.Material.SmoothPlastic\n\t\tp.Shape = shape or Enum.PartType.Block\n\t\tp.TopSurface = Enum.SurfaceType.Smooth\n\t\tp.BottomSurface = Enum.SurfaceType.Smooth\n\t\tp.Anchored = false\n\t\tp.CanCollide = false\n\t\tp.CanTouch = false\n\t\tp.CanQuery = false\n\t\tp.Massless = true\n\t\tp.CFrame = base.CFrame * offset\n\t\tlocal weld = Instance.new(\"WeldConstraint\")\n\t\tweld.Part0 = base\n\t\tweld.Part1 = p\n\t\tweld.Parent = p\n\t\tp.Parent = model\n\t\treturn p\n\tend\nend\n\n-- Cilindro vertical respecto a la pieza base.\nlocal function cyl(make: Maker, radius: number, height: number, offset: CFrame, color: Color3, material: Enum.Material?): Part\n\treturn make(V3(height, radius * 2, radius * 2), offset * ANG(0, 0, rad(90)), color, material, Enum.PartType.Cylinder)\nend\n\nlocal function plate(make: Maker, size: Vector3, offset: CFrame, text: string, color: Color3, face: Enum.NormalId): Part\n\tlocal p = make(size, offset, WHITE)\n\tp.Transparency = 1\n\tlocal gui = Instance.new(\"SurfaceGui\")\n\tgui.Face = face\n\tgui.CanvasSize = Vector2.new(200, 200 * size.Y / math.max(size.X, 0.01))\n\tgui.LightInfluence = 1\n\tgui.Parent = p\n\tlocal label = Instance.new(\"TextLabel\")\n\tlabel.Size = UDim2.fromScale(1, 1)\n\tlabel.BackgroundTransparency = 1\n\tlabel.Text = text\n\tlabel.TextColor3 = color\n\tlabel.Font = Enum.Font.FredokaOne\n\tlabel.TextScaled = true\n\tlabel.Parent = gui\n\treturn p\nend\n\nlocal function find(character: Model, ...: string): BasePart?\n\tfor _, name in { ... } do\n\t\tlocal p = character:FindFirstChild(name)\n\t\tif p and p:IsA(\"BasePart\") then\n\t\t\treturn p\n\t\tend\n\tend\n\treturn nil\nend\n\nlocal function setBodyColors(character: Model, skin: Color3, shirt: Color3, legs: Color3)\n\tlocal found = character:FindFirstChildOfClass(\"BodyColors\")\n\tlocal bc: BodyColors\n\tif found then\n\t\tbc = found\n\telse\n\t\tbc = Instance.new(\"BodyColors\")\n\t\tbc.Parent = character\n\tend\n\tbc.HeadColor3 = skin\n\tbc.LeftArmColor3 = skin\n\tbc.RightArmColor3 = skin\n\tbc.TorsoColor3 = shirt\n\tbc.LeftLegColor3 = legs\n\tbc.RightLegColor3 = legs\nend\n\n----------------------------------------------------------------------------------------------------\n-- Rostro: se dibuja con Frames sobre una placa frente a la cabeza.\n\nlocal function dot(parent: Instance, x: number, y: number, w: number, h: number, color: Color3): Frame\n\tlocal f = Instance.new(\"Frame\")\n\tf.AnchorPoint = Vector2.new(0.5, 0.5)\n\tf.Position = UDim2.fromScale(x / 100, y / 100)\n\tf.Size = UDim2.fromScale(w / 100, h / 100)\n\tf.BackgroundColor3 = color\n\tf.BorderSizePixel = 0\n\tlocal corner = Instance.new(\"UICorner\")\n\tcorner.CornerRadius = UDim.new(0.5, 0)\n\tcorner.Parent = f\n\tf.Parent = parent\n\treturn f\nend\n\nlocal function buildFace(make: Maker, head: BasePart, faceId: string, w: number, h: number, d: number)\n\tfor _, child in head:GetChildren() do\n\t\tif child:IsA(\"Decal\") then\n\t\t\tchild:Destroy()\n\t\tend\n\tend\n\tlocal p = make(V3(w * 0.92, h * 0.92, 0.05), CF(0, 0, -d / 2 - 0.03), WHITE)\n\tp.Transparency = 1\n\tp.Name = \"Rostro\"\n\tlocal gui = Instance.new(\"SurfaceGui\")\n\tgui.Face = Enum.NormalId.Front\n\tgui.CanvasSize = Vector2.new(200, 200)\n\tgui.LightInfluence = 1\n\tgui.Parent = p\n\tlocal root = Instance.new(\"Frame\")\n\troot.Size = UDim2.fromScale(1, 1)\n\troot.BackgroundTransparency = 1\n\troot.Parent = gui\n\n\tlocal wink = faceId == \"cara_guino\"\n\tif faceId == \"cara_lentes\" then\n\t\tdot(root, 30, 40, 30, 20, BLACK).ZIndex = 2\n\t\tdot(root, 70, 40, 30, 20, BLACK).ZIndex = 2\n\t\tdot(root, 50, 38, 16, 5, BLACK)\n\telse\n\t\tdot(root, 30, 40, 11, if wink then 4 else 16, BLACK)\n\t\tdot(root, 70, 40, 11, 16, BLACK)\n\tend\n\t-- boca: medio círculo recortado\n\tlocal clip = Instance.new(\"Frame\")\n\tclip.AnchorPoint = Vector2.new(0.5, 0)\n\tclip.Position = UDim2.fromScale(0.5, 0.6)\n\tclip.Size = UDim2.fromScale(0.44, 0.22)\n\tclip.BackgroundTransparency = 1\n\tclip.ClipsDescendants = true\n\tclip.Parent = root\n\tlocal mouth = Instance.new(\"Frame\")\n\tmouth.AnchorPoint = Vector2.new(0.5, 1)\n\tmouth.Position = UDim2.fromScale(0.5, 1)\n\tmouth.Size = UDim2.fromScale(1, 2)\n\tmouth.BorderSizePixel = 0\n\tlocal round = Instance.new(\"UICorner\")\n\tround.CornerRadius = UDim.new(0.5, 0)\n\tround.Parent = mouth\n\tif faceId == \"cara_feliz\" then\n\t\tmouth.BackgroundColor3 = hex(\"#7a1f2b\")\n\telse\n\t\tmouth.BackgroundTransparency = 1\n\t\tlocal stroke = Instance.new(\"UIStroke\")\n\t\tstroke.Thickness = 7\n\t\tstroke.Color = BLACK\n\t\tstroke.Parent = mouth\n\t\tmouth.Size = UDim2.new(1, -14, 2, -14)\n\t\tmouth.Position = UDim2.new(0.5, 0, 1, -7)\n\tend\n\tmouth.Parent = clip\n\tif faceId == \"cara_pecas\" then\n\t\tfor _, o in { { 20, 56 }, { 27, 60 }, { 14, 61 }, { 80, 56 }, { 73, 60 }, { 86, 61 } } do\n\t\t\tdot(root, o[1], o[2], 4, 4, hex(\"#8a5a3c\"))\n\t\tend\n\telseif faceId == \"cara_bigote\" then\n\t\tdot(root, 50, 58, 44, 10, hex(\"#2b1b12\")).ZIndex = 3\n\tend\nend\n\n----------------------------------------------------------------------------------------------------\n\nlocal function buildHair(make: Maker, hairId: string, color: Color3, w: number, h: number, d: number)\n\tif hairId == \"calvo\" then\n\t\treturn\n\tend\n\tlocal top = h / 2\n\tif hairId == \"pelo_afro\" then\n\t\tmake(V3(w + 1, w + 1, w + 1), CF(0, top + 0.25, 0.1), color, Enum.Material.Fabric, Enum.PartType.Ball)\n\t\treturn\n\tend\n\tmake(V3(w + 0.12, 0.34, d + 0.12), CF(0, top + 0.1, 0), color) -- casquete\n\tmake(V3(w + 0.12, h * 0.55, 0.22), CF(0, top - h * 0.25, d / 2 + 0.05), color) -- nuca\n\tif hairId == \"pelo_largo\" then\n\t\tmake(V3(w + 0.12, 1.5, 0.26), CF(0, top - 0.9, d / 2 + 0.08), color)\n\t\tfor _, x in { -1, 1 } do\n\t\t\tmake(V3(0.2, 1.1, d * 0.6), CF(x * (w / 2 + 0.06), top - 0.6, 0.15), color)\n\t\tend\n\telseif hairId == \"pelo_rizado\" then\n\t\tfor i = 0, 5 do\n\t\t\tlocal a = rad(i * 60)\n\t\t\tmake(V3(0.62, 0.62, 0.62), CF(math.cos(a) * w * 0.38, top + 0.3, math.sin(a) * d * 0.38), color, nil, Enum.PartType.Ball)\n\t\tend\n\t\tmake(V3(0.7, 0.7, 0.7), CF(0, top + 0.42, 0), color, nil, Enum.PartType.Ball)\n\telseif hairId == \"pelo_coleta\" then\n\t\tmake(V3(0.4, 0.4, 0.5), CF(0, top - 0.1, d / 2 + 0.3), color)\n\t\tmake(V3(0.6, 1, 0.6), CF(0, top - 0.6, d / 2 + 0.6), color, nil, Enum.PartType.Ball)\n\telseif hairId == \"pelo_trenzas\" then\n\t\tfor _, x in { -1, 1 } do\n\t\t\tcyl(make, 0.16, 1.5, CF(x * (w / 2 + 0.1), top - 0.9, 0.1), color)\n\t\t\tmake(V3(0.3, 0.3, 0.3), CF(x * (w / 2 + 0.1), top - 1.7, 0.1), hex(\"#e63946\"), nil, Enum.PartType.Ball)\n\t\tend\n\tend\nend\n\nlocal function buildHat(make: Maker, hatId: string, tint: Color3, w: number, h: number, d: number)\n\tlocal y = h / 2 + 0.28 -- encima del cabello\n\tif hatId == \"gorra\" then\n\t\tcyl(make, w / 2 + 0.1, 0.45, CF(0, y + 0.22, 0), tint, Enum.Material.Fabric)\n\t\tmake(V3(w * 0.8, 0.1, 0.7), CF(0, y + 0.06, -d / 2 - 0.3), tint, Enum.Material.Fabric)\n\telseif hatId == \"sombrero_junco\" then\n\t\tcyl(make, 1.3, 0.1, CF(0, y + 0.05, 0), JUNCO, Enum.Material.Fabric)\n\t\tcyl(make, 0.62, 0.6, CF(0, y + 0.38, 0), JUNCO, Enum.Material.Fabric)\n\t\tcyl(make, 0.64, 0.14, CF(0, y + 0.2, 0), hex(\"#5d4037\"))\n\telseif hatId == \"panuelo_lenca\" then\n\t\tfor i, c in { \"#7b2cbf\", \"#ffb703\", \"#ff5d9e\" } do\n\t\t\tmake(V3(w + 0.16, 0.14, d + 0.16), CF(0, h / 2 - 0.08 + i * 0.14, 0), hex(c), Enum.Material.Fabric)\n\t\tend\n\t\tmake(V3(0.5, 0.5, 0.3), CF(0, h / 2 + 0.1, d / 2 + 0.2), hex(\"#7b2cbf\"), Enum.Material.Fabric)\n\telseif hatId == \"sombrero_vaquero\" then\n\t\tlocal brown = hex(\"#7a5230\")\n\t\tcyl(make, 1.4, 0.1, CF(0, y + 0.05, 0), brown, Enum.Material.Fabric)\n\t\tmake(V3(w + 0.1, 0.7, d + 0.1), CF(0, y + 0.42, 0), brown, Enum.Material.Fabric)\n\t\tfor _, x in { -1, 1 } do\n\t\t\tmake(V3(0.14, 0.5, 2.2), CF(x * 1.25, y + 0.22, 0) * ANG(0, 0, rad(-x * 30)), brown, Enum.Material.Fabric)\n\t\tend\n\telseif hatId == \"casco_explorador\" then\n\t\tlocal khaki = hex(\"#cbb98a\")\n\t\tcyl(make, 1.02, 0.1, CF(0, y + 0.05, 0), khaki)\n\t\tmake(V3(w + 0.3, w + 0.3, w + 0.3), CF(0, y + 0.25, 0), khaki, nil, Enum.PartType.Ball)\n\t\tcyl(make, w / 2 + 0.18, 0.14, CF(0, y + 0.16, 0), hex(\"#6b4a2b\"))\n\telseif hatId == \"corona_carnaval\" then\n\t\tlocal gold = hex(\"#ffd700\")\n\t\tcyl(make, w / 2 + 0.05, 0.3, CF(0, y + 0.15, 0), gold, Enum.Material.Metal)\n\t\tlocal gems = { \"#e63946\", \"#00a3d7\", \"#2ea44f\", \"#ff5d9e\", \"#7b5cff\", \"#ff7a3d\" }\n\t\tfor i = 0, 5 do\n\t\t\tlocal a = rad(i * 60)\n\t\t\tlocal r = w / 2\n\t\t\tmake(V3(0.22, 0.6, 0.22), CF(math.sin(a) * r, y + 0.55, math.cos(a) * r), gold, Enum.Material.Metal)\n\t\t\tmake(V3(0.26, 0.26, 0.26), CF(math.sin(a) * r, y + 0.92, math.cos(a) * r), hex(gems[i + 1]), Enum.Material.Neon, Enum.PartType.Ball)\n\t\tend\n\t\tfor i = 0, 2 do\n\t\t\tmake(V3(0.16, 1.5, 0.5), CF((i - 1) * 0.4, y + 1.1, d / 2) * ANG(rad(-20), 0, rad((1 - i) * 22)), hex(gems[i * 2 + 1]), Enum.Material.Fabric)\n\t\tend\n\tend\nend\n\nlocal function sleeves(character: Model, model: Model, color: Color3, long: boolean)\n\tfor _, side in { \"Left\", \"Right\" } do\n\t\tlocal upper = find(character, side .. \"UpperArm\")\n\t\tif upper then\n\t\t\tmaker(model, upper)(upper.Size + V3(0.08, 0.02, 0.08), CF(), color, Enum.Material.Fabric)\n\t\t\tlocal lower = find(character, side .. \"LowerArm\")\n\t\t\tif long and lower then\n\t\t\t\tmaker(model, lower)(lower.Size + V3(0.08, 0.02, 0.08), CF(), color, Enum.Material.Fabric)\n\t\t\tend\n\t\telse\n\t\t\tlocal arm = find(character, side .. \" Arm\")\n\t\t\tif arm then\n\t\t\t\tlocal f = if long then 0.8 else 0.45\n\t\t\t\tmaker(model, arm)(V3(arm.Size.X + 0.08, arm.Size.Y * f, arm.Size.Z + 0.08), CF(0, arm.Size.Y * (1 - f) / 2, 0), color, Enum.Material.Fabric)\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal function buildShirt(character: Model, model: Model, make: Maker, shirtId: string, base: Color3, tw: number, th: number, td: number)\n\tlocal front = -td / 2 - 0.03\n\tsleeves(character, model, base, shirtId == \"guayabera\" or shirtId == \"camisa_manta\")\n\tif shirtId == \"camisa_rayas\" then\n\t\tfor i = -1, 1 do\n\t\t\tmake(V3(tw + 0.06, th * 0.13, td + 0.06), CF(0, i * th * 0.3, 0), WHITE, Enum.Material.Fabric)\n\t\tend\n\telseif shirtId == \"camisa_cuadros\" then\n\t\tlocal dark = base:Lerp(BLACK, 0.4)\n\t\tfor _, x in { -0.3, 0.3 } do\n\t\t\tmake(V3(0.12, th + 0.02, td + 0.06), CF(x * tw, 0, 0), dark, Enum.Material.Fabric)\n\t\tend\n\t\tfor _, y in { -0.25, 0.25 } do\n\t\t\tmake(V3(tw + 0.06, 0.12, td + 0.06), CF(0, y * th, 0), dark, Enum.Material.Fabric)\n\t\tend\n\telseif shirtId == \"camisa_504\" then\n\t\tplate(make, V3(tw * 0.8, th * 0.6, 0.04), CF(0, 0, front), \"504\", WHITE, Enum.NormalId.Front)\n\telseif shirtId == \"camisa_h\" or shirtId == \"camisa_h_azul\" then\n\t\tlocal ink = if shirtId == \"camisa_h\" then hex(\"#0d47a1\") else WHITE\n\t\tplate(make, V3(tw * 0.6, th * 0.6, 0.04), CF(0, -th * 0.05, front), \"H\", ink, Enum.NormalId.Front)\n\t\tplate(make, V3(tw * 0.5, th * 0.5, 0.04), CF(0, 0, td / 2 + 0.03), \"15\", ink, Enum.NormalId.Back)\n\t\tmake(V3(tw * 0.5, 0.12, td + 0.06), CF(0, th / 2 - 0.06, 0), ink, Enum.Material.Fabric)\n\telseif shirtId == \"guayabera\" then\n\t\tfor _, x in { -0.24, 0.24 } do\n\t\t\tmake(V3(0.1, th, 0.05), CF(x * tw, 0, front), hex(\"#d8d2c2\"), Enum.Material.Fabric)\n\t\tend\n\t\tfor i = -1, 1 do\n\t\t\tmake(V3(0.1, 0.1, 0.05), CF(0, i * th * 0.28, front), hex(\"#c9c2b0\"))\n\t\tend\n\telseif shirtId == \"camisa_manta\" then\n\t\tmake(V3(tw + 0.06, 0.16, td + 0.06), CF(0, th / 2 - 0.08, 0), hex(\"#e63946\"), Enum.Material.Fabric)\n\t\tmake(V3(0.34, th * 0.7, 0.05), CF(0, th * 0.1, front), hex(\"#e63946\"), Enum.Material.Fabric)\n\t\tmake(V3(0.14, th * 0.7, 0.06), CF(0, th * 0.1, front - 0.01), hex(\"#ffc93c\"), Enum.Material.Fabric)\n\telseif shirtId == \"blusa_tipica\" then\n\t\tfor i, c in { \"#e63946\", \"#ffc93c\", \"#2ea44f\" } do\n\t\t\tmake(V3(tw + 0.1 + i * 0.04, 0.13, td + 0.1 + i * 0.04), CF(0, th / 2 - 0.02 - i * 0.14, 0), hex(c), Enum.Material.Fabric)\n\t\tend\n\t\tfor _, x in { -1, 1 } do\n\t\t\tmake(V3(0.9, 0.9, 0.9), CF(x * (tw / 2 + 0.25), th / 2 - 0.3, 0), WHITE, Enum.Material.Fabric, Enum.PartType.Ball)\n\t\tend\n\tend\nend\n\nlocal function buildPants(character: Model, model: Model, pantsId: string, color: Color3)\n\tlocal hips = find(character, \"LowerTorso\")\n\tlocal torso = find(character, \"Torso\")\n\tif pantsId == \"falda_tipica\" then\n\t\tlocal base = hips or torso\n\t\tif base then\n\t\t\tlocal make = maker(model, base)\n\t\t\tlocal y0 = if hips then 0 else -base.Size.Y / 2\n\t\t\tfor i, c in { \"#e63946\", \"#ffc93c\", \"#00a3d7\", \"#2ea44f\" } do\n\t\t\t\tcyl(make, 0.95 + i * 0.16, 0.36, CF(0, y0 - (i - 1) * 0.36, 0), hex(c), Enum.Material.Fabric)\n\t\t\tend\n\t\tend\n\t\treturn\n\tend\n\tif hips then\n\t\tmaker(model, hips)(hips.Size + V3(0.06, 0.02, 0.06), CF(), color, Enum.Material.Fabric)\n\tend\n\tif pantsId == \"short_futbol\" then\n\t\tfor _, side in { \"Left\", \"Right\" } do\n\t\t\tlocal upper = find(character, side .. \"UpperLeg\")\n\t\t\tif upper then\n\t\t\t\tmaker(model, upper)(upper.Size + V3(0.1, 0, 0.1), CF(), color, Enum.Material.Fabric)\n\t\t\telse\n\t\t\t\tlocal leg = find(character, side .. \" Leg\")\n\t\t\t\tif leg then\n\t\t\t\t\tmaker(model, leg)(V3(leg.Size.X + 0.08, leg.Size.Y * 0.45, leg.Size.Z + 0.08), CF(0, leg.Size.Y * 0.275, 0), color, Enum.Material.Fabric)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal function buildAccessory(make: Maker, accId: string, tint: Color3, tw: number, th: number, td: number)\n\tlocal front, back = -td / 2, td / 2\n\tif accId == \"mochila\" then\n\t\tmake(V3(tw * 0.72, th * 0.9, 0.6), CF(0, 0, back + 0.32), tint, Enum.Material.Fabric)\n\t\tmake(V3(tw * 0.5, th * 0.35, 0.2), CF(0, -th * 0.2, back + 0.7), tint:Lerp(BLACK, 0.3), Enum.Material.Fabric)\n\t\tfor _, x in { -0.3, 0.3 } do\n\t\t\tmake(V3(0.16, th, 0.06), CF(x * tw, 0, front - 0.04), tint:Lerp(BLACK, 0.3), Enum.Material.Fabric)\n\t\tend\n\telseif accId == \"banda_bandera\" then\n\t\tfor _, z in { front - 0.05, back + 0.05 } do\n\t\t\tlocal flip = if z < 0 then 1 else -1\n\t\t\tfor i, c in { FLAG_BLUE, WHITE, FLAG_BLUE } do\n\t\t\t\tmake(V3(0.17, th * 1.5, 0.05), CF(0, 0, z) * ANG(0, 0, rad(flip * 42)) * CF((i - 2) * 0.17, 0, 0), c, Enum.Material.Fabric)\n\t\t\tend\n\t\tend\n\telseif accId == \"collar_jade\" then\n\t\tfor i = -3, 3 do\n\t\t\tlocal y = th / 2 - 0.12 - (9 - i * i) * 0.045\n\t\t\tmake(V3(0.2, 0.2, 0.2), CF(i * tw * 0.1, y, front - 0.08), hex(\"#1faa59\"), Enum.Material.Glass, Enum.PartType.Ball)\n\t\tend\n\telseif accId == \"guitarra\" then\n\t\tlocal tilt = CF(0, 0, back + 0.25) * ANG(0, 0, rad(35))\n\t\tlocal wood = hex(\"#c98f5f\")\n\t\tcyl(make, 0.62, 0.22, tilt * CF(0, -0.5, 0) * ANG(rad(90), 0, 0), wood, Enum.Material.Wood)\n\t\tcyl(make, 0.46, 0.22, tilt * CF(0, 0.2, 0) * ANG(rad(90), 0, 0), wood, Enum.Material.Wood)\n\t\tmake(V3(0.2, 1.5, 0.14), tilt * CF(0, 1.2, 0), hex(\"#5d4037\"), Enum.Material.Wood)\n\t\tcyl(make, 0.2, 0.24, tilt * CF(0, -0.3, 0) * ANG(rad(90), 0, 0), BLACK)\n\telseif accId == \"tambor_garifuna\" then\n\t\tlocal at = CF(-tw * 0.35, -th * 0.55, front - 0.5)\n\t\tcyl(make, 0.5, 0.9, at, hex(\"#8d5a2b\"), Enum.Material.Wood)\n\t\tcyl(make, 0.52, 0.08, at * CF(0, 0.48, 0), hex(\"#f3e6c8\"))\n\t\tcyl(make, 0.53, 0.1, at * CF(0, 0.2, 0), hex(\"#e63946\"))\n\t\tmake(V3(0.1, th * 1.3, 0.05), CF(0, 0.1, front - 0.04) * ANG(0, 0, rad(-38)), hex(\"#ffc93c\"), Enum.Material.Fabric)\n\telseif accId == \"capa_bandera\" then\n\t\tlocal at = CF(0, -0.9, back + 0.12) * ANG(rad(-8), 0, 0)\n\t\tlocal h = th + 1.9\n\t\tmake(V3(tw * 1.05, h / 3, 0.08), at * CF(0, h / 3, 0), FLAG_BLUE, Enum.Material.Fabric)\n\t\tmake(V3(tw * 1.05, h / 3, 0.08), at * CF(0, -h / 3, 0), FLAG_BLUE, Enum.Material.Fabric)\n\t\tmake(V3(tw * 1.05, h / 3, 0.08), at, WHITE, Enum.Material.Fabric)\n\t\tplate(make, V3(tw * 1.05, h / 3, 0.04), at * CF(0, 0, 0.07), \"★ ★ ★ ★ ★\", FLAG_BLUE, Enum.NormalId.Back)\n\tend\nend\n\n-- Aplica el avatar del perfil al personaje. Se puede llamar las veces que haga falta.\nfunction Outfit.apply(character: Model, avatar: Types.Avatar)\n\tlocal head = find(character, \"Head\")\n\tlocal torso = find(character, \"UpperTorso\", \"Torso\")\n\tif not head or not torso then\n\t\treturn\n\tend\n\tlocal old = character:FindFirstChild(\"Atuendo\")\n\tif old then\n\t\told:Destroy()\n\tend\n\tfor _, child in character:GetChildren() do\n\t\tif child:IsA(\"Accessory\") or child:IsA(\"Shirt\") or child:IsA(\"Pants\") or child:IsA(\"ShirtGraphic\") or child:IsA(\"CharacterMesh\") then\n\t\t\tchild:Destroy()\n\t\tend\n\tend\n\n\tlocal skin = hex(avatar.skin)\n\tlocal shirt = FIXED_SHIRT[avatar.shirt] or hex(avatar.shirtColor)\n\tlocal pants = FIXED_PANTS[avatar.pants] or hex(avatar.pantsColor)\n\tlocal bareLegs = avatar.pants == \"short_futbol\" or avatar.pants == \"falda_tipica\"\n\tsetBodyColors(character, skin, shirt, if bareLegs then skin else pants)\n\n\tlocal model = Instance.new(\"Model\")\n\tmodel.Name = \"Atuendo\"\n\tmodel.Parent = character\n\n\t-- medidas visibles de la cabeza (en R6 la malla es más angosta que la pieza)\n\tlocal w = math.min(head.Size.X, 1.3)\n\tlocal h = math.max(head.Size.Y, 1.2)\n\tlocal d = math.max(head.Size.Z, 1.2)\n\tlocal onHead = maker(model, head)\n\tbuildFace(onHead, head, avatar.face, w, h, d)\n\tbuildHair(onHead, avatar.hair, hex(avatar.hairColor), w, h, d)\n\tbuildHat(onHead, avatar.hat, hex(avatar.hatColor), w, h, d)\n\n\tlocal tw, th, td = torso.Size.X, torso.Size.Y, torso.Size.Z\n\tlocal onTorso = maker(model, torso)\n\tbuildShirt(character, model, onTorso, avatar.shirt, shirt, tw, th, td)\n\tbuildPants(character, model, avatar.pants, pants)\n\tbuildAccessory(onTorso, avatar.acc, hex(avatar.accColor), tw, th, td)\nend\n\nreturn Outfit\n"},{"path":"src/server/Main.server.luau","code":"--!strict\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Shared\")\nlocal Net = require(Shared.Net)\nlocal Services = script.Parent.Services\nlocal Guard = require(Services.Guard)\nlocal Data = require(Services.DataService)\nlocal Progress = require(Services.ProgressService)\nlocal World = require(Services.WorldService)\nNet.setup()\nGuard.start()\nProgress.start()\nWorld.build()\nWorld.start()\nrequire(Services.AvatarService).start()\nrequire(Services.ShopService).start()\nrequire(Services.LeaderboardService).start()\nrequire(Services.EmoteService).start()\nrequire(Services.RoomService).start()\nrequire(Services.MinigameService).start()\nGuard.onInvoke(Net.Functions.GetProfile, 0.5, 2, function(player)\n\tlocal profile = Data.waitFor(player, 20)\n\treturn { ok = profile ~= nil, profile = profile }\nend)\nData.start()\nprint(\"Mundo Catrucho listo. ¡Dale viaje!\")\n"},{"path":"src/server/Minigames/Carrera.luau","code":"--!nonstrict\nlocal Players = game:GetService(\"Players\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Shared = game:GetService(\"ReplicatedStorage\").Shared\nlocal Config = require(Shared.Config)\nlocal Sanity = require(Shared.Logic.Sanity)\nlocal Build = require(script.Parent.Parent.World.Build)\nlocal World = require(script.Parent.Parent.Services.WorldService)\nlocal Carrera = { id = \"carrera\" }\nlocal origin = Config.World.Carrera\nlocal V, CF = Vector3.new, CFrame.new\nlocal checkpoints = {}\nlocal service\nlocal function position(index) return origin + V(0, 4, -index * 120) end\nfunction Carrera.setup(s)\n\tservice = s\n\tlocal model = Build.model(World.root(), \"CarreraCatrucha\")\n\tBuild.part(model, V(22, 2, 25), CF(origin), Build.C.blue)\n\tBuild.sign(model, CF(origin + V(16, 0, 0)), 18, 6, \"Carrera Catrucha\\nSaltá y seguí los puestos azules\", nil, 2)\n\tfor i = 1, 40 do\n\t\tlocal z = -i * 12\n\t\tlocal x = if i % 10 == 0 then 0 else math.sin(i * 1.1) * 4\n\t\tlocal p = Build.part(model, V(12, 2, 8), CF(origin + V(x, 0, z)), if i % 10 == 0 then Build.C.blue else Build.C.asphalt)\n\t\tif i % 10 == 0 then\n\t\t\tlocal cp = i / 10\n\t\t\tcheckpoints[cp] = p\n\t\t\tBuild.label(p, if cp == 4 then \"¡META!\" else `Puesto {cp}`, 7)\n\t\t\tp.Touched:Connect(function(hit)\n\t\t\t\tlocal player = Players:GetPlayerFromCharacter(hit.Parent)\n\t\t\t\tlocal run = player and s.runs[player]\n\t\t\t\tif not run or run.id ~= Carrera.id or cp ~= run.checkpoint + 1 then return end\n\t\t\t\tif not World.isNear(player, p.Position, 14) or os.clock() - run.segmentAt < Sanity.minTravelTime(120) then return end\n\t\t\t\trun.checkpoint = cp\n\t\t\t\trun.segmentAt = os.clock()\n\t\t\t\trun.hud = { hint = `Puesto {cp}/4` }\n\t\t\t\tif cp == 4 then s.finish(player, { finished = true, time = os.clock() - run.started }) end\n\t\t\tend)\n\t\telseif i % 7 == 0 then\n\t\t\tlocal tween = TweenService:Create(p, TweenInfo.new(2.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { CFrame = p.CFrame + V(5, 0, 0) })\n\t\t\ttween:Play()\n\t\tend\n\t\tif i % 5 == 0 and i % 10 ~= 0 then\n\t\t\tlocal hazard = Build.part(model, V(2, 1, 7), CF(origin + V(x + 4, 1.5, z)), Build.C.red, Enum.Material.Neon)\n\t\t\thazard.Touched:Connect(function(hit)\n\t\t\t\tlocal player = Players:GetPlayerFromCharacter(hit.Parent)\n\t\t\t\tlocal run = player and s.runs[player]\n\t\t\t\tif run and run.id == Carrera.id then\n\t\t\t\t\tWorld.teleport(player, CF(position(run.checkpoint)), \"carrera\")\n\t\t\t\t\trun.sample = position(run.checkpoint); run.sampleAt = os.clock()\n\t\t\t\tend\n\t\t\tend)\n\t\tend\n\t\tif i % 4 == 0 then\n\t\t\tfor _, side in { -1, 1 } do Build.house(model, CF(origin + V(side * 24, -8, z)), 13, 12, 16, if side == 1 then Build.C.yellow else Build.C.pink) end\n\t\tend\n\tend\n\tRunService.Heartbeat:Connect(function()\n\t\tfor player, run in s.runs do\n\t\t\tif run.id ~= Carrera.id then continue end\n\t\t\tlocal root = World.rootPart(player)\n\t\t\tif root then\n\t\t\t\tlocal now = os.clock()\n\t\t\t\tlocal delta = now - run.sampleAt\n\t\t\t\tif delta >= 0.15 then\n\t\t\t\t\tlocal flat = (root.Position - run.sample) * V(1, 0, 1)\n\t\t\t\t\tif flat.Magnitude > Config.Limits.MaxRunSpeed * delta + 6 then\n\t\t\t\t\t\trun.invalid = true\n\t\t\t\t\t\ts.cancel(player); World.toLobby(player)\n\t\t\t\t\telse\n\t\t\t\t\t\trun.sample = root.Position; run.sampleAt = now\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\t\tif root.Position.Y < origin.Y - 12 then\n\t\t\t\t\tWorld.teleport(player, CF(position(run.checkpoint)), \"carrera\")\n\t\t\t\t\trun.sample = position(run.checkpoint); run.sampleAt = now\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\nend\nfunction Carrera.begin(player, run)\n\trun.checkpoint = 0; run.segmentAt = os.clock()\n\trun.sample = position(0); run.sampleAt = os.clock()\n\trun.timeout = function() service.finish(player, { finished = false, time = 120 }) end\n\tWorld.teleport(player, CF(position(0)), \"carrera\")\n\treturn true\nend\nreturn Carrera\n"},{"path":"src/server/Minigames/Exploradores.luau","code":"--!nonstrict\nlocal Shared = game:GetService(\"ReplicatedStorage\").Shared\nlocal GameData = require(Shared.GameData)\nlocal Explorer = require(Shared.Content.Explorer)\nlocal Net = require(Shared.Net)\nlocal Build = require(script.Parent.Parent.World.Build)\nlocal World = require(script.Parent.Parent.Services.WorldService)\nlocal Progress = require(script.Parent.Parent.Services.ProgressService)\nlocal Guard = require(script.Parent.Parent.Services.Guard)\nlocal ExplorerGame = { id = \"exploradores\" }\nlocal service\nfunction ExplorerGame.setup(s)\n\tservice = s\n\tfor _, object in Explorer.objects do\n\t\tlocal zone = World.zones[object.site]\n\t\tlocal p = Build.ball(zone.model, 1.8, zone.cframe * CFrame.new(object.offset), Build.C.gold, Enum.Material.Neon, { CanCollide = false })\n\t\tlocal prompt = Build.prompt(p, \"Investigar\", object.name, 0.4, 9)\n\t\tprompt.Triggered:Connect(function(player)\n\t\t\tlocal run = s.runs[player]\n\t\t\tif not run or run.id ~= ExplorerGame.id or run.found[object.id] or os.clock() - run.lastFind < 1 or not World.isNear(player, p.Position, 12) then return end\n\t\t\trun.lastFind = os.clock(); run.found[object.id] = true; run.score += 1\n\t\t\tProgress.commit(player, function(profile) profile.facts[object.id] = true end)\n\t\t\tProgress.toast(player, object.name .. \": \" .. object.fact)\n\t\t\tif run.score == #Explorer.objects then s.finish(player, { found = run.score }) end\n\t\tend)\n\tend\n\tGuard.onInvoke(Net.Functions.ExplorerTravel, 0.5, 2, function(player, site)\n\t\tlocal run = s.runs[player]\n\t\tif not run or run.id ~= ExplorerGame.id or typeof(site) ~= \"string\" or not table.find(GameData.rules(\"exploradores\").sites, site) then return { ok = false } end\n\t\treturn { ok = World.teleport(player, World.zones[site].arrival, \"exploradores\") }\n\tend)\nend\nfunction ExplorerGame.begin(player, run)\n\trun.found = {}; run.lastFind = os.clock(); run.hud = { hint = \"Buscá los objetos dorados · cambiá de sitio en Minijuegos\" }\n\trun.timeout = function() service.finish(player, { found = run.score }) end\n\tWorld.teleport(player, World.zones.copan.arrival, \"exploradores\")\n\treturn true\nend\nreturn ExplorerGame\n"},{"path":"src/server/Minigames/Feria.luau","code":"--!nonstrict\nlocal Shared = game:GetService(\"ReplicatedStorage\").Shared\nlocal Config = require(Shared.Config)\nlocal GameData = require(Shared.GameData)\nlocal Math = require(Shared.Logic.FeriaMath)\nlocal Sanity = require(Shared.Logic.Sanity)\nlocal Net = require(Shared.Net)\nlocal Build = require(script.Parent.Parent.World.Build)\nlocal World = require(script.Parent.Parent.Services.WorldService)\nlocal Guard = require(script.Parent.Parent.Services.Guard)\nlocal Feria = { id = \"feria\" }\nlocal lanes, service = {}, nil\nlocal V, CF = Vector3.new, CFrame.new\nlocal function shotsPerBooth() return GameData.rules(\"feria\").shotsPerBooth end\nlocal function booth(run)\n\treturn GameData.rules(\"feria\").booths[math.floor(run.shots / GameData.rules(\"feria\").shotsPerBooth) + 1]\nend\nlocal function targets(run)\n\tif run.targets then run.targets:Destroy() end\n\trun.targets = Build.model(run.model, \"Blancos\")\n\trun.objects = {}; run.standing = table.create(10, true)\n\tlocal kind = booth(run)\n\tif kind == \"hulera\" then\n\t\tfor i = 1, 3 do\n\t\t\tlocal pos = run.origin + V((i - 2) * 5, 5, -24)\n\t\t\tlocal p = Build.ball(run.targets, 4, CF(pos), if i == 2 then Build.C.red else Build.C.yellow)\n\t\t\ttable.insert(run.objects, p)\n\t\tend\n\telseif kind == \"argollas\" then\n\t\tfor i = 1, 3 do\n\t\t\tlocal p = Build.cyl(run.targets, 0.4, 3, CF(run.origin + V((i - 2) * 4, 1.5, -17)), Build.C.yellow)\n\t\t\ttable.insert(run.objects, p)\n\t\tend\n\telse\n\t\tlocal index = 0\n\t\tfor row, count in Math.CanRows do\n\t\t\tfor i = 1, count do\n\t\t\t\tindex += 1\n\t\t\t\trun.objects[index] = Build.part(run.targets, V(1.6, 2, 1.6), CF(run.origin + V((i - (count + 1) / 2) * 1.8, 1 + (row - 1) * 2, -22)), Build.C.red)\n\t\t\tend\n\t\tend\n\tend\n\trun.hud = { hint = `{kind} · tiro {run.shots % shotsPerBooth() + 1}/{shotsPerBooth()} · apuntá y soltá (fuerza con 1–5)` }\nend\nfunction Feria.setup(s)\n\tservice = s\n\tGuard.onEvent(Net.Events.FeriaShoot, 1 / Config.Limits.ShotCooldown, 1, function(player, direction, power)\n\t\tlocal run = s.runs[player]\n\t\tif not run or run.id ~= Feria.id or not Sanity.isNumber(power) or power < 0 or power > 1 then return end\n\t\tif not World.isNear(player, run.origin + V(0, 4, 0), 9) then return end\n\t\tlocal dir = Sanity.aimDirection(direction, V(0, 0, -1), 0.6)\n\t\tif not dir then return end\n\t\tlocal start = run.origin + V(0, 5, -2)\n\t\tlocal kind = booth(run)\n\t\tlocal points, hitPos = 0, start + dir * 30\n\t\tif kind == \"hulera\" then\n\t\t\tfor _, p in run.objects do\n\t\t\t\tlocal distance, pos = Math.rayDisc(start, dir, p.Position, V(0, 0, 1), 2)\n\t\t\t\tif distance then points = Math.targetPoints(distance, 2, false); hitPos = pos; break end\n\t\t\tend\n\t\telseif kind == \"argollas\" then\n\t\t\tlocal land = Math.ringLanding(start, dir, power, run.origin.Y)\n\t\t\thitPos = land\n\t\t\tfor _, p in run.objects do\n\t\t\t\tlocal delta = (land - p.Position) * V(1, 0, 1)\n\t\t\t\tif delta.Magnitude < 2 then points = 40; break end\n\t\t\tend\n\t\telse\n\t\t\tlocal closest, index = math.huge, nil\n\t\t\tfor i, p in run.objects do\n\t\t\t\tlocal distance = if run.standing[i] then Math.rayBox(start, dir, p.Position, p.Size / 2) else nil\n\t\t\t\tif distance and distance < closest then closest = distance; index = i end\n\t\t\tend\n\t\t\tif index then\n\t\t\t\thitPos = start + dir * closest\n\t\t\t\tfor _, i in Math.cansKnocked(index, run.standing) do run.standing[i] = false; run.objects[i].Transparency = 1; points += 10 end\n\t\t\t\tif not table.find(run.standing, true) and not run.bonus then points += 50; run.bonus = true end\n\t\t\tend\n\t\tend\n\t\tlocal tracer = Build.ball(run.model, 0.6, CF(hitPos), Build.C.gold, Enum.Material.Neon, { CanCollide = false })\n\t\tgame:GetService(\"Debris\"):AddItem(tracer, 0.8)\n\t\trun.score += points; run.shots += 1\n\t\tif run.shots >= #GameData.rules(\"feria\").booths * GameData.rules(\"feria\").shotsPerBooth then\n\t\t\ts.finish(player, { points = run.score })\n\t\telseif run.shots % shotsPerBooth() == 0 then targets(run)\n\t\telse run.hud = { hint = `{booth(run)} · tiro {run.shots % shotsPerBooth() + 1}/{shotsPerBooth()} · +{points} puntos` } end\n\tend)\nend\nfunction Feria.begin(player, run)\n\tlocal lane\n\tfor i = 1, Config.Feria.Lanes do if not lanes[i] then lane = i; break end end\n\tif not lane then return false, \"Los puestos están ocupados. Probá en un ratito.\" end\n\tlanes[lane] = player\n\trun.origin = Config.World.Feria + V(lane * 70, 0, 0)\n\trun.model = Build.model(World.root(), \"Feria_\" .. player.UserId)\n\tBuild.part(run.model, V(36, 2, 44), CF(run.origin + V(0, -1, -13)), Build.C.sand)\n\tBuild.walls(run.model, CF(run.origin + V(0, 0, -13)), 36, 44, 15)\n\tBuild.sign(run.model, CF(run.origin + V(0, 0, -31)), 25, 5, \"Hulera · Argollas · Tumbalatas\", nil, 8)\n\trun.shots = 0\n\trun.cleanup = function() lanes[lane] = nil; run.model:Destroy() end\n\trun.timeout = function() service.finish(player, { points = run.score }) end\n\ttargets(run)\n\tWorld.teleport(player, CF(run.origin + V(0, 4, 0)), \"feria\")\n\treturn true\nend\nreturn Feria\n"},{"path":"src/server/Minigames/Futbol.luau","code":"--!nonstrict\nlocal RunService = game:GetService(\"RunService\")\nlocal Shared = game:GetService(\"ReplicatedStorage\").Shared\nlocal Config = require(Shared.Config)\nlocal GameData = require(Shared.GameData)\nlocal Net = require(Shared.Net)\nlocal Build = require(script.Parent.Parent.World.Build)\nlocal World = require(script.Parent.Parent.Services.WorldService)\nlocal Guard = require(script.Parent.Parent.Services.Guard)\nlocal Futbol = { id = \"futbol\" }\nlocal V, CF = Vector3.new, CFrame.new\nlocal origin = Config.World.Futbol\nlocal players, bots, score = {}, {}, { [1] = 0, [-1] = 0 }\nlocal ball, service, deadline, lastKick, resetUntil\nlocal function resetBall()\n\tball.CFrame = CF(origin + V(0, 4, 0)); ball.AssemblyLinearVelocity = V(0, 0, 0); ball.AssemblyAngularVelocity = V(0, 0, 0)\n\tlastKick = nil; resetUntil = os.clock() + 2\nend\nfunction Futbol.setup(s)\n\tservice = s\n\tlocal m = Build.model(World.root(), \"FutbolDeBarrio\")\n\tBuild.part(m, V(84, 2, 124), CF(origin + V(0, -1, 0)), Build.C.green, Enum.Material.Grass)\n\tBuild.walls(m, CF(origin), 84, 124, 20)\n\tBuild.part(m, V(80, 0.1, 0.4), CF(origin + V(0, 0.1, 0)), Build.C.white)\n\tfor _, side in { -1, 1 } do\n\t\tfor _, x in { -12, 12 } do Build.part(m, V(1, 12, 1), CF(origin + V(x, 6, side * 57)), Build.C.white) end\n\t\tBuild.part(m, V(25, 1, 1), CF(origin + V(0, 12, side * 57)), Build.C.white)\n\t\tBuild.part(m, V(24, 12, 0.5), CF(origin + V(0, 6, side * 61)), Build.C.gray, nil, { Transparency = 0.5 })\n\t\tlocal bot = Build.figure(m, CF(origin + V(0, 0, -side * 24)), { skin = Build.C.cream, shirt = if side == 1 then Build.C.blue else Build.C.red, pants = Build.C.white }, 1, false)\n\t\tBuild.label(bot.PrimaryPart, `Bot {if side == 1 then \"azul\" else \"rojo\"}`, 4)\n\t\ttable.insert(bots, { model = bot, team = side, at = 0 })\n\tend\n\tball = Build.ball(m, 3, CF(origin + V(0, 4, 0)), Build.C.white, nil, { Anchored = false, Name = \"Pelota\", CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.35, 0.7) })\n\tball:SetNetworkOwner(nil)\n\tresetBall()\n\tGuard.onEvent(Net.Events.FutbolKick, 1 / Config.Limits.KickCooldown, 1, function(player)\n\t\tlocal run = s.runs[player]\n\t\tif not run or run.id ~= Futbol.id or os.clock() < resetUntil or not World.isNear(player, ball.Position, Config.Limits.KickDistance) then return end\n\t\tlocal root = World.rootPart(player)\n\t\tlocal dir = root.CFrame.LookVector * V(1, 0, 1)\n\t\tif dir.Magnitude < 0.1 then return end\n\t\tball.AssemblyLinearVelocity = dir.Unit * 65 + V(0, 14, 0)\n\t\tlastKick = player\n\tend)\n\tlocal tickAt = 0\n\tRunService.Heartbeat:Connect(function(dt)\n\t\tif not next(players) then return end\n\t\tlocal now = os.clock()\n\t\tif deadline - now > GameData.rules(\"futbol\").duration then return end\n\t\tif now >= deadline then\n\t\t\tlocal finished = table.clone(players)\n\t\t\tfor player, team in finished do\n\t\t\t\tlocal run = s.runs[player]\n\t\t\t\tif run then s.finish(player, { teamGoals = score[team], rivalGoals = score[-team], goals = run.score }) end\n\t\t\tend\n\t\t\treturn\n\t\tend\n\t\tlocal pos = ball.Position - origin\n\t\tif ball.AssemblyLinearVelocity.Magnitude > 110 or pos.Magnitude > 150 then resetBall(); return end\n\t\tif now >= resetUntil and math.abs(pos.X) < 11 and pos.Y < 12 and math.abs(pos.Z) > 57 then\n\t\t\tlocal team = if pos.Z > 0 then 1 else -1\n\t\t\tscore[team] += 1\n\t\t\tif lastKick and players[lastKick] == team and s.runs[lastKick] then s.runs[lastKick].score += 1 end\n\t\t\tresetBall()\n\t\tend\n\t\tfor _, bot in bots do\n\t\t\tlocal hasHuman = false\n\t\t\tfor _, team in players do if team == bot.team then hasHuman = true end end\n\t\t\tif hasHuman then continue end\n\t\t\tlocal bp = bot.model:GetPivot().Position\n\t\t\tlocal target = V(ball.Position.X, origin.Y, ball.Position.Z - bot.team * 3)\n\t\t\tlocal delta = target - bp\n\t\t\tif delta.Magnitude > 0.1 then bot.model:PivotTo(CFrame.lookAt(bp + delta.Unit * math.min(delta.Magnitude, dt * 12), target + V(0, 0, bot.team * 0.01))) end\n\t\t\tif (ball.Position - bp).Magnitude < 7 and now > bot.at and now >= resetUntil then\n\t\t\t\tlocal goal = origin + V(math.random(-7, 7), 3, bot.team * 60)\n\t\t\t\tball.AssemblyLinearVelocity = (goal - ball.Position).Unit * 48 + V(0, 7, 0)\n\t\t\t\tlastKick = nil; bot.at = now + 1.4\n\t\t\tend\n\t\tend\n\t\tif now - tickAt > 0.5 then\n\t\t\ttickAt = now\n\t\t\tfor player, team in players do\n\t\t\t\tlocal run = s.runs[player]\n\t\t\t\tif run then run.hud = { hint = `Azul {score[1]} : {score[-1]} Rojo · sos {if team == 1 then \"azul\" else \"rojo\"}` } end\n\t\t\tend\n\t\tend\n\tend)\nend\nlocal function beginRound(player, run)\n\tif next(players) then return false, \"La potra ya empezó. Entrá al terminar (2 minutos).\" end\n\t-- Ventana de ingreso: el primer jugador espera ocho segundos.\n\tdeadline = os.clock() + Config.Futbol.WaitSeconds + GameData.rules(\"futbol\").duration\n\tscore = { [1] = 0, [-1] = 0 }\n\tresetBall()\n\tFutbol.join(player, run)\n\treturn true\nend\nfunction Futbol.join(player, run)\n\tlocal counts = { [1] = 0, [-1] = 0 }\n\tfor _, t in players do counts[t] += 1 end\n\tlocal team = if counts[1] <= counts[-1] then 1 else -1\n\tplayers[player] = team\n\trun.deadline = deadline + 1\n\trun.cleanup = function() players[player] = nil end\n\trun.timeout = function() service.finish(player, { teamGoals = score[team], rivalGoals = score[-team], goals = run.score }) end\n\tWorld.teleport(player, CF(origin + V(counts[team] * 6, 4, -team * 24)) * CFrame.Angles(0, if team == 1 then math.pi else 0, 0), \"futbol\")\nend\n-- Permite entrar durante la espera, con equipos equilibrados.\nfunction Futbol.begin(player, run)\n\tif next(players) and deadline - os.clock() > GameData.rules(\"futbol\").duration then\n\t\tlocal n = 0; for _ in players do n += 1 end\n\t\tif n >= Config.Futbol.MaxPlayers then return false, \"La cancha está llena.\" end\n\t\tFutbol.join(player, run); return true\n\tend\n\treturn beginRound(player, run)\nend\nreturn Futbol\n"},{"path":"src/server/Minigames/Pulperia.luau","code":"--!nonstrict\nlocal Shared = game:GetService(\"ReplicatedStorage\").Shared\nlocal Config = require(Shared.Config)\nlocal Build = require(script.Parent.Parent.World.Build)\nlocal World = require(script.Parent.Parent.Services.WorldService)\nlocal Progress = require(script.Parent.Parent.Services.ProgressService)\nlocal Pulperia = { id = \"pulperia\" }\nlocal goods = { \"Baleada\", \"Semita\", \"Fresco\", \"Tajadas\" }\nlocal stations, service = {}, nil\nfunction Pulperia.setup(s) service = s end\nfunction Pulperia.begin(player, run)\n\tlocal station\n\tfor i = 1, Config.Pulperia.Stations do if not stations[i] then station = i; break end end\n\tif not station then return false, \"La pulpería está llena.\" end\n\tstations[station] = player\n\tlocal origin = Config.World.Pulperia + Vector3.new(station * 70, 0, 0)\n\tlocal m = Build.model(World.root(), \"Turno_\" .. player.UserId)\n\tBuild.part(m, Vector3.new(46, 2, 42), CFrame.new(origin + Vector3.new(0, -1, 0)), Build.C.cream)\n\tBuild.figure(m, CFrame.new(origin + Vector3.new(0, 0, -13)), { skin = Build.C.cream, shirt = Build.C.pink, pants = Build.C.blue })\n\trun.order = math.random(1, #goods); run.orderAt = os.clock()\n\tlocal function order()\n\t\trun.order = math.random(1, #goods); run.orderAt = os.clock()\n\t\trun.hud = { hint = \"Cliente: \" .. goods[run.order] .. \" · tenés 14 segundos\" }\n\tend\n\tfor i, name in goods do\n\t\tlocal p = Build.part(m, Vector3.new(7, 3, 4), CFrame.new(origin + Vector3.new((i - 2.5) * 10, 1.5, 4)), Build.C.yellow)\n\t\tBuild.label(p, name, 4)\n\t\tBuild.prompt(p, \"Servir\", name, 0.3, 10).Triggered:Connect(function(visitor)\n\t\t\tif visitor ~= player or service.runs[player] ~= run or not World.isNear(player, p.Position, 14) then return end\n\t\t\tlocal elapsed = os.clock() - run.orderAt\n\t\t\tif elapsed < 2 then return end\n\t\t\tif i == run.order and elapsed <= Config.Pulperia.Patience then run.score += 20\n\t\t\telse Progress.toast(player, \"Ese pedido no era, ¡pilas!\") end\n\t\t\torder()\n\t\tend)\n\tend\n\torder()\n\trun.cleanup = function() stations[station] = nil; m:Destroy() end\n\trun.timeout = function() service.finish(player, { points = run.score }) end\n\tWorld.teleport(player, CFrame.new(origin + Vector3.new(0, 4, 12)), \"pulperia\")\n\treturn true\nend\nreturn Pulperia\n"},{"path":"src/server/Services/AvatarService.luau","code":"--!strict\n-- Aplica en el servidor el avatar guardado (ropa, cabello, accesorios) cada vez que aparece el personaje.\nlocal PhysicsService = game:GetService(\"PhysicsService\")\nlocal Players = game:GetService(\"Players\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal DataService = require(script.Parent.DataService)\nlocal Outfit = require(script.Parent.Parent.Avatar.Outfit)\n\nlocal AvatarService = {}\n\nlocal GROUP = \"Jugadores\"\n\nlocal function setGroup(instance: Instance)\n\tif instance:IsA(\"BasePart\") then\n\t\tinstance.CollisionGroup = GROUP\n\tend\nend\n\nfunction AvatarService.refresh(player: Player)\n\tlocal character = player.Character\n\tlocal profile = DataService.get(player)\n\tif character and profile and character:FindFirstChild(\"Head\") then\n\t\tlocal ok, err = pcall(function(): any return Outfit.apply(character, profile.avatar) end)\n\t\tif not ok then\n\t\t\twarn(`[Avatar] No se pudo vestir a {player.Name}: {err}`)\n\t\tend\n\tend\nend\n\nlocal function onCharacter(player: Player, character: Model)\n\tfor _, d in character:GetDescendants() do\n\t\tsetGroup(d)\n\tend\n\tcharacter.DescendantAdded:Connect(setGroup)\n\tif not DataService.waitFor(player, 20) then\n\t\treturn\n\tend\n\tcharacter:WaitForChild(\"Humanoid\", 10)\n\tcharacter:WaitForChild(\"Head\", 10)\n\tif not character:IsDescendantOf(Workspace) then\n\t\tcharacter.AncestryChanged:Wait()\n\tend\n\ttask.wait(0.1)\n\tif player.Character == character then\n\t\tAvatarService.refresh(player)\n\tend\nend\n\nlocal function onPlayer(player: Player)\n\tplayer.CharacterAdded:Connect(function(character)\n\t\tonCharacter(player, character)\n\tend)\n\tif player.Character then\n\t\ttask.spawn(onCharacter, player, player.Character)\n\tend\nend\n\nfunction AvatarService.start()\n\t-- los jugadores no chocan entre sí: nadie puede empujar a otro en la carrera\n\tpcall(function()\n\t\tPhysicsService:RegisterCollisionGroup(GROUP)\n\t\tPhysicsService:CollisionGroupSetCollidable(GROUP, GROUP, false)\n\tend)\n\tPlayers.PlayerAdded:Connect(onPlayer)\n\tfor _, player in Players:GetPlayers() do\n\t\tonPlayer(player)\n\tend\nend\n\nreturn AvatarService\n"},{"path":"src/server/Services/DataService.luau","code":"--!strict\n-- PlayerData: carga y guarda perfiles en DataStore con pcall, reintentos, caché de sesión,\n-- autoguardado y BindToClose. Si Studio no tiene acceso a la API, sigue en memoria.\nlocal DataStoreService = game:GetService(\"DataStoreService\")\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Config = require(Shared.Config)\nlocal Types = require(Shared.Types)\nlocal Profiles = require(Shared.Logic.Profiles)\n\nlocal DataService = {}\n\ntype Session = { profile: Types.Profile, dirty: boolean, saving: boolean, canSave: boolean }\n\nlocal sessions: { [Player]: Session } = {}\nlocal loadedCallbacks: { (Player, Types.Profile) -> () } = {}\nlocal store: DataStore? = nil\nlocal memoryOnly = false\nlocal memory: { [string]: any } = {} -- respaldo en memoria (solo dura lo que dure el servidor)\nlocal started = false\n\nlocal function key(userId: number): string\n\treturn \"u_\" .. userId\nend\n\nlocal function goMemory(reason: any)\n\tif not memoryOnly then\n\t\tmemoryOnly = true\n\t\twarn(`[Datos] DataStore no disponible, se usa memoria: {reason}`)\n\tend\nend\n\nlocal function getStore(): DataStore?\n\tif memoryOnly then\n\t\treturn nil\n\tend\n\tif not store then\n\t\tlocal ok, result = pcall(function()\n\t\t\treturn DataStoreService:GetDataStore(Config.DataStore.Name)\n\t\tend)\n\t\tif ok then\n\t\t\tstore = result\n\t\telse\n\t\t\tgoMemory(result)\n\t\tend\n\tend\n\treturn store\nend\n\nlocal function waitForBudget(requestType: Enum.DataStoreRequestType)\n\tlocal deadline = os.clock() + 8\n\twhile os.clock() < deadline do\n\t\tlocal ok, budget = pcall(function()\n\t\t\treturn DataStoreService:GetRequestBudgetForRequestType(requestType)\n\t\tend)\n\t\tif not ok or budget > 0 then\n\t\t\treturn\n\t\tend\n\t\ttask.wait(0.5)\n\tend\nend\n\n-- Reintenta con espera creciente. En Studio, el primer fallo pasa a modo memoria.\nlocal function retry(label: string, fn: (attempt: number) -> ()): (boolean, any)\n\tlocal lastErr: any = nil\n\tfor attempt = 1, Config.DataStore.Retries do\n\t\tlocal ok, err = pcall(function(): any return fn(attempt) end)\n\t\tif ok then\n\t\t\treturn true, nil\n\t\tend\n\t\tlastErr = err\n\t\tif RunService:IsStudio() then\n\t\t\tbreak\n\t\tend\n\t\twarn(`[Datos] {label} intento {attempt}: {err}`)\n\t\ttask.wait(attempt * 1.5)\n\tend\n\treturn false, lastErr\nend\n\nlocal function clone(value: any): any\n\tif typeof(value) ~= \"table\" then\n\t\treturn value\n\tend\n\tlocal out = {}\n\tfor k, v in value do\n\t\tout[k] = clone(v)\n\tend\n\treturn out\nend\n\n-- Lee el perfil y toma el candado de sesión. Devuelve (ok, datos crudos).\nlocal function load(userId: number): (boolean, any)\n\tlocal s = getStore()\n\tif not s then\n\t\treturn true, clone(memory[key(userId)])\n\tend\n\tlocal raw: any = nil\n\tlocal ok, err = retry(\"cargar\", function(_attempt)\n\t\tlocal busy = false\n\t\twaitForBudget(Enum.DataStoreRequestType.UpdateAsync)\n\t\ts:UpdateAsync(key(userId), function(old: any): any\n\t\t\tlocal lock = if typeof(old) == \"table\" then old.lock else nil\n\t\t\tlocal fresh = typeof(lock) == \"table\" and os.time() - (lock.at or 0) < Config.DataStore.LockSeconds\n\t\t\t-- Nunca tomar una sesión activa.\n\t\t\tif fresh and lock.job ~= game.JobId  then\n\t\t\t\tbusy = true\n\t\t\t\treturn nil\n\t\t\tend\n\t\t\tbusy = false\n\t\t\tlocal doc = if typeof(old) == \"table\" then old else {}\n\t\t\tdoc.lock = { job = game.JobId, at = os.time() }\n\t\t\traw = doc.data\n\t\t\treturn doc\n\t\tend)\n\t\tif busy then\n\t\t\terror(\"perfil en uso por otro servidor\")\n\t\tend\n\tend)\n\tif not ok and RunService:IsStudio() then\n\t\tgoMemory(err)\n\t\treturn true, clone(memory[key(userId)])\n\tend\n\treturn ok, raw\nend\n\nlocal function save(player: Player, release: boolean): boolean\n\tlocal session = sessions[player]\n\tif not session or not session.canSave then\n\t\treturn false\n\tend\n\twhile session.saving do\n\t\ttask.wait(0.1)\n\tend\n\tsession.saving = true\n\tsession.dirty = false\n\tsession.profile.lastSeen = os.time()\n\tlocal data = clone(session.profile)\n\tlocal s = getStore()\n\tlocal ok = true\n\tif not s then\n\t\tmemory[key(player.UserId)] = data\n\telse\n\t\tlocal err\n\t\tok, err = retry(\"guardar\", function()\n\t\t\twaitForBudget(Enum.DataStoreRequestType.UpdateAsync)\n\t\t\ts:UpdateAsync(key(player.UserId), function(old: any): any\n\t\t\t\tlocal lock = if typeof(old) == \"table\" then old.lock else nil\n\t\t\t\tif typeof(lock) == \"table\" and lock.job ~= game.JobId then\n\t\t\t\t\terror(\"candado de sesión perdido\")\n\t\t\t\tend\n\t\t\t\treturn {\n\t\t\t\t\tdata = data,\n\t\t\t\t\tlock = if release then nil else { job = game.JobId, at = os.time() },\n\t\t\t\t\tversion = Config.ProfileVersion,\n\t\t\t\t}\n\t\t\tend)\n\t\tend)\n\t\tif not ok then\n\t\t\tsession.dirty = true\n\t\t\twarn(`[Datos] No se pudo guardar a {player.Name}: {err}`)\n\t\t\tif RunService:IsStudio() then\n\t\t\t\tgoMemory(err)\n\t\t\t\tmemory[key(player.UserId)] = data\n\t\t\t\tok = true\n\t\t\tend\n\t\tend\n\tend\n\tsession.saving = false\n\treturn ok\nend\n\nlocal function onPlayerAdded(player: Player)\n\tif sessions[player] then\n\t\treturn\n\tend\n\tlocal ok, raw = load(player.UserId)\n\tif not player:IsDescendantOf(Players) then\n\t\treturn -- se fue mientras cargaba\n\tend\n\tif not ok then\n\t\tplayer:Kick(\"No pudimos cargar tus datos. Entrá de nuevo en un ratito para no perder tu progreso.\")\n\t\treturn\n\tend\n\tlocal profile = Profiles.reconcile(raw, os.time())\n\tlocal session: Session = { profile = profile, dirty = raw == nil, saving = false, canSave = true }\n\tsessions[player] = session\n\tfor _, callback in loadedCallbacks do\n\t\ttask.spawn(callback, player, profile)\n\tend\nend\n\nlocal function onPlayerRemoving(player: Player)\n\tif sessions[player] then\n\t\tsave(player, true)\n\t\tsessions[player] = nil\n\tend\nend\n\nfunction DataService.get(player: Player): Types.Profile?\n\tlocal session = sessions[player]\n\treturn if session then session.profile else nil\nend\n\n-- Espera a que el perfil esté cargado (o a que el jugador se vaya).\nfunction DataService.waitFor(player: Player, timeout: number?): Types.Profile?\n\tlocal deadline = os.clock() + (timeout or 20)\n\twhile not sessions[player] and player:IsDescendantOf(Players) and os.clock() < deadline do\n\t\ttask.wait(0.1)\n\tend\n\treturn DataService.get(player)\nend\n\nfunction DataService.markDirty(player: Player)\n\tlocal session = sessions[player]\n\tif session then\n\t\tsession.dirty = true\n\tend\nend\n\nfunction DataService.onLoaded(callback: (Player, Types.Profile) -> ())\n\ttable.insert(loadedCallbacks, callback)\n\tfor player, session in sessions do\n\t\ttask.spawn(callback, player, session.profile)\n\tend\nend\n\nfunction DataService.isMemoryOnly(): boolean\n\treturn memoryOnly\nend\n\nfunction DataService.saveNow(player: Player): boolean\n\treturn save(player, false)\nend\n\nfunction DataService.saveAll(release: boolean)\n\tlocal pending = 0\n\tfor player in sessions do\n\t\tpending += 1\n\t\ttask.spawn(function()\n\t\t\tsave(player, release)\n\t\t\tpending -= 1\n\t\tend)\n\tend\n\tlocal deadline = os.clock() + 25\n\twhile pending > 0 and os.clock() < deadline do\n\t\ttask.wait(0.1)\n\tend\nend\n\nfunction DataService.start()\n\tif started then\n\t\treturn\n\tend\n\tstarted = true\n\tPlayers.PlayerAdded:Connect(onPlayerAdded)\n\tPlayers.PlayerRemoving:Connect(onPlayerRemoving)\n\tfor _, player in Players:GetPlayers() do\n\t\ttask.spawn(onPlayerAdded, player)\n\tend\n\n\t-- autoguardado escalonado de los perfiles con cambios\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(Config.DataStore.AutosaveSeconds)\n\t\t\tfor player, session in sessions do\n\t\t\t\tif session.canSave then\n\t\t\t\t\ttask.spawn(save, player, false)\n\t\t\t\t\ttask.wait(0.3)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend)\n\n\tgame:BindToClose(function()\n\t\tDataService.saveAll(true)\n\tend)\nend\n\nreturn DataService\n"},{"path":"src/server/Services/EmoteService.luau","code":"--!strict\n-- Emotes: el servidor valida que el jugador tenga el emote y avisa a todos los clientes,\n-- que son los que animan al personaje (animación por código, sin assets).\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Config = require(Shared.Config)\nlocal Net = require(Shared.Net)\nlocal Profiles = require(Shared.Logic.Profiles)\nlocal Guard = require(script.Parent.Guard)\nlocal ProgressService = require(script.Parent.ProgressService)\nlocal WorldService = require(script.Parent.WorldService)\n\nlocal EmoteService = {}\n\nfunction EmoteService.play(player: Player, emoteId: string)\n\tNet.event(\"EmotePlay\"):FireAllClients(player.UserId, emoteId)\nend\n\nfunction EmoteService.start()\n\tlocal rate = 1 / Config.Limits.EmoteCooldown\n\tGuard.onEvent(Net.Events.EmoteRequest, rate, 2, function(player, emoteId)\n\t\tif not WorldService.isAlive(player) then\n\t\t\treturn\n\t\tend\n\t\tlocal ok = false\n\t\tProgressService.commit(player, function(profile)\n\t\t\tok = Profiles.useEmote(profile, emoteId)\n\t\tend)\n\t\tif ok then\n\t\t\tEmoteService.play(player, emoteId)\n\t\tend\n\tend)\n\n\t-- pista de baile: el que la pisa baila punta (no cuenta para misiones)\n\tlocal lobby = WorldService.lobby\n\tif lobby then\n\t\tlocal limiter = Guard.limiter(1 / 6, 1)\n\t\tlobby.danceFloor.Touched:Connect(function(hit)\n\t\t\tlocal player = Players:GetPlayerFromCharacter(hit.Parent)\n\t\t\tif player and limiter:allow(player) then\n\t\t\t\tEmoteService.play(player, \"emote_punta\")\n\t\t\tend\n\t\tend)\n\tend\nend\n\nreturn EmoteService\n"},{"path":"src/server/Services/Guard.luau","code":"--!strict\n-- Envuelve los remotos del servidor: límite de frecuencia por jugador + pcall.\n-- Ningún remoto se conecta directo; todos pasan por aquí.\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Net = require(Shared.Net)\nlocal RateLimiter = require(Shared.Logic.RateLimiter)\n\nlocal Guard = {}\n\nlocal limiters: { RateLimiter.Limiter } = {}\n\nlocal function limiter(rate: number, burst: number): RateLimiter.Limiter\n\tlocal l = RateLimiter.new(rate, burst)\n\ttable.insert(limiters, l)\n\treturn l\nend\nGuard.limiter = limiter\n\n-- rate: llamadas por segundo permitidas; burst: ráfaga máxima.\nfunction Guard.onEvent(name: string, rate: number, burst: number, handler: (player: Player, ...any) -> ())\n\tlocal l = limiter(rate, burst)\n\tNet.event(name).OnServerEvent:Connect(function(player: Player, ...: any)\n\t\tif not l:allow(player) then\n\t\t\treturn\n\t\tend\n\t\tlocal ok, err = pcall(function(...): any return handler(player, ...) end, ...)\n\t\tif not ok then\n\t\t\twarn(`[Remoto {name}] {err}`)\n\t\tend\n\tend)\nend\n\nfunction Guard.onInvoke(name: string, rate: number, burst: number, handler: (player: Player, ...any) -> any)\n\tlocal l = limiter(rate, burst)\n\tNet.func(name).OnServerInvoke = function(player: Player, ...: any): any\n\t\tif not l:allow(player) then\n\t\t\treturn { ok = false, code = \"rapido\", msg = \"Despacio, catracho. Probá otra vez.\" }\n\t\tend\n\t\tlocal ok, result = pcall(function(...): any return handler(player, ...) end, ...)\n\t\tif not ok then\n\t\t\twarn(`[Remoto {name}] {result}`)\n\t\t\treturn { ok = false, code = \"error\", msg = \"Algo falló. Probá otra vez.\" }\n\t\tend\n\t\treturn result\n\tend\nend\n\nfunction Guard.start()\n\tPlayers.PlayerRemoving:Connect(function(player)\n\t\tfor _, l in limiters do\n\t\t\tl:forget(player)\n\t\tend\n\tend)\nend\n\nreturn Guard\n"},{"path":"src/server/Services/LeaderboardService.luau","code":"--!strict\n-- Tablas de clasificación por minijuego con OrderedDataStore (más alto es mejor).\n-- En memoria (Studio sin API) se llena con bots de progress.json para que el panel no salga vacío.\nlocal DataStoreService = game:GetService(\"DataStoreService\")\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Config = require(Shared.Config)\nlocal GameData = require(Shared.GameData)\nlocal Net = require(Shared.Net)\nlocal Rewards = require(Shared.Logic.Rewards)\nlocal DataService = require(script.Parent.DataService)\nlocal Guard = require(script.Parent.Guard)\n\nlocal LeaderboardService = {}\n\nexport type Entry = { name: string, score: number, label: string, you: boolean? }\n\nlocal TOP = 10\nlocal CACHE_SECONDS = 45\n\nlocal stores: { [string]: OrderedDataStore } = {}\nlocal cache: { [string]: { at: number, entries: { Entry } } } = {}\nlocal local_: { [string]: { [number]: number } } = {} -- respaldo en memoria: userId -> score\nlocal names: { [number]: string } = {}\nlocal failed = false\n\nlocal function getStore(gameId: string): OrderedDataStore?\n\tif failed or DataService.isMemoryOnly() then\n\t\treturn nil\n\tend\n\tif not stores[gameId] then\n\t\tlocal ok, result = pcall(function()\n\t\t\treturn DataStoreService:GetOrderedDataStore(Config.DataStore.LeaderboardPrefix .. gameId)\n\t\tend)\n\t\tif not ok then\n\t\t\tfailed = true\n\t\t\treturn nil\n\t\tend\n\t\tstores[gameId] = result\n\tend\n\treturn stores[gameId]\nend\n\nlocal function nameOf(userId: number): string\n\tif names[userId] then\n\t\treturn names[userId]\n\tend\n\tlocal player = Players:GetPlayerByUserId(userId)\n\tlocal name = if player then player.DisplayName else nil\n\tif not name then\n\t\tlocal ok, result = pcall(function()\n\t\t\treturn Players:GetNameFromUserIdAsync(userId)\n\t\tend)\n\t\tname = if ok then result else \"Catracho\"\n\tend\n\tnames[userId] = name :: string\n\treturn name :: string\nend\n\n-- Marcas de ejemplo estables para el modo memoria.\nlocal function botEntries(gameId: string): { Entry }\n\tlocal rules = GameData.rules(gameId)\n\tlocal top = if gameId == \"carrera\"\n\t\tthen (rules.timeLimit - rules.gold) * 1000\n\t\telseif gameId == \"futbol\" then rules.goldGoals + 2\n\t\telse rules.gold\n\tlocal out = {}\n\tfor i = 1, 6 do\n\t\tlocal score = math.floor(top * (1.05 - i * 0.13))\n\t\tlocal name = GameData.bots[(i * 3 + #gameId) % #GameData.bots + 1]\n\t\ttable.insert(out, { name = name .. \" 🤖\", score = score, label = Rewards.scoreLabel(gameId, score) })\n\tend\n\treturn out\nend\n\n-- Guarda la marca si mejora la anterior. No bloquea al que llama.\nfunction LeaderboardService.submit(player: Player, gameId: string, score: number)\n\tif score <= 0 or score ~= score or not GameData.minigameById[gameId] then\n\t\treturn\n\tend\n\tscore = math.floor(score)\n\tlocal userId = player.UserId\n\tnames[userId] = player.DisplayName\n\tlocal board = local_[gameId] or {}\n\tlocal_[gameId] = board\n\tboard[userId] = math.max(board[userId] or 0, score)\n\tcache[gameId] = nil\n\tlocal store = getStore(gameId)\n\tif store then\n\t\ttask.spawn(function()\n\t\t\tlocal ok, err = pcall(function()\n\t\t\t\tstore:UpdateAsync(tostring(userId), function(old: any): any\n\t\t\t\t\tif typeof(old) == \"number\" and old >= score then\n\t\t\t\t\t\treturn nil\n\t\t\t\t\tend\n\t\t\t\t\treturn score\n\t\t\t\tend)\n\t\t\tend)\n\t\t\tif not ok then\n\t\t\t\twarn(`[Ranking] No se guardó la marca de {player.Name}: {err}`)\n\t\t\tend\n\t\tend)\n\tend\nend\n\nfunction LeaderboardService.top(gameId: string, viewer: Player?): { Entry }\n\tif not GameData.minigameById[gameId] then\n\t\treturn {}\n\tend\n\tlocal cached = cache[gameId]\n\tlocal entries: { Entry }\n\tif cached and os.clock() - cached.at < CACHE_SECONDS then\n\t\tentries = cached.entries\n\telse\n\t\tentries = {}\n\t\tlocal store = getStore(gameId)\n\t\tlocal loaded = false\n\t\tif store then\n\t\t\tlocal ok, err = pcall(function()\n\t\t\t\tlocal page = store:GetSortedAsync(false, TOP):GetCurrentPage()\n\t\t\t\tfor _, item in page do\n\t\t\t\t\tlocal userId = tonumber(item.key) or 0\n\t\t\t\t\ttable.insert(entries, { name = nameOf(userId), score = item.value, label = Rewards.scoreLabel(gameId, item.value), userId = userId } :: any)\n\t\t\t\tend\n\t\t\tend)\n\t\t\tloaded = ok\n\t\t\tif not ok then\n\t\t\t\twarn(`[Ranking] No se pudo leer {gameId}: {err}`)\n\t\t\tend\n\t\tend\n\t\tif not loaded then\n\t\t\tentries = botEntries(gameId)\n\t\t\tlocal board: { [number]: number } = local_[gameId] or {}\n\t\t\tfor userId, score in board do\n\t\t\t\ttable.insert(entries, { name = nameOf(userId), score = score, label = Rewards.scoreLabel(gameId, score), userId = userId } :: any)\n\t\t\tend\n\t\t\ttable.sort(entries, function(a, b)\n\t\t\t\treturn a.score > b.score\n\t\t\tend)\n\t\t\twhile #entries > TOP do\n\t\t\t\ttable.remove(entries)\n\t\t\tend\n\t\tend\n\t\tcache[gameId] = { at = os.clock(), entries = entries }\n\tend\n\tlocal out = {}\n\tfor _, e in entries do\n\t\ttable.insert(out, { name = e.name, score = e.score, label = e.label, you = viewer ~= nil and (e :: any).userId == viewer.UserId })\n\tend\n\treturn out\nend\n\nfunction LeaderboardService.start()\n\tGuard.onInvoke(Net.Functions.GetLeaderboard, 2, 5, function(player, gameId)\n\t\tif typeof(gameId) ~= \"string\" then\n\t\t\treturn { ok = false, entries = {} }\n\t\tend\n\t\treturn { ok = true, entries = LeaderboardService.top(gameId, player) }\n\tend)\nend\n\nreturn LeaderboardService\n"},{"path":"src/server/Services/MinigameService.luau","code":"--!nonstrict\nlocal Players = game:GetService(\"Players\")\nlocal Shared = game:GetService(\"ReplicatedStorage\").Shared\nlocal Net = require(Shared.Net)\nlocal GameData = require(Shared.GameData)\nlocal Rewards = require(Shared.Logic.Rewards)\nlocal Sanity = require(Shared.Logic.Sanity)\nlocal Guard = require(script.Parent.Guard)\nlocal Data = require(script.Parent.DataService)\nlocal Progress = require(script.Parent.ProgressService)\nlocal World = require(script.Parent.WorldService)\nlocal Boards = require(script.Parent.LeaderboardService)\nlocal Service = { runs = {}, games = {} }\n\nfunction Service.state(player, extra)\n\tlocal run = Service.runs[player]\n\tif not run then return end\n\tlocal state = { id = run.id, remaining = math.max(0, run.deadline - os.clock()), score = run.score or 0 }\n\tfor k, v in extra or {} do state[k] = v end\n\tNet.event(\"MinigameState\"):FireClient(player, state)\nend\n\nfunction Service.cancel(player)\n\tlocal run = Service.runs[player]\n\tif not run then return end\n\tService.runs[player] = nil\n\tif run.cleanup then run.cleanup() end\n\tplayer:SetAttribute(\"Minijuego\", nil)\n\tif player.Parent then Net.event(\"MinigameState\"):FireClient(player, { id = \"\" }) end\nend\n\nfunction Service.finish(player, raw)\n\tlocal run = Service.runs[player]\n\tif not run then return end\n\tlocal elapsed = os.clock() - run.started\n\tlocal valid, reason = Sanity.validate(run.id, raw, elapsed)\n\tService.cancel(player)\n\tif valid then\n\t\tlocal result = Rewards.evaluate(run.id, raw)\n\t\tlocal summary = Progress.recordMinigame(player, run.id, result)\n\t\tBoards.submit(player, run.id, result.score)\n\t\tif summary then Net.event(\"MinigameResult\"):FireClient(player, summary) end\n\telse\n\t\tProgress.toast(player, \"Partida inválida: \" .. tostring(reason))\n\tend\n\tWorld.toLobby(player)\nend\n\nfunction Service.begin(player, id)\n\tif typeof(id) ~= \"string\" or not Service.games[id] then return { ok = false, msg = \"Ese juego no está disponible.\" } end\n\tif Service.runs[player] then return { ok = false, msg = \"Salí de tu partida primero.\" } end\n\tif not Data.get(player) or not World.isAlive(player) then return { ok = false, msg = \"Esperá a que cargue tu personaje.\" } end\n\tlocal rules = GameData.rules(id)\n\tlocal duration = rules.timeLimit or rules.duration or 180\n\tlocal now = os.clock()\n\tlocal run = { id = id, started = now, deadline = now + duration, score = 0 }\n\tService.runs[player] = run\n\tlocal ok, message = Service.games[id].begin(player, run)\n\tif not ok then Service.cancel(player); return { ok = false, msg = message or \"Esperá a la próxima ronda.\" } end\n\tplayer:SetAttribute(\"Minijuego\", id)\n\tService.state(player)\n\treturn { ok = true }\nend\n\nfunction Service.start()\n\tfor _, module in script.Parent.Parent.Minigames:GetChildren() do\n\t\tif module:IsA(\"ModuleScript\") then\n\t\t\tlocal implementation = require(module)\n\t\t\timplementation.setup(Service)\n\t\t\tService.games[implementation.id] = implementation\n\t\tend\n\tend\n\tGuard.onInvoke(Net.Functions.MinigameStart, 0.5, 2, Service.begin)\n\tGuard.onEvent(Net.Events.MinigameQuit, 1, 2, function(player) Service.cancel(player); World.toLobby(player) end)\n\tWorld.onBeforeTravel(Service.cancel)\n\tlocal lobby = World.lobby\n\tassert(lobby)\n\tfor id, prompt in lobby.portals do\n\t\tprompt.Triggered:Connect(function(player)\n\t\t\tif not World.isNear(player, prompt.Parent.Position, 18) then return end\n\t\t\tlocal result = Service.begin(player, id)\n\t\t\tif not result.ok then Progress.toast(player, result.msg) end\n\t\tend)\n\tend\n\tlocal function playerAdded(player)\n\t\tplayer.CharacterAdded:Connect(function() Service.cancel(player) end)\n\tend\n\tPlayers.PlayerAdded:Connect(playerAdded)\n\tfor _, player in Players:GetPlayers() do playerAdded(player) end\n\tPlayers.PlayerRemoving:Connect(Service.cancel)\n\ttask.spawn(function()\n\t\twhile true do\n\t\t\ttask.wait(0.25)\n\t\t\tfor player, run in Service.runs do\n\t\t\t\tif os.clock() >= run.deadline and run.timeout then run.timeout()\n\t\t\t\telseif Service.runs[player] then Service.state(player, run.hud) end\n\t\t\tend\n\t\tend\n\tend)\nend\nreturn Service\n"},{"path":"src/server/Services/ProgressService.luau","code":"--!strict\n-- Única puerta para cambiar el progreso de un jugador: monedas, XP, logros, misiones y leaderstats.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal GameData = require(Shared.GameData)\nlocal Net = require(Shared.Net)\nlocal Types = require(Shared.Types)\nlocal Achievements = require(Shared.Logic.Achievements)\nlocal Missions = require(Shared.Logic.Missions)\nlocal Profiles = require(Shared.Logic.Profiles)\nlocal DataService = require(script.Parent.DataService)\nlocal Guard = require(script.Parent.Guard)\n\nlocal ProgressService = {}\n\nlocal syncQueued: { [Player]: boolean } = {}\n\nfunction ProgressService.toast(player: Player, text: string, icon: string?)\n\tNet.event(\"Toast\"):FireClient(player, text, icon)\nend\n\nfunction ProgressService.effect(player: Player, kind: string, data: any)\n\tNet.event(\"Effect\"):FireClient(player, kind, data)\nend\n\nlocal function leaderstats(player: Player, profile: Types.Profile)\n\tlocal folder = player:FindFirstChild(\"leaderstats\")\n\tif not folder then\n\t\tlocal created = Instance.new(\"Folder\")\n\t\tcreated.Name = \"leaderstats\"\n\t\tlocal level = Instance.new(\"IntValue\")\n\t\tlevel.Name = \"Nivel\"\n\t\tlevel.Parent = created\n\t\tlocal coins = Instance.new(\"IntValue\")\n\t\tcoins.Name = GameData.rewards.currency\n\t\tcoins.Parent = created\n\t\tcreated.Parent = player\n\t\tfolder = created\n\tend\n\tlocal f = folder :: Instance\n\tlocal level = f:FindFirstChild(\"Nivel\")\n\tlocal coins = f:FindFirstChild(GameData.rewards.currency)\n\tif level and level:IsA(\"IntValue\") then\n\t\tlevel.Value = profile.level\n\tend\n\tif coins and coins:IsA(\"IntValue\") then\n\t\tcoins.Value = profile.coins\n\tend\nend\n\n-- Manda el perfil al cliente; varias llamadas en el mismo cuadro salen como una sola.\nfunction ProgressService.sync(player: Player)\n\tif syncQueued[player] then\n\t\treturn\n\tend\n\tsyncQueued[player] = true\n\ttask.defer(function()\n\t\tsyncQueued[player] = nil\n\t\tlocal profile = DataService.get(player)\n\t\tif profile and player.Parent then\n\t\t\tNet.event(\"ProfileSync\"):FireClient(player, profile)\n\t\tend\n\tend)\nend\n\nlocal function readyMissions(profile: Types.Profile): { [string]: boolean }\n\tlocal ready = {}\n\tfor _, dm in profile.daily.missions do\n\t\tlocal m = GameData.missionById[dm.id]\n\t\tif m and dm.progress >= m.count then\n\t\t\tready[dm.id] = true\n\t\tend\n\tend\n\treturn ready\nend\n\n-- Aplica cambios al perfil, revisa logros, marca para guardar y avisa al cliente.\n-- Devuelve los logros nuevos, o nil si el perfil todavía no cargó.\nfunction ProgressService.commit(player: Player, change: (profile: Types.Profile) -> ()): { string }?\n\tlocal profile = DataService.get(player)\n\tif not profile then\n\t\treturn nil\n\tend\n\tMissions.ensureToday(profile, os.time())\n\tlocal levelBefore = profile.level\n\tlocal readyBefore = readyMissions(profile)\n\tchange(profile)\n\tlocal fresh = Achievements.check(profile)\n\tDataService.markDirty(player)\n\tleaderstats(player, profile)\n\tProgressService.sync(player)\n\tfor _, id in fresh do\n\t\tlocal a = GameData.achievementById[id]\n\t\tProgressService.toast(player, `Logro: {a.name} (+{a.coins})`, a.icon)\n\tend\n\tif profile.level > levelBefore then\n\t\tProgressService.toast(player, `¡Subiste al nivel {profile.level}! (+{GameData.rewards.levelUp.coins * (profile.level - levelBefore)})`, \"⭐\")\n\tend\n\tfor id in readyMissions(profile) do\n\t\tif not readyBefore[id] then\n\t\t\tProgressService.toast(player, `Misión lista: {GameData.missionById[id].text}`, \"📋\")\n\t\tend\n\tend\n\treturn fresh\nend\n\n-- Registra una partida ya validada por MinigameService y devuelve el resumen para el cliente.\nfunction ProgressService.recordMinigame(player: Player, gameId: string, result: Types.Result): Types.Summary?\n\tlocal summary: Types.Summary? = nil\n\tlocal fresh = ProgressService.commit(player, function(profile)\n\t\tsummary = Profiles.recordMinigame(profile, gameId, result)\n\tend)\n\tif summary and fresh then\n\t\tsummary.newAchievements = fresh\n\tend\n\treturn summary\nend\n\nfunction ProgressService.start()\n\tDataService.onLoaded(function(player, _profile)\n\t\t-- el primer commit entrega \"Primeros pasos\" y deja listas las misiones del día\n\t\tProgressService.commit(player, function() end)\n\tend)\n\n\tGuard.onInvoke(Net.Functions.ClaimMission, 2, 4, function(player, id)\n\t\tlocal claimed = false\n\t\tlocal mission: Types.Mission? = nil\n\t\tif typeof(id) == \"string\" then\n\t\t\tProgressService.commit(player, function(profile)\n\t\t\t\tclaimed, mission = Missions.claim(profile, id)\n\t\t\tend)\n\t\tend\n\t\tif claimed and mission then\n\t\t\tProgressService.toast(player, `Misión cumplida: +{mission.coins} {GameData.rewards.currency}`, \"📋\")\n\t\tend\n\t\treturn { ok = claimed }\n\tend)\n\n\tGuard.onInvoke(Net.Functions.SettingsSet, 2, 4, function(player, changes)\n\t\tlocal ok = false\n\t\tProgressService.commit(player, function(profile)\n\t\t\tok = Profiles.setSettings(profile, changes)\n\t\tend)\n\t\treturn { ok = ok }\n\tend)\nend\n\nreturn ProgressService\n"},{"path":"src/server/Services/RoomService.luau","code":"--!strict\n-- Salas privadas: TeleportService:ReserveServer + código corto para invitar amigos.\n-- En Studio no hay teleport: se avisa y el juego sigue en el servidor público.\nlocal MemoryStoreService = game:GetService(\"MemoryStoreService\")\nlocal RunService = game:GetService(\"RunService\")\nlocal TeleportService = game:GetService(\"TeleportService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Net = require(Shared.Net)\nlocal Guard = require(script.Parent.Guard)\nlocal ProgressService = require(script.Parent.ProgressService)\n\nlocal RoomService = {}\n\nlocal ALPHABET = \"ABCDEFGHJKLMNPQRSTUVWXYZ23456789\" -- sin 0/O ni 1/I\nlocal CODE_LENGTH = 6\nlocal EXPIRATION = 6 * 3600\nlocal STUDIO_MESSAGE = \"Las salas privadas solo funcionan en el juego publicado, no en Studio.\"\n\nlocal myCode: string? = nil\n\nlocal function map(): MemoryStoreHashMap\n\treturn MemoryStoreService:GetHashMap(\"MC_Salas_v1\")\nend\n\nlocal function newCode(): string\n\tlocal out = {}\n\tfor _ = 1, CODE_LENGTH do\n\t\tlocal i = math.random(1, #ALPHABET)\n\t\ttable.insert(out, string.sub(ALPHABET, i, i))\n\tend\n\treturn table.concat(out)\nend\n\n-- Limpia lo que escribió el jugador; nil si no parece un código.\nfunction RoomService.cleanCode(raw: any): string?\n\tif typeof(raw) ~= \"string\" or #raw > 16 then\n\t\treturn nil\n\tend\n\tlocal code = string.upper((string.gsub(raw, \"[%s%-]\", \"\")))\n\tif #code ~= CODE_LENGTH or string.find(code, \"[^A-Z0-9]\") then\n\t\treturn nil\n\tend\n\treturn code\nend\n\nlocal function isReserved(): boolean\n\treturn game.PrivateServerId ~= \"\" and game.PrivateServerOwnerId == 0\nend\n\nlocal function send(player: Player, accessCode: string)\n\ttask.spawn(function()\n\t\tlocal options = Instance.new(\"TeleportOptions\")\n\t\toptions.ReservedServerAccessCode = accessCode\n\t\tlocal ok, err = pcall(function()\n\t\t\tTeleportService:TeleportAsync(game.PlaceId, { player }, options)\n\t\tend)\n\t\tif not ok then\n\t\t\twarn(`[Salas] Teleport falló: {err}`)\n\t\t\tProgressService.toast(player, \"No se pudo entrar a la sala. Probá otra vez.\", \"🚪\")\n\t\tend\n\tend)\nend\n\nfunction RoomService.start()\n\tif isReserved() then\n\t\ttask.spawn(function()\n\t\t\tlocal ok, code = pcall(function()\n\t\t\t\treturn map():GetAsync(\"s_\" .. game.PrivateServerId)\n\t\t\tend)\n\t\t\tif ok and typeof(code) == \"string\" then\n\t\t\t\tmyCode = code\n\t\t\tend\n\t\tend)\n\tend\n\n\tGuard.onInvoke(Net.Functions.RoomInfo, 2, 4, function(_player)\n\t\treturn { ok = true, private = isReserved(), code = myCode, studio = RunService:IsStudio() }\n\tend)\n\n\tGuard.onInvoke(Net.Functions.RoomCreate, 0.2, 2, function(player)\n\t\tif RunService:IsStudio() then\n\t\t\treturn { ok = false, msg = STUDIO_MESSAGE }\n\t\tend\n\t\tlocal accessCode, serverId\n\t\tlocal ok, err = pcall(function()\n\t\t\taccessCode, serverId = TeleportService:ReserveServer(game.PlaceId)\n\t\tend)\n\t\tif not ok or typeof(accessCode) ~= \"string\" then\n\t\t\twarn(`[Salas] ReserveServer falló: {err}`)\n\t\t\treturn { ok = false, msg = \"No se pudo crear la sala. Probá más tarde.\" }\n\t\tend\n\t\tlocal code = newCode()\n\t\tlocal saved = pcall(function()\n\t\t\tmap():SetAsync(\"c_\" .. code, accessCode, EXPIRATION)\n\t\t\tmap():SetAsync(\"s_\" .. tostring(serverId), code, EXPIRATION)\n\t\tend)\n\t\tif not saved then\n\t\t\treturn { ok = false, msg = \"No se pudo guardar el código de la sala.\" }\n\t\tend\n\t\tsend(player, accessCode)\n\t\treturn { ok = true, code = code }\n\tend)\n\n\tGuard.onInvoke(Net.Functions.RoomJoin, 0.5, 3, function(player, raw)\n\t\tif RunService:IsStudio() then\n\t\t\treturn { ok = false, msg = STUDIO_MESSAGE }\n\t\tend\n\t\tlocal code = RoomService.cleanCode(raw)\n\t\tif not code then\n\t\t\treturn { ok = false, msg = \"El código tiene 6 letras o números.\" }\n\t\tend\n\t\tlocal ok, accessCode = pcall(function()\n\t\t\treturn map():GetAsync(\"c_\" .. code)\n\t\tend)\n\t\tif not ok then\n\t\t\treturn { ok = false, msg = \"No se pudo buscar la sala. Probá otra vez.\" }\n\t\tend\n\t\tif typeof(accessCode) ~= \"string\" then\n\t\t\treturn { ok = false, msg = \"No existe una sala con ese código.\" }\n\t\tend\n\t\tsend(player, accessCode)\n\t\treturn { ok = true, code = code }\n\tend)\nend\n\nreturn RoomService\n"},{"path":"src/server/Services/ShopService.luau","code":"--!strict\n-- Tienda: compras y cambios de avatar, siempre validados contra shop.json y el perfil del servidor.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal GameData = require(Shared.GameData)\nlocal Net = require(Shared.Net)\nlocal Shop = require(Shared.Logic.Shop)\nlocal AvatarService = require(script.Parent.AvatarService)\nlocal Guard = require(script.Parent.Guard)\nlocal ProgressService = require(script.Parent.ProgressService)\n\nlocal ShopService = {}\n\nlocal MESSAGES = {\n\tok = \"¡Comprado!\",\n\tno = \"Ese artículo no existe.\",\n\tya = \"Ya lo tenés.\",\n\tcaro = \"No te alcanzan las Lempiritas.\",\n}\n\nfunction ShopService.start()\n\tGuard.onInvoke(Net.Functions.ShopBuy, 3, 5, function(player, itemId)\n\t\tlocal code = \"no\"\n\t\tlocal fresh = ProgressService.commit(player, function(profile)\n\t\t\tcode = Shop.buy(profile, itemId)\n\t\tend)\n\t\tif not fresh then\n\t\t\treturn { ok = false, code = \"error\", msg = \"Tus datos todavía están cargando.\" }\n\t\tend\n\t\tif code == \"ok\" then\n\t\t\tlocal item = GameData.itemById[itemId]\n\t\t\tProgressService.toast(player, `Compraste: {item.name} (-{item.price})`, \"🛍️\")\n\t\tend\n\t\treturn { ok = code == \"ok\", code = code, msg = MESSAGES[code] }\n\tend)\n\n\tGuard.onInvoke(Net.Functions.AvatarSet, 6, 10, function(player, changes)\n\t\tlocal changed, rejected = 0, 0\n\t\tlocal fresh = ProgressService.commit(player, function(profile)\n\t\t\tchanged, rejected = Shop.applyAvatar(profile, changes)\n\t\tend)\n\t\tif not fresh then\n\t\t\treturn { ok = false }\n\t\tend\n\t\tif changed > 0 then\n\t\t\tAvatarService.refresh(player)\n\t\tend\n\t\treturn { ok = rejected == 0, changed = changed }\n\tend)\nend\n\nreturn ShopService\n"},{"path":"src/server/Services/WorldService.luau","code":"--!strict\n-- Construye el mundo al iniciar y maneja lo que pasa en él: viajes, monedas, recuerdos y avisos.\nlocal CollectionService = game:GetService(\"CollectionService\")\nlocal Lighting = game:GetService(\"Lighting\")\nlocal Players = game:GetService(\"Players\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Config = require(Shared.Config)\nlocal GameData = require(Shared.GameData)\nlocal Net = require(Shared.Net)\nlocal Profiles = require(Shared.Logic.Profiles)\nlocal Build = require(script.Parent.Parent.World.Build)\nlocal Lobby = require(script.Parent.Parent.World.Lobby)\nlocal Zones = require(script.Parent.Parent.World.Zones)\nlocal Guard = require(script.Parent.Guard)\nlocal ProgressService = require(script.Parent.ProgressService)\n\nlocal WorldService = {}\n\nWorldService.zones = {} :: { [string]: Zones.Zone }\nWorldService.lobby = nil :: Lobby.Result?\n\nlocal root: Folder? = nil\nlocal beforeTravel: { (Player) -> () } = {}\nlocal travelLimiter = Guard.limiter(1 / Config.Limits.TravelCooldown, 2)\nlocal coinLimiter = Guard.limiter(Config.Limits.CoinPickupsPerSecond, Config.Limits.CoinPickupsPerSecond * 2)\n\nlocal COIN_RESPAWN = 25\n\nfunction WorldService.root(): Folder\n\tif not root then\n\t\troot = Build.folder(Workspace, \"Mundo\")\n\tend\n\treturn root :: Folder\nend\n\nlocal function rootPart(player: Player): BasePart?\n\tlocal character = player.Character\n\tlocal part = character and character:FindFirstChild(\"HumanoidRootPart\")\n\tif part and part:IsA(\"BasePart\") then\n\t\treturn part\n\tend\n\treturn nil\nend\nWorldService.rootPart = rootPart\n\nfunction WorldService.isAlive(player: Player): boolean\n\tlocal character = player.Character\n\tlocal humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n\treturn humanoid ~= nil and humanoid.Health > 0 and rootPart(player) ~= nil\nend\n\n-- ¿Está el jugador a menos de `distance` studs de este punto? (para validar avisos y recogidas)\nfunction WorldService.isNear(player: Player, position: Vector3, distance: number): boolean\n\tlocal part = rootPart(player)\n\treturn part ~= nil and (part.Position - position).Magnitude <= distance\nend\n\n-- Mueve al personaje. `place` queda en el atributo \"Lugar\" para que el cliente sepa dónde está.\nfunction WorldService.teleport(player: Player, cf: CFrame, place: string): boolean\n\tlocal character = player.Character\n\tlocal part = rootPart(player)\n\tif not character or not part or not WorldService.isAlive(player) then\n\t\treturn false\n\tend\n\tlocal humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n\tif humanoid and humanoid.Sit then\n\t\thumanoid.Sit = false\n\tend\n\tpart.AssemblyLinearVelocity = Vector3.zero\n\tpart.AssemblyAngularVelocity = Vector3.zero\n\tcharacter:PivotTo(cf)\n\tplayer:SetAttribute(\"Lugar\", place)\n\treturn true\nend\n\n-- Se llama antes de cualquier viaje pedido por el jugador (los minijuegos lo usan para abandonar la partida).\nfunction WorldService.onBeforeTravel(callback: (Player) -> ())\n\ttable.insert(beforeTravel, callback)\nend\n\nfunction WorldService.toLobby(player: Player): boolean\n\tfor _, callback in beforeTravel do\n\t\tcallback(player)\n\tend\n\tlocal s = Config.World.LobbySpawn\n\treturn WorldService.teleport(player, CFrame.new(s), \"lobby\")\nend\n\nfunction WorldService.travel(player: Player, deptId: string): (boolean, string?)\n\tlocal zone = WorldService.zones[deptId]\n\tif not zone then\n\t\treturn false, \"Ese lugar no existe.\"\n\tend\n\tif not travelLimiter:allow(player) then\n\t\treturn false, \"Esperá un momento antes de viajar otra vez.\"\n\tend\n\tfor _, callback in beforeTravel do\n\t\tcallback(player)\n\tend\n\tif not WorldService.teleport(player, zone.arrival, \"depto:\" .. deptId) then\n\t\treturn false, \"Tu personaje todavía no está listo.\"\n\tend\n\tlocal first = false\n\tProgressService.commit(player, function(profile)\n\t\tfirst = Profiles.visit(profile, deptId)\n\tend)\n\tif first then\n\t\tlocal r = GameData.rewards.world.firstVisit\n\t\tProgressService.toast(player, `Primera visita a {zone.dept.name}: +{r.coins} {GameData.rewards.currency}`, \"🚌\")\n\tend\n\treturn true, nil\nend\n\nlocal function wireCoin(coin: BasePart)\n\tcoin.Touched:Connect(function(hit)\n\t\tif coin:GetAttribute(\"Tomada\") then\n\t\t\treturn\n\t\tend\n\t\tlocal player = Players:GetPlayerFromCharacter(hit.Parent)\n\t\tif not player or not WorldService.isNear(player, coin.Position, Config.Limits.CoinPickupDistance) then\n\t\t\treturn\n\t\tend\n\t\tif not coinLimiter:allow(player) then\n\t\t\treturn\n\t\tend\n\t\tcoin:SetAttribute(\"Tomada\", true)\n\t\tcoin.Transparency = 1\n\t\tProgressService.commit(player, Profiles.pickupCoin)\n\t\tProgressService.effect(player, \"moneda\", coin.Position)\n\t\ttask.delay(COIN_RESPAWN, function()\n\t\t\tcoin.Transparency = 0\n\t\t\tcoin:SetAttribute(\"Tomada\", nil)\n\t\tend)\n\tend)\nend\n\nlocal function wireZone(zone: Zones.Zone)\n\tzone.returnPrompt.Triggered:Connect(function(player)\n\t\tWorldService.toLobby(player)\n\tend)\n\tzone.collectPrompt.Triggered:Connect(function(player)\n\t\tlocal gift = zone.collectPrompt.Parent :: BasePart\n\t\tif not WorldService.isNear(player, gift.Position, Config.Limits.PromptDistance) then\n\t\t\treturn\n\t\tend\n\t\tlocal got = false\n\t\tProgressService.commit(player, function(profile)\n\t\t\tgot = Profiles.collect(profile, zone.dept.id)\n\t\tend)\n\t\tif got then\n\t\t\tlocal r = GameData.rewards.world.collectible\n\t\t\tProgressService.toast(player, `Recuerdo: {zone.dept.collectible} (+{r.coins} {GameData.rewards.currency})`, \"💎\")\n\t\telse\n\t\t\tProgressService.toast(player, \"Ya tenés este recuerdo.\", \"💎\")\n\t\tend\n\tend)\nend\n\nlocal function atmosphere()\n\tlocal sky = Instance.new(\"Atmosphere\")\n\tsky.Density = 0.28\n\tsky.Offset = 0.2\n\tsky.Color = Color3.fromHex(\"#cfe9ff\")\n\tsky.Decay = Color3.fromHex(\"#ffe9c4\")\n\tsky.Glare = 0.2\n\tsky.Haze = 1.2\n\tsky.Parent = Lighting\nend\n\n-- Genera lobby y departamentos. Los minijuegos agregan sus canchas en WorldService.root().\nfunction WorldService.build()\n\tlocal folder = WorldService.root()\n\tatmosphere()\n\tWorldService.lobby = Lobby.build(folder)\n\tWorldService.zones = Zones.build(folder)\nend\n\nfunction WorldService.start()\n\tlocal lobby = WorldService.lobby\n\tassert(lobby, \"WorldService.build() va primero\")\n\n\tfor _, coin in CollectionService:GetTagged(\"Moneda\") do\n\t\tif coin:IsA(\"BasePart\") then\n\t\t\twireCoin(coin)\n\t\tend\n\tend\n\tfor _, zone in WorldService.zones do\n\t\twireZone(zone)\n\tend\n\tfor deptId, prompt in lobby.mapPrompts do\n\t\tprompt.Triggered:Connect(function(player)\n\t\t\tlocal ok, msg = WorldService.travel(player, deptId)\n\t\t\tif not ok and msg then\n\t\t\t\tProgressService.toast(player, msg, \"🚌\")\n\t\t\tend\n\t\tend)\n\tend\n\tlobby.shopPrompt.Triggered:Connect(function(player)\n\t\tNet.event(\"OpenPanel\"):FireClient(player, \"tienda\")\n\tend)\n\tlobby.terminalPrompt.Triggered:Connect(function(player)\n\t\tNet.event(\"OpenPanel\"):FireClient(player, \"mapa\")\n\tend)\n\n\tPlayers.PlayerAdded:Connect(function(player)\n\t\tplayer:SetAttribute(\"Lugar\", \"lobby\")\n\t\tplayer.CharacterAdded:Connect(function()\n\t\t\tplayer:SetAttribute(\"Lugar\", \"lobby\")\n\t\tend)\n\tend)\n\tfor _, player in Players:GetPlayers() do\n\t\tplayer:SetAttribute(\"Lugar\", \"lobby\")\n\tend\n\n\tGuard.onInvoke(Net.Functions.TravelTo, 2, 3, function(player, target)\n\t\tif typeof(target) ~= \"string\" or #target > 40 then\n\t\t\treturn { ok = false, msg = \"Destino inválido.\" }\n\t\tend\n\t\tif target == \"lobby\" then\n\t\t\treturn { ok = WorldService.toLobby(player) }\n\t\tend\n\t\tlocal ok, msg = WorldService.travel(player, target)\n\t\treturn { ok = ok, msg = msg }\n\tend)\nend\n\nreturn WorldService\n"},{"path":"src/server/World/Build.luau","code":"--!strict\n-- Piezas de construcción: todo el mundo se arma con estas funciones (no hay nada hecho a mano en Studio).\nlocal CollectionService = game:GetService(\"CollectionService\")\n\nlocal Build = {}\n\nexport type Props = { [string]: any }\n\nlocal SMOOTH = Enum.SurfaceType.Smooth\n\nlocal function hex(h: string): Color3\n\treturn Color3.fromHex(h)\nend\nBuild.hex = hex\n\nBuild.C = {\n\twhite = hex(\"#f7f4ec\"),\n\tcream = hex(\"#f3e6c8\"),\n\tblack = hex(\"#1d1d1f\"),\n\tgray = hex(\"#8d9399\"),\n\tdarkGray = hex(\"#4a4f55\"),\n\tstone = hex(\"#a8a495\"),\n\tblue = hex(\"#00a3d7\"), -- azul turquesa de la bandera\n\tnavy = hex(\"#0d47a1\"),\n\tred = hex(\"#e63946\"),\n\torange = hex(\"#ff7a3d\"),\n\tyellow = hex(\"#ffc93c\"),\n\tgreen = hex(\"#2ea44f\"),\n\tleaf = hex(\"#3f9b4b\"),\n\tdarkLeaf = hex(\"#2d6a4f\"),\n\tpink = hex(\"#ff5d9e\"),\n\tpurple = hex(\"#7b5cff\"),\n\twood = hex(\"#8d6e63\"),\n\tdarkWood = hex(\"#5d4037\"),\n\tsand = hex(\"#f1dca7\"),\n\twater = hex(\"#3aa7e0\"),\n\troof = hex(\"#b5533c\"), -- teja colonial\n\tasphalt = hex(\"#3b3f45\"),\n\tgold = hex(\"#ffd700\"),\n}\nlocal C = Build.C\n\nlocal function apply(inst: Instance, props: Props?)\n\tif props then\n\t\tfor k, v in props do\n\t\t\t(inst :: any)[k] = v\n\t\tend\n\tend\nend\n\nfunction Build.folder(parent: Instance, name: string): Folder\n\tlocal f = Instance.new(\"Folder\")\n\tf.Name = name\n\tf.Parent = parent\n\treturn f\nend\n\nfunction Build.model(parent: Instance, name: string): Model\n\tlocal m = Instance.new(\"Model\")\n\tm.Name = name\n\tm.Parent = parent\n\treturn m\nend\n\n-- Bloque anclado. Es la base de todo lo demás.\nfunction Build.part(parent: Instance, size: Vector3, cf: CFrame, color: Color3, material: Enum.Material?, props: Props?): Part\n\tlocal p = Instance.new(\"Part\")\n\tp.Anchored = true\n\tp.Size = size\n\tp.CFrame = cf\n\tp.Color = color\n\tp.Material = material or Enum.Material.SmoothPlastic\n\tp.TopSurface = SMOOTH\n\tp.BottomSurface = SMOOTH\n\tapply(p, props)\n\tp.Parent = parent\n\treturn p\nend\n\n-- Adorno: no choca, no se toca, no entra en raycasts (barato para el motor).\nfunction Build.ghost<T>(p: T): T\n\tlocal part = p :: any\n\tpart.CanCollide = false\n\tpart.CanTouch = false\n\tpart.CanQuery = false\n\treturn p\nend\n\nfunction Build.deco(parent: Instance, size: Vector3, cf: CFrame, color: Color3, material: Enum.Material?, props: Props?): Part\n\treturn Build.ghost(Build.part(parent, size, cf, color, material, props))\nend\n\n-- Cilindro vertical (eje Y) de radio y alto dados.\nfunction Build.cyl(parent: Instance, radius: number, height: number, cf: CFrame, color: Color3, material: Enum.Material?, props: Props?): Part\n\tlocal p = Build.part(parent, Vector3.new(height, radius * 2, radius * 2), cf * CFrame.Angles(0, 0, math.rad(90)), color, material, props)\n\tp.Shape = Enum.PartType.Cylinder\n\treturn p\nend\n\nfunction Build.ball(parent: Instance, diameter: number, cf: CFrame, color: Color3, material: Enum.Material?, props: Props?): Part\n\tlocal p = Build.part(parent, Vector3.new(diameter, diameter, diameter), cf, color, material, props)\n\tp.Shape = Enum.PartType.Ball\n\treturn p\nend\n\nfunction Build.wedge(parent: Instance, size: Vector3, cf: CFrame, color: Color3, material: Enum.Material?, props: Props?): WedgePart\n\tlocal p = Instance.new(\"WedgePart\")\n\tp.Anchored = true\n\tp.Size = size\n\tp.CFrame = cf\n\tp.Color = color\n\tp.Material = material or Enum.Material.SmoothPlastic\n\tp.TopSurface = SMOOTH\n\tp.BottomSurface = SMOOTH\n\tapply(p, props)\n\tp.Parent = parent\n\treturn p\nend\n\nexport type TextOpts = {\n\tcolor: Color3?,\n\tbg: Color3?,\n\tfont: Enum.Font?,\n\tface: Enum.NormalId?,\n\twrap: boolean?,\n\tpad: number?,\n}\n\n-- Texto pintado en una cara de la pieza.\nfunction Build.text(part: BasePart, text: string, opts: TextOpts?): TextLabel\n\tlocal o: TextOpts = opts or {}\n\tlocal face = o.face or Enum.NormalId.Front\n\tlocal gui = Instance.new(\"SurfaceGui\")\n\tgui.Face = face\n\tgui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n\tgui.PixelsPerStud = 30\n\tgui.LightInfluence = 0.4\n\tgui.Parent = part\n\tlocal label = Instance.new(\"TextLabel\")\n\tlabel.Size = UDim2.fromScale(1, 1)\n\tlabel.BackgroundTransparency = if o.bg then 0 else 1\n\tlabel.BackgroundColor3 = o.bg or C.white\n\tlabel.BorderSizePixel = 0\n\tlabel.Text = text\n\tlabel.TextColor3 = o.color or C.black\n\tlabel.Font = o.font or Enum.Font.FredokaOne\n\tlabel.TextScaled = true\n\tlabel.TextWrapped = o.wrap ~= false\n\tlabel.Parent = gui\n\tlocal padding = Instance.new(\"UIPadding\")\n\tlocal pad = UDim.new(o.pad or 0.06, 0)\n\tpadding.PaddingLeft, padding.PaddingRight, padding.PaddingTop, padding.PaddingBottom = pad, pad, pad, pad\n\tpadding.Parent = label\n\treturn label\nend\n\n-- Rótulo con patas. Devuelve el tablero.\nfunction Build.sign(parent: Instance, cf: CFrame, width: number, height: number, text: string, opts: TextOpts?, legs: number?): Part\n\tlocal legHeight = legs or 3\n\tlocal m = Build.model(parent, \"Rotulo\")\n\tlocal board = Build.part(m, Vector3.new(width, height, 0.5), cf * CFrame.new(0, legHeight + height / 2, 0), (opts and opts.bg) or C.cream, Enum.Material.Wood)\n\tboard.Name = \"Tablero\"\n\tlocal o: TextOpts = if opts then table.clone(opts) else {}\n\to.bg = nil\n\tBuild.text(board, text, o)\n\tif legHeight > 0 then\n\t\tfor _, x in { -width / 2 + 0.6, width / 2 - 0.6 } do\n\t\t\tBuild.deco(m, Vector3.new(0.6, legHeight + height, 0.6), cf * CFrame.new(x, (legHeight + height) / 2, 0.5), C.darkWood, Enum.Material.Wood)\n\t\tend\n\tend\n\treturn board\nend\n\n-- Etiqueta flotante sobre una pieza (se ve desde cualquier ángulo).\nfunction Build.label(adornee: BasePart, text: string, studsUp: number?, color: Color3?, width: number?): BillboardGui\n\tlocal gui = Instance.new(\"BillboardGui\")\n\tgui.Size = UDim2.fromScale(width or 10, 2.4)\n\tgui.StudsOffsetWorldSpace = Vector3.new(0, studsUp or 4, 0)\n\tgui.MaxDistance = 140\n\tgui.AlwaysOnTop = false\n\tgui.LightInfluence = 0\n\tgui.Adornee = adornee\n\tgui.Parent = adornee\n\tlocal label = Instance.new(\"TextLabel\")\n\tlabel.Size = UDim2.fromScale(1, 1)\n\tlabel.BackgroundTransparency = 1\n\tlabel.Text = text\n\tlabel.TextColor3 = color or C.white\n\tlabel.TextStrokeTransparency = 0.3\n\tlabel.TextStrokeColor3 = C.black\n\tlabel.Font = Enum.Font.FredokaOne\n\tlabel.TextScaled = true\n\tlabel.Parent = gui\n\treturn gui\nend\n\nfunction Build.prompt(part: BasePart, action: string, object: string?, hold: number?, distance: number?): ProximityPrompt\n\tlocal prompt = Instance.new(\"ProximityPrompt\")\n\tprompt.ActionText = action\n\tprompt.ObjectText = object or \"\"\n\tprompt.HoldDuration = hold or 0\n\tprompt.MaxActivationDistance = distance or 12\n\tprompt.RequiresLineOfSight = false\n\tprompt.Parent = part\n\treturn prompt\nend\n\n-- Árboles por tipo de bioma.\nfunction Build.tree(parent: Instance, kind: string, pos: Vector3, scale: number?)\n\tlocal s = scale or 1\n\tlocal m = Build.model(parent, \"Arbol\")\n\tlocal base = CFrame.new(pos)\n\tif kind == \"palm\" then\n\t\tBuild.cyl(m, 0.7 * s, 14 * s, base * CFrame.new(0, 7 * s, 0) * CFrame.Angles(0, 0, math.rad(4)), hex(\"#9c7a4d\"), Enum.Material.Wood)\n\t\tfor i = 0, 4 do\n\t\t\tlocal a = math.rad(i * 72)\n\t\t\tBuild.deco(m, Vector3.new(8 * s, 0.4 * s, 2.4 * s), base * CFrame.new(0, 14 * s, 0) * CFrame.Angles(0, a, math.rad(-18)) * CFrame.new(4 * s, 0, 0), C.leaf, Enum.Material.Grass)\n\t\tend\n\t\tBuild.ghost(Build.ball(m, 1.4 * s, base * CFrame.new(0.6 * s, 13.2 * s, 0.4 * s), hex(\"#6b4a2b\")))\n\telseif kind == \"pine\" then\n\t\tBuild.cyl(m, 0.8 * s, 6 * s, base * CFrame.new(0, 3 * s, 0), C.darkWood, Enum.Material.Wood)\n\t\tfor i = 0, 2 do\n\t\t\tlocal r = (5 - i * 1.4) * s\n\t\t\tBuild.ghost(Build.cyl(m, r, 3.4 * s, base * CFrame.new(0, (6.5 + i * 3) * s, 0), C.darkLeaf, Enum.Material.Grass))\n\t\tend\n\telseif kind == \"dry\" then\n\t\tBuild.cyl(m, 0.6 * s, 7 * s, base * CFrame.new(0, 3.5 * s, 0), hex(\"#7a6248\"), Enum.Material.Wood)\n\t\tBuild.ghost(Build.ball(m, 6 * s, base * CFrame.new(0, 8.5 * s, 0), hex(\"#b7a44e\"), Enum.Material.Grass))\n\telseif kind == \"cactus\" then\n\t\tBuild.cyl(m, 0.9 * s, 7 * s, base * CFrame.new(0, 3.5 * s, 0), hex(\"#4f8f4a\"))\n\t\tBuild.deco(m, Vector3.new(3 * s, 1 * s, 1 * s), base * CFrame.new(1.4 * s, 4 * s, 0), hex(\"#4f8f4a\"))\n\t\tBuild.deco(m, Vector3.new(1 * s, 2.4 * s, 1 * s), base * CFrame.new(2.6 * s, 5 * s, 0), hex(\"#4f8f4a\"))\n\telseif kind == \"jungle\" then\n\t\tBuild.cyl(m, 1.1 * s, 12 * s, base * CFrame.new(0, 6 * s, 0), hex(\"#5b4630\"), Enum.Material.Wood)\n\t\tBuild.ghost(Build.ball(m, 12 * s, base * CFrame.new(0, 14 * s, 0), hex(\"#1f7a3d\"), Enum.Material.Grass))\n\t\tBuild.ghost(Build.ball(m, 8 * s, base * CFrame.new(3 * s, 11 * s, 2 * s), hex(\"#2f9950\"), Enum.Material.Grass))\n\telse -- round\n\t\tBuild.cyl(m, 0.8 * s, 6 * s, base * CFrame.new(0, 3 * s, 0), C.darkWood, Enum.Material.Wood)\n\t\tBuild.ghost(Build.ball(m, 8 * s, base * CFrame.new(0, 8.5 * s, 0), C.leaf, Enum.Material.Grass))\n\tend\nend\n\n-- Casita de barrio: cuerpo, techo de teja a dos aguas, puerta y ventana. Mira hacia -Z local.\nfunction Build.house(parent: Instance, cf: CFrame, w: number, h: number, d: number, wall: Color3, roof: Color3?): Model\n\tlocal m = Build.model(parent, \"Casa\")\n\tBuild.part(m, Vector3.new(w, h, d), cf * CFrame.new(0, h / 2, 0), wall, Enum.Material.Concrete)\n\tlocal rc = roof or C.roof\n\tlocal rh = math.max(1.5, h * 0.35)\n\tBuild.wedge(m, Vector3.new(w + 1, rh, d / 2 + 0.5), cf * CFrame.new(0, h + rh / 2, d / 4 + 0.25) * CFrame.Angles(0, math.rad(180), 0), rc, Enum.Material.Slate)\n\tBuild.wedge(m, Vector3.new(w + 1, rh, d / 2 + 0.5), cf * CFrame.new(0, h + rh / 2, -d / 4 - 0.25), rc, Enum.Material.Slate)\n\tBuild.deco(m, Vector3.new(math.min(3, w * 0.3), math.min(5.5, h * 0.7), 0.3), cf * CFrame.new(-w * 0.2, math.min(5.5, h * 0.7) / 2, -d / 2 - 0.1), C.darkWood, Enum.Material.Wood)\n\tBuild.deco(m, Vector3.new(math.min(2.6, w * 0.25), 2.4, 0.3), cf * CFrame.new(w * 0.22, h * 0.55, -d / 2 - 0.1), hex(\"#bfe6f5\"), Enum.Material.Glass)\n\treturn m\nend\n\n-- Banca con asiento de verdad (el personaje se sienta al tocarla).\nfunction Build.bench(parent: Instance, cf: CFrame, color: Color3?): Seat\n\tlocal m = Build.model(parent, \"Banca\")\n\tlocal seat = Instance.new(\"Seat\")\n\tseat.Anchored = true\n\tseat.Size = Vector3.new(6, 0.6, 2)\n\tseat.CFrame = cf * CFrame.new(0, 1.6, 0)\n\tseat.Color = color or C.wood\n\tseat.Material = Enum.Material.Wood\n\tseat.TopSurface = SMOOTH\n\tseat.BottomSurface = SMOOTH\n\tseat.Parent = m\n\tBuild.part(m, Vector3.new(6, 2, 0.5), cf * CFrame.new(0, 2.8, 1), color or C.wood, Enum.Material.Wood)\n\tfor _, x in { -2.5, 2.5 } do\n\t\tBuild.deco(m, Vector3.new(0.5, 1.4, 1.8), cf * CFrame.new(x, 0.7, 0), C.darkGray, Enum.Material.Metal)\n\tend\n\treturn seat\nend\n\nfunction Build.lamp(parent: Instance, pos: Vector3)\n\tlocal m = Build.model(parent, \"Farol\")\n\tBuild.cyl(m, 0.3, 10, CFrame.new(pos) * CFrame.new(0, 5, 0), C.darkGray, Enum.Material.Metal)\n\tlocal bulb = Build.ghost(Build.ball(m, 1.6, CFrame.new(pos) * CFrame.new(0, 10.6, 0), hex(\"#fff3c4\"), Enum.Material.Neon))\n\tlocal light = Instance.new(\"PointLight\")\n\tlight.Range = 22\n\tlight.Brightness = 0.6\n\tlight.Color = hex(\"#ffe9a8\")\n\tlight.Parent = bulb\nend\n\n-- Lempirita: moneda del mundo. El servidor la detecta con Touched (etiqueta \"Moneda\").\nfunction Build.coin(parent: Instance, pos: Vector3): Part\n\tlocal coin = Build.part(parent, Vector3.new(0.4, 2.2, 2.2), CFrame.new(pos) * CFrame.Angles(0, math.rad(90), 0), C.gold, Enum.Material.Neon, { CanCollide = false, CanQuery = false })\n\tcoin.Shape = Enum.PartType.Cylinder\n\tcoin.Name = \"Lempirita\"\n\tCollectionService:AddTag(coin, \"Moneda\")\n\treturn coin\nend\n\n-- Cono o cerro escalonado hecho de cilindros apilados.\nfunction Build.stack(parent: Instance, cf: CFrame, baseRadius: number, topRadius: number, height: number, levels: number, color: Color3, material: Enum.Material?, topColor: Color3?)\n\tlocal h = height / levels\n\tfor i = 0, levels - 1 do\n\t\tlocal t = if levels > 1 then i / (levels - 1) else 0\n\t\tlocal r = baseRadius + (topRadius - baseRadius) * t\n\t\tlocal col = if topColor then color:Lerp(topColor, t) else color\n\t\tBuild.cyl(parent, r, h, cf * CFrame.new(0, h * (i + 0.5), 0), col, material or Enum.Material.Grass)\n\tend\nend\n\nexport type FigureColors = { skin: Color3, shirt: Color3, pants: Color3, hair: Color3? }\n\n-- Personaje de bloques (estatuas, clientes, bots). El pivote queda en los pies.\nfunction Build.figure(parent: Instance, cf: CFrame, colors: FigureColors, scale: number?, collide: boolean?): Model\n\tlocal s = scale or 1\n\tlocal m = Build.model(parent, \"Figura\")\n\tlocal props = { CanCollide = collide == true, CanTouch = collide == true, CanQuery = collide == true }\n\tlocal torso = Build.part(m, Vector3.new(2 * s, 2 * s, 1 * s), cf * CFrame.new(0, 3 * s, 0), colors.shirt, nil, props)\n\ttorso.Name = \"Torso\"\n\tBuild.part(m, Vector3.new(0.9 * s, 2 * s, 0.9 * s), cf * CFrame.new(-0.5 * s, 1 * s, 0), colors.pants, nil, props)\n\tBuild.part(m, Vector3.new(0.9 * s, 2 * s, 0.9 * s), cf * CFrame.new(0.5 * s, 1 * s, 0), colors.pants, nil, props)\n\tBuild.part(m, Vector3.new(0.9 * s, 2 * s, 0.9 * s), cf * CFrame.new(-1.5 * s, 3 * s, 0), colors.skin, nil, props).Name = \"BrazoIzq\"\n\tBuild.part(m, Vector3.new(0.9 * s, 2 * s, 0.9 * s), cf * CFrame.new(1.5 * s, 3 * s, 0), colors.skin, nil, props).Name = \"BrazoDer\"\n\tlocal head = Build.part(m, Vector3.new(1.3 * s, 1.3 * s, 1.3 * s), cf * CFrame.new(0, 4.65 * s, 0), colors.skin, nil, props)\n\thead.Name = \"Cabeza\"\n\tif colors.hair then\n\t\tBuild.part(m, Vector3.new(1.4 * s, 0.5 * s, 1.4 * s), cf * CFrame.new(0, 5.4 * s, 0), colors.hair, nil, props)\n\tend\n\ttorso.PivotOffset = CFrame.new(0, -3 * s, 0)\n\tm.PrimaryPart = torso\n\treturn m\nend\n\n-- Bandera de Honduras: franjas azul turquesa, blanca y azul, con cinco estrellas.\nfunction Build.flag(parent: Instance, cf: CFrame, width: number, height: number): Model\n\tlocal m = Build.model(parent, \"Bandera\")\n\tlocal stripe = height / 3\n\tBuild.deco(m, Vector3.new(width, stripe, 0.3), cf * CFrame.new(0, stripe, 0), C.blue, Enum.Material.Fabric)\n\tlocal middle = Build.deco(m, Vector3.new(width, stripe, 0.3), cf, C.white, Enum.Material.Fabric)\n\tBuild.deco(m, Vector3.new(width, stripe, 0.3), cf * CFrame.new(0, -stripe, 0), C.blue, Enum.Material.Fabric)\n\tfor _, face in { Enum.NormalId.Front, Enum.NormalId.Back } do\n\t\tBuild.text(middle, \"★ ★\\n★\\n★ ★\", { color = C.blue, face = face, font = Enum.Font.GothamBold, pad = 0.02 }).LineHeight = 0.62\n\tend\n\treturn m\nend\n\n-- Portal de minijuego: arco con luz y aviso. Devuelve la pieza que lleva el ProximityPrompt.\nfunction Build.portal(parent: Instance, cf: CFrame, color: Color3, title: string, icon: string): Part\n\tlocal m = Build.model(parent, \"Portal\")\n\tfor _, x in { -4.5, 4.5 } do\n\t\tBuild.part(m, Vector3.new(1.6, 11, 1.6), cf * CFrame.new(x, 5.5, 0), color, Enum.Material.Concrete)\n\tend\n\tBuild.part(m, Vector3.new(11.6, 1.8, 1.8), cf * CFrame.new(0, 11.6, 0), color, Enum.Material.Concrete)\n\tlocal glow = Build.part(m, Vector3.new(7.4, 10.4, 0.4), cf * CFrame.new(0, 5.4, 0), color:Lerp(C.white, 0.45), Enum.Material.Neon, { CanCollide = false, Transparency = 0.35 })\n\tglow.Name = \"Luz\"\n\tBuild.label(glow, icon .. \" \" .. title, 9, C.white, 16)\n\treturn glow\nend\n\n-- Plataforma redonda de viaje. Devuelve la pieza para colgarle el aviso.\nfunction Build.pad(parent: Instance, cf: CFrame, color: Color3, radius: number?): Part\n\tlocal r = radius or 3\n\tlocal pad = Build.cyl(parent, r, 0.5, cf * CFrame.new(0, 0.25, 0), color, Enum.Material.Neon)\n\tpad.Name = \"Plataforma\"\n\tBuild.ghost(Build.cyl(parent, r + 0.5, 0.3, cf * CFrame.new(0, 0.15, 0), C.white, Enum.Material.SmoothPlastic))\n\treturn pad\nend\n\n-- Muros invisibles alrededor de un rectángulo para que nadie se caiga.\nfunction Build.walls(parent: Instance, cf: CFrame, sizeX: number, sizeZ: number, height: number)\n\tlocal props = { Transparency = 1, CanQuery = false, CastShadow = false, Name = \"Muro\" }\n\tBuild.part(parent, Vector3.new(sizeX + 4, height, 2), cf * CFrame.new(0, height / 2, -sizeZ / 2 - 1), C.white, nil, props)\n\tBuild.part(parent, Vector3.new(sizeX + 4, height, 2), cf * CFrame.new(0, height / 2, sizeZ / 2 + 1), C.white, nil, props)\n\tBuild.part(parent, Vector3.new(2, height, sizeZ + 4), cf * CFrame.new(-sizeX / 2 - 1, height / 2, 0), C.white, nil, props)\n\tBuild.part(parent, Vector3.new(2, height, sizeZ + 4), cf * CFrame.new(sizeX / 2 + 1, height / 2, 0), C.white, nil, props)\nend\n\n-- Número pseudoaleatorio estable (misma semilla, mismo mundo en cada servidor).\nfunction Build.rng(seed: number): (min: number, max: number) -> number\n\tlocal state = seed % 2147483647\n\tif state <= 0 then\n\t\tstate += 2147483646\n\tend\n\treturn function(min: number, max: number): number\n\t\tstate = (state * 48271) % 2147483647\n\t\treturn min + (max - min) * (state / 2147483647)\n\tend\nend\n\nreturn Build\n"},{"path":"src/server/World/HondurasMap.luau","code":"--!strict\n-- Mapa pisable de Honduras: cada departamento se rellena con franjas a partir de los contornos reales\n-- de departments.json y lleva una plataforma de viaje en su centro.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal GameData = require(Shared.GameData)\nlocal Polygon = require(Shared.Logic.Polygon)\nlocal Build = require(script.Parent.Build)\n\nlocal HondurasMap = {}\n\nlocal STEP = 8 -- alto de franja en unidades del viewBox\n\n-- origin: esquina noroeste (x menor, z menor). Devuelve los avisos de viaje por departamento.\nfunction HondurasMap.build(parent: Instance, origin: Vector3, scale: number): { [string]: ProximityPrompt }\n\tlocal folder = Build.folder(parent, \"MapaHonduras\")\n\tlocal vb = GameData.viewBox\n\tlocal w, d = vb[1] * scale, vb[2] * scale\n\tlocal base = CFrame.new(origin)\n\tlocal prompts: { [string]: ProximityPrompt } = {}\n\n\t-- mar\n\tBuild.part(folder, Vector3.new(w + 16, 0.6, d + 16), base * CFrame.new(w / 2, -0.3, d / 2), Build.hex(\"#2b8fd0\"), Enum.Material.SmoothPlastic).Name = \"Mar\"\n\tBuild.part(folder, Vector3.new(w + 20, 0.4, d + 20), base * CFrame.new(w / 2, -0.4, d / 2), Build.C.white).Name = \"Borde\"\n\n\tfor _, dept in GameData.departments do\n\t\tlocal model = Build.model(folder, dept.id)\n\t\tlocal color = Build.hex(dept.colors[1])\n\t\tfor _, ring in dept.map.rings do\n\t\t\tlocal spans = Polygon.scanlines({ ring }, STEP)\n\t\t\tif #spans == 0 then\n\t\t\t\tlocal minX, minY, maxX, maxY = Polygon.bounds({ ring })\n\t\t\t\ttable.insert(spans, { y = (minY + maxY) / 2, x0 = minX, x1 = maxX })\n\t\t\tend\n\t\t\tfor _, span in spans do\n\t\t\t\tlocal len = math.max(0.8, (span.x1 - span.x0) * scale)\n\t\t\t\tlocal cx = (span.x0 + span.x1) / 2 * scale\n\t\t\t\tlocal strip = Build.part(model, Vector3.new(len, 0.5, STEP * scale + 0.05), base * CFrame.new(cx, 0.25, span.y * scale), color, Enum.Material.SmoothPlastic)\n\t\t\t\tstrip.Name = \"Franja\"\n\t\t\tend\n\t\tend\n\t\tlocal c = dept.map.center\n\t\tlocal pad = Build.pad(model, base * CFrame.new(c[1] * scale, 0.5, c[2] * scale), Build.hex(dept.colors[2]), 2.2)\n\t\tpad.Name = \"Viaje\"\n\t\tBuild.label(pad, dept.name, 3.2, Build.C.white, 9)\n\t\tlocal prompt = Build.prompt(pad, \"Viajar\", dept.name, 0.4, 9)\n\t\tprompt:SetAttribute(\"Dept\", dept.id)\n\t\tprompts[dept.id] = prompt\n\tend\n\n\tlocal title = Build.sign(folder, base * CFrame.new(w / 2, 0, -11), 46, 7, \"🗺️ Mapa de Honduras · parate en un departamento y viajá\", { color = Build.C.navy }, 4)\n\ttitle.Name = \"Titulo\"\n\treturn prompts\nend\n\nreturn HondurasMap\n"},{"path":"src/server/World/Landmarks.luau","code":"--!strict\n-- Un constructor por tipo de lugar emblemático (landmark.kind en departments.json).\n-- Cada función recibe el punto central del lugar y devuelve dónde esconder el recuerdo (relativo a ese punto).\nlocal Build = require(script.Parent.Build)\n\nlocal C = Build.C\nlocal hex = Build.hex\nlocal V3 = Vector3.new\nlocal CF = CFrame.new\nlocal ANG = CFrame.Angles\nlocal rad = math.rad\nlocal part, deco, cyl, ball, wedge = Build.part, Build.deco, Build.cyl, Build.ball, Build.wedge\nlocal Rock, Wood, Concrete, Grass = Enum.Material.Slate, Enum.Material.Wood, Enum.Material.Concrete, Enum.Material.Grass\n\nexport type Builder = (m: Model, cf: CFrame, rng: (number, number) -> number) -> Vector3\n\nlocal Landmarks: { [string]: Builder } = {}\n\nlocal function water(m: Instance, size: Vector3, cf: CFrame): Part\n\treturn Build.ghost(part(m, size, cf, C.water, Enum.Material.Glass, { Transparency = 0.3, Name = \"Agua\" }))\nend\n\nlocal function cannon(m: Instance, cf: CFrame)\n\tBuild.ghost(cyl(m, 0.7, 5, cf * CF(0, 1.8, 0) * ANG(rad(-80), 0, 0), C.black, Enum.Material.Metal))\n\tdeco(m, V3(2.4, 1.2, 3), cf * CF(0, 0.8, 0.4), C.darkWood, Wood)\nend\n\nlocal function boat(m: Instance, cf: CFrame, color: Color3)\n\tpart(m, V3(4, 1.4, 10), cf * CF(0, 0.7, 0), color, Wood).Name = \"Lancha\"\n\twedge(m, V3(4, 1.4, 3), cf * CF(0, 0.7, -6.5) * ANG(0, rad(180), 0), color, Wood)\n\tdeco(m, V3(3.6, 0.3, 1), cf * CF(0, 1.5, 1), C.wood, Wood)\nend\n\nlocal function stall(m: Instance, cf: CFrame, awning: Color3, goods: { Color3 })\n\tfor _, o in { V3(-3.5, 3.5, -2), V3(3.5, 3.5, -2), V3(-3.5, 3.5, 2), V3(3.5, 3.5, 2) } do\n\t\tdeco(m, V3(0.4, 7, 0.4), cf * CF(o), C.darkWood, Wood)\n\tend\n\tpart(m, V3(8.6, 0.4, 5.6), cf * CF(0, 7.2, 0) * ANG(rad(-8), 0, 0), awning, Enum.Material.Fabric).Name = \"Toldo\"\n\tpart(m, V3(7, 0.5, 3), cf * CF(0, 2.6, 0), C.wood, Wood).Name = \"Mesa\"\n\tfor _, o in { V3(-3, 1.2, 0), V3(3, 1.2, 0) } do\n\t\tdeco(m, V3(0.5, 2.4, 2.6), cf * CF(o), C.darkWood, Wood)\n\tend\n\tfor i, g in goods do\n\t\tBuild.ghost(ball(m, 1.1, cf * CF(-3.4 + i * 1.3, 3.3, 0), g))\n\tend\nend\n\n-- Atlántida: malecón de La Ceiba con Pico Bonito al fondo.\nLandmarks.playa = function(m, cf, _rng)\n\twater(m, V3(190, 0.4, 70), cf * CF(0, 0.25, -44))\n\tpart(m, V3(8, 1, 50), cf * CF(0, 0.9, -24), C.wood, Enum.Material.WoodPlanks).Name = \"Malecon\"\n\twedge(m, V3(8, 1.4, 5), cf * CF(0, 0.7, 3.5) * ANG(0, rad(180), 0), C.wood, Enum.Material.WoodPlanks)\n\tfor i = 0, 4 do\n\t\tfor _, x in { -4.4, 4.4 } do\n\t\t\tdeco(m, V3(0.7, 4, 0.7), cf * CF(x, 2, -2 - i * 11), C.darkWood, Wood)\n\t\tend\n\tend\n\tBuild.stack(m, cf * CF(-52, 0, -30), 24, 3, 46, 7, hex(\"#3f9b4b\"), Grass, hex(\"#1f5f3a\"))\n\tBuild.stack(m, cf * CF(-30, 0, -46), 16, 3, 28, 5, hex(\"#4aa857\"), Grass, hex(\"#2a6f45\"))\n\tfor _, x in { 22, 40 } do\n\t\tcyl(m, 0.25, 7, cf * CF(x, 3.5, 6), C.white)\n\t\tBuild.stack(m, cf * CF(x, 6.4, 6), 4.5, 0.6, 1.6, 2, if x == 22 then C.red else C.yellow, Enum.Material.Fabric)\n\tend\n\tBuild.tree(m, \"palm\", (cf * CF(30, 0, -6)).Position, 1)\n\tBuild.tree(m, \"palm\", (cf * CF(54, 0, 2)).Position, 1.15)\n\treturn V3(-64, 2, -50)\nend\n\n-- Choluteca: puente colgante sobre el río.\nLandmarks.puente = function(m, cf, _rng)\n\twater(m, V3(190, 0.4, 36), cf * CF(0, 0.25, -10))\n\tpart(m, V3(10, 1, 60), cf * CF(0, 6.5, -10), C.darkGray, Enum.Material.Metal).Name = \"Puente\"\n\twedge(m, V3(10, 7, 16), cf * CF(0, 3.5, 28) * ANG(0, rad(180), 0), C.stone, Concrete)\n\twedge(m, V3(10, 7, 16), cf * CF(0, 3.5, -48), C.stone, Concrete)\n\tfor _, z in { 8, -28 } do\n\t\tfor _, x in { -5.6, 5.6 } do\n\t\t\tpart(m, V3(1.6, 30, 1.6), cf * CF(x, 15, z), C.orange, Enum.Material.Metal).Name = \"Torre\"\n\t\tend\n\t\tdeco(m, V3(12.8, 1.4, 1.4), cf * CF(0, 29, z), C.orange, Enum.Material.Metal)\n\tend\n\tfor _, x in { -5.6, 5.6 } do\n\t\tdeco(m, V3(0.4, 0.4, 36), cf * CF(x, 28.5, -10), C.white, Enum.Material.Metal)\n\t\tdeco(m, V3(0.4, 0.4, 25), cf * CF(x, 18, 18) * ANG(rad(-62), 0, 0), C.white, Enum.Material.Metal)\n\t\tdeco(m, V3(0.4, 0.4, 25), cf * CF(x, 18, -38) * ANG(rad(62), 0, 0), C.white, Enum.Material.Metal)\n\t\tfor i = 0, 4 do\n\t\t\tdeco(m, V3(0.25, 21, 0.25), cf * CF(x, 17.6, 2 - i * 6), C.white, Enum.Material.Metal)\n\t\tend\n\t\tdeco(m, V3(0.4, 2.4, 60), cf * CF(x * 0.88, 8.2, -10), C.orange, Enum.Material.Metal)\n\tend\n\tBuild.tree(m, \"dry\", (cf * CF(-36, 0, 22)).Position, 1)\n\tBuild.tree(m, \"cactus\", (cf * CF(34, 0, 24)).Position, 1)\n\treturn V3(10, 2, -12)\nend\n\n-- Colón: Fortaleza de Santa Bárbara en Trujillo.\nLandmarks.fortaleza = function(m, cf, _rng)\n\twater(m, V3(190, 0.4, 40), cf * CF(0, 0.25, -58))\n\tlocal wall = hex(\"#b9b3a3\")\n\tpart(m, V3(56, 9, 4), cf * CF(0, 4.5, -32), wall, Enum.Material.Cobblestone)\n\tpart(m, V3(4, 9, 52), cf * CF(-28, 4.5, -6), wall, Enum.Material.Cobblestone)\n\tpart(m, V3(4, 9, 52), cf * CF(28, 4.5, -6), wall, Enum.Material.Cobblestone)\n\tpart(m, V3(22, 9, 4), cf * CF(-17, 4.5, 20), wall, Enum.Material.Cobblestone)\n\tpart(m, V3(22, 9, 4), cf * CF(17, 4.5, 20), wall, Enum.Material.Cobblestone)\n\tpart(m, V3(12, 3, 4), cf * CF(0, 7.5, 20), wall, Enum.Material.Cobblestone).Name = \"Arco\"\n\tfor _, o in { V3(-28, 0, -32), V3(28, 0, -32), V3(-28, 0, 20), V3(28, 0, 20) } do\n\t\tcyl(m, 6, 12, cf * CF(o) * CF(0, 6, 0), wall, Enum.Material.Cobblestone)\n\t\tBuild.stack(m, cf * CF(o) * CF(0, 12, 0), 6.6, 0.8, 4, 3, C.roof, Enum.Material.Slate)\n\tend\n\tfor i = -3, 3 do\n\t\tdeco(m, V3(3, 2, 4.2), cf * CF(i * 7, 10, -32), wall, Enum.Material.Cobblestone)\n\tend\n\tfor _, x in { -14, 0, 14 } do\n\t\tcannon(m, cf * CF(x, 0, -24))\n\tend\n\tcyl(m, 0.3, 18, cf * CF(0, 9, -6), C.gray, Enum.Material.Metal)\n\tBuild.flag(m, cf * CF(4, 16, -6), 8, 4.5)\n\treturn V3(40, 2, -38)\nend\n\n-- Comayagua: catedral colonial con el reloj más antiguo de América.\nLandmarks.catedral = function(m, cf, _rng)\n\tlocal wall = hex(\"#f7f1e3\")\n\tpart(m, V3(34, 20, 30), cf * CF(4, 10, -18), wall, Concrete).Name = \"Nave\"\n\tpart(m, V3(24, 26, 3), cf * CF(4, 13, -2), wall, Concrete).Name = \"Fachada\"\n\tpart(m, V3(11, 38, 11), cf * CF(-16, 19, -6), wall, Concrete).Name = \"Torre\"\n\tball(m, 11, cf * CF(-16, 39, -6), hex(\"#c9d6df\"), Concrete)\n\tdeco(m, V3(0.6, 5, 0.6), cf * CF(-16, 46.5, -6), C.gold, Enum.Material.Metal)\n\tdeco(m, V3(2.6, 0.6, 0.6), cf * CF(-16, 47.4, -6), C.gold, Enum.Material.Metal)\n\tlocal clock = Build.ghost(cyl(m, 3.4, 0.5, cf * CF(-16, 28, -0.3) * ANG(rad(90), 0, 0), C.white))\n\tclock.Name = \"Reloj\"\n\tlocal face = deco(m, V3(5, 5, 0.2), cf * CF(-16, 28, 0.1), C.white, nil, { Transparency = 1 })\n\tBuild.text(face, \"🕛\", { face = Enum.NormalId.Back })\n\tdeco(m, V3(8, 12, 0.5), cf * CF(4, 6, -0.3), C.darkWood, Wood).Name = \"Puerta\"\n\tball(m, 14, cf * CF(8, 22, -22), hex(\"#e8dcc6\"), Concrete)\n\tpart(m, V3(40, 0.6, 14), cf * CF(0, 0.3, 8), hex(\"#d9d2c0\"), Enum.Material.Cobblestone).Name = \"Atrio\"\n\tBuild.tree(m, \"round\", (cf * CF(34, 0, 6)).Position, 1)\n\treturn V3(26, 2, -40)\nend\n\n-- Copán: pirámide escalonada, estelas y juego de pelota.\nLandmarks.ruinas = function(m, cf, _rng)\n\tlocal stone = hex(\"#b7ab8f\")\n\tfor i = 0, 4 do\n\t\tlocal s = 44 - i * 8\n\t\tpart(m, V3(s, 4, s), cf * CF(0, 2 + i * 4, -10), stone:Lerp(hex(\"#8f8468\"), i / 6), Enum.Material.Cobblestone).Name = \"Nivel\"\n\tend\n\twedge(m, V3(8, 20, 20), cf * CF(0, 10, 6) * ANG(0, rad(180), 0), hex(\"#d6cbb0\"), Enum.Material.Cobblestone).Name = \"Escalinata\"\n\tpart(m, V3(8, 6, 6), cf * CF(0, 23, -12), hex(\"#8f8468\"), Enum.Material.Cobblestone).Name = \"Templo\"\n\tdeco(m, V3(3, 4, 0.4), cf * CF(0, 22, -8.9), C.black)\n\tfor i, o in { V3(-40, 0, 28), V3(-32, 0, 34), V3(-46, 0, 36) } do\n\t\tlocal stela = part(m, V3(2.6, 8 + i, 1.6), cf * CF(o) * CF(0, 4 + i / 2, 0), hex(\"#9c9278\"), Rock)\n\t\tstela.Name = \"Estela\"\n\t\tBuild.text(stela, \"☀\\n◆\\n▲\", { color = hex(\"#5f563f\"), face = Enum.NormalId.Back })\n\tend\n\t-- juego de pelota\n\twedge(m, V3(24, 5, 8), cf * CF(40, 2.5, 14) * ANG(0, rad(90), 0), stone, Enum.Material.Cobblestone)\n\twedge(m, V3(24, 5, 8), cf * CF(56, 2.5, 14) * ANG(0, rad(-90), 0), stone, Enum.Material.Cobblestone)\n\tpart(m, V3(8, 0.3, 24), cf * CF(48, 0.15, 14), hex(\"#cdbf9b\"), Enum.Material.Sand).Name = \"Cancha\"\n\tBuild.tree(m, \"jungle\", (cf * CF(-62, 0, -30)).Position, 1)\n\tBuild.tree(m, \"jungle\", (cf * CF(60, 0, -36)).Position, 0.9)\n\treturn V3(24, 2, -38)\nend\n\n-- Cortés: Lago de Yojoa con muelle, lancha y comedor de pescado frito.\nLandmarks.lago = function(m, cf, _rng)\n\tBuild.ghost(cyl(m, 42, 0.4, cf * CF(0, 0.25, -4), C.water, Enum.Material.Glass, { Transparency = 0.25, Name = \"Lago\" }))\n\tpart(m, V3(6, 1, 28), cf * CF(0, 0.9, 30), C.wood, Enum.Material.WoodPlanks).Name = \"Muelle\"\n\twedge(m, V3(6, 1.4, 4), cf * CF(0, 0.7, 46) * ANG(0, rad(180), 0), C.wood, Enum.Material.WoodPlanks)\n\tboat(m, cf * CF(14, 0.3, 10) * ANG(0, rad(25), 0), C.red)\n\tboat(m, cf * CF(-18, 0.3, -14) * ANG(0, rad(-70), 0), C.blue)\n\tcyl(m, 7, 1, cf * CF(0, 0.5, -10), hex(\"#79c267\"), Grass).Name = \"Islote\"\n\tBuild.tree(m, \"round\", (cf * CF(-2, 1, -10)).Position, 0.8)\n\tBuild.house(m, cf * CF(-54, 0, 30) * ANG(0, rad(-90), 0), 16, 9, 12, hex(\"#ffe8a3\"), C.roof)\n\tBuild.sign(m, cf * CF(-42, 0, 42) * ANG(0, rad(180), 0), 10, 2.6, \"🐟 Pescado frito\", { color = C.red }, 3)\n\tfor i = 0, 5 do\n\t\tdeco(m, V3(0.5, 5, 0.5), cf * CF(40 + (i % 3) * 2, 2.5, -24 + i * 1.6), hex(\"#5a9a50\"), Grass)\n\tend\n\tBuild.stack(m, cf * CF(-46, 0, -46), 20, 4, 30, 5, hex(\"#4f8f4a\"), Grass, hex(\"#2d6a4f\"))\n\treturn V3(-46, 2, -70)\nend\n\n-- El Paraíso: Yuscarán, pueblo minero de casas blancas.\nLandmarks.pueblo = function(m, cf, _rng)\n\tpart(m, V3(46, 0.4, 40), cf * CF(0, 0.2, 6), hex(\"#cfc8b6\"), Enum.Material.Cobblestone).Name = \"Calle\"\n\tlocal spots = { CF(-34, 0, 14) * ANG(0, rad(-90), 0), CF(-34, 0, -6) * ANG(0, rad(-90), 0), CF(34, 0, 14) * ANG(0, rad(90), 0), CF(34, 0, -6) * ANG(0, rad(90), 0) }\n\tfor _, s in spots do\n\t\tBuild.house(m, cf * s, 15, 9, 12, C.white, C.roof)\n\tend\n\tBuild.stack(m, cf * CF(0, 0, -46), 34, 14, 28, 5, hex(\"#8d8a80\"), Rock, hex(\"#6f6c64\"))\n\tpart(m, V3(9, 9, 10), cf * CF(0, 4.5, -18), C.black, nil, { Name = \"Mina\", CanCollide = false })\n\tfor _, x in { -5, 5 } do\n\t\tpart(m, V3(1.2, 10, 1.2), cf * CF(x, 5, -12.6), C.darkWood, Wood)\n\tend\n\tpart(m, V3(11.4, 1.2, 1.2), cf * CF(0, 10.4, -12.6), C.darkWood, Wood)\n\tpart(m, V3(4, 3, 5), cf * CF(8, 2.2, -4), C.darkGray, Enum.Material.Metal).Name = \"Vagoneta\"\n\tBuild.ghost(ball(m, 2.4, cf * CF(8, 4, -4), C.gray, Enum.Material.Metal))\n\tdeco(m, V3(1, 0.3, 22), cf * CF(6.6, 0.2, -6), C.darkWood, Wood)\n\tdeco(m, V3(1, 0.3, 22), cf * CF(9.4, 0.2, -6), C.darkWood, Wood)\n\treturn V3(0, 2, -19)\nend\n\n-- Francisco Morazán: Cristo del Picacho sobre el cerro.\nLandmarks.cristo = function(m, cf, _rng)\n\tfor i = 0, 3 do\n\t\tcyl(m, 44 - i * 8, 4, cf * CF(0, 2 + i * 4, -10), hex(\"#6fae5e\"):Lerp(hex(\"#4f8f4a\"), i / 3), Grass).Name = \"Cerro\"\n\tend\n\twedge(m, V3(8, 16, 32), cf * CF(0, 8, 24) * ANG(0, rad(180), 0), C.stone, Concrete).Name = \"Gradas\"\n\tlocal base = cf * CF(0, 16, -12)\n\tpart(m, V3(9, 8, 9), base * CF(0, 4, 0), C.stone, Concrete).Name = \"Pedestal\"\n\tpart(m, V3(5, 16, 3.4), base * CF(0, 16, 0), C.white, Concrete).Name = \"Cristo\"\n\tpart(m, V3(18, 2.6, 2.6), base * CF(0, 21, 0), C.white, Concrete).Name = \"Brazos\"\n\tball(m, 3.6, base * CF(0, 25.6, 0), C.white, Concrete)\n\tBuild.tree(m, \"pine\", (cf * CF(-52, 0, 20)).Position, 1)\n\tBuild.tree(m, \"pine\", (cf * CF(54, 0, 16)).Position, 1.1)\n\tBuild.sign(m, cf * CF(14, 0, 36) * ANG(0, rad(180), 0), 10, 2.6, \"Mirador El Picacho\", { color = C.navy }, 3)\n\treturn V3(0, 18, -19)\nend\n\n-- Gracias a Dios: Río Plátano entre la selva.\nLandmarks.rio = function(m, cf, rng)\n\tlocal bends = { V3(-60, 0, 30), V3(-28, 0, 8), V3(6, 0, 20), V3(34, 0, -8), V3(64, 0, 6) }\n\tfor i = 1, #bends - 1 do\n\t\tlocal a, b = cf * bends[i], cf * bends[i + 1]\n\t\tlocal mid = a:Lerp(b, 0.5) + V3(0, 0.25, 0)\n\t\twater(m, V3(18, 0.4, (b - a).Magnitude + 14), CFrame.lookAt(mid, b + V3(0, 0.25, 0)))\n\tend\n\tpart(m, V3(2.4, 1.2, 14), cf * CF(2, 0.8, 18) * ANG(0, rad(60), 0), hex(\"#6b4a2b\"), Wood).Name = \"Pipante\"\n\tfor _ = 1, 9 do\n\t\tBuild.tree(m, \"jungle\", (cf * CF(rng(-66, 66), 0, rng(-56, -24))).Position, rng(0.8, 1.2))\n\tend\n\tlocal rock = part(m, V3(8, 7, 5), cf * CF(-20, 3.5, -16) * ANG(0, rad(20), 0), hex(\"#77766f\"), Rock)\n\trock.Name = \"Petroglifo\"\n\tBuild.text(rock, \"🌀 〰️ 🐒\", { color = C.white, face = Enum.NormalId.Back })\n\tBuild.ghost(ball(m, 2, cf * CF(30, 9, -30), C.red)).Name = \"Guara\"\n\treturn V3(-22, 2, -24)\nend\n\n-- Intibucá: mercado lenca de La Esperanza.\nLandmarks.mercado = function(m, cf, _rng)\n\tpart(m, V3(60, 0.4, 44), cf * CF(0, 0.2, -6), hex(\"#cfc8b6\"), Enum.Material.Cobblestone).Name = \"Plaza\"\n\tlocal awnings = { \"#7b2cbf\", \"#ffb703\", \"#ff5d9e\", \"#00a3d7\", \"#e63946\", \"#2ea44f\" }\n\tlocal goods = { hex(\"#c9a66b\"), C.red, C.green, C.yellow, C.orange }\n\tlocal n = 0\n\tfor _, z in { 4, -18 } do\n\t\tfor _, x in { -20, 0, 20 } do\n\t\t\tn += 1\n\t\t\tstall(m, cf * CF(x, 0, z), hex(awnings[n]), goods)\n\t\tend\n\tend\n\tBuild.figure(m, cf * CF(-20, 0.4, 7), { skin = hex(\"#a56b43\"), shirt = C.pink, pants = C.purple, hair = C.black }, 1)\n\tBuild.figure(m, cf * CF(20, 0.4, -15), { skin = hex(\"#c98f5f\"), shirt = C.yellow, pants = C.navy, hair = C.black }, 1)\n\tBuild.tree(m, \"pine\", (cf * CF(-48, 0, -24)).Position, 1)\n\tBuild.tree(m, \"pine\", (cf * CF(48, 0, -20)).Position, 0.9)\n\treturn V3(1.5, 1.4, -18)\nend\n\n-- Islas de la Bahía: arrecife de coral de Roatán.\nLandmarks.arrecife = function(m, cf, rng)\n\twater(m, V3(190, 0.5, 96), cf * CF(0, 0.3, -32))\n\tlocal corals = { \"#ff5d9e\", \"#ff7a3d\", \"#7b5cff\", \"#ffc93c\", \"#e63946\", \"#19b5c8\" }\n\tfor i = 1, 16 do\n\t\tlocal p = cf * CF(rng(-66, 66), 0, rng(-62, -8))\n\t\tlocal color = hex(corals[i % #corals + 1])\n\t\tif i % 2 == 0 then\n\t\t\tcyl(m, rng(0.8, 1.6), rng(2, 4), p * CF(0, 1.4, 0), color, Enum.Material.Sand).Name = \"Coral\"\n\t\telse\n\t\t\tball(m, rng(2.4, 4.4), p * CF(0, 1, 0), color, Enum.Material.Sand).Name = \"Coral\"\n\t\tend\n\tend\n\tfor i = 1, 6 do\n\t\tlocal p = cf * CF(rng(-50, 50), rng(1.2, 2.6), rng(-56, -12)) * ANG(0, rng(0, 6), 0)\n\t\tdeco(m, V3(0.5, 1.2, 2), p, if i % 2 == 0 then C.orange else C.yellow).Name = \"Pez\"\n\tend\n\tpart(m, V3(6, 1, 34), cf * CF(0, 0.9, 6), C.wood, Enum.Material.WoodPlanks).Name = \"Muelle\"\n\twedge(m, V3(6, 1.4, 4), cf * CF(0, 0.7, 25) * ANG(0, rad(180), 0), C.wood, Enum.Material.WoodPlanks)\n\tBuild.house(m, cf * CF(-50, 0, 30) * ANG(0, rad(-90), 0), 12, 8, 10, hex(\"#19b5c8\"), hex(\"#ffe8a3\"))\n\tBuild.sign(m, cf * CF(-40, 0, 40) * ANG(0, rad(180), 0), 9, 2.4, \"🤿 Buceo Roatán\", { color = C.navy }, 3)\n\tBuild.tree(m, \"palm\", (cf * CF(56, 0, 32)).Position, 1.1)\n\tBuild.tree(m, \"palm\", (cf * CF(40, 0, 40)).Position, 0.9)\n\treturn V3(10, 1.6, -48)\nend\n\n-- La Paz: cafetales de Marcala.\nLandmarks.cafetal = function(m, cf, _rng)\n\tfor row = 0, 3 do\n\t\tfor i = 0, 5 do\n\t\t\tlocal p = cf * CF(-40 + i * 9, 0, -6 - row * 11)\n\t\t\tBuild.ghost(ball(m, 5, p * CF(0, 2.4, 0), hex(\"#2f7d3b\"), Grass)).Name = \"Cafeto\"\n\t\t\tif (row + i) % 2 == 0 then\n\t\t\t\tBuild.ghost(ball(m, 0.9, p * CF(1.6, 3.4, 1.4), C.red))\n\t\t\tend\n\t\tend\n\tend\n\tpart(m, V3(24, 0.4, 16), cf * CF(34, 0.2, 18), hex(\"#d9c9a3\"), Concrete).Name = \"PatioDeSecado\"\n\tdeco(m, V3(18, 0.2, 10), cf * CF(34, 0.5, 18), hex(\"#7f5539\"), Enum.Material.Sand)\n\tBuild.house(m, cf * CF(36, 0, -8) * ANG(0, rad(90), 0), 14, 9, 12, hex(\"#f3e6c8\"), hex(\"#d62828\"))\n\tfor i = 0, 2 do\n\t\tpart(m, V3(3, 2, 2), cf * CF(22 + i * 3.2, 1, 4), hex(\"#c9a66b\"), Enum.Material.Fabric).Name = \"Saco\"\n\tend\n\tBuild.tree(m, \"pine\", (cf * CF(-56, 0, -44)).Position, 1.1)\n\treturn V3(25, 1.6, 1.4)\nend\n\n-- Lempira: Fuerte San Cristóbal sobre Gracias.\nLandmarks.fuerte = function(m, cf, _rng)\n\tcyl(m, 36, 6, cf * CF(0, 3, -10), hex(\"#7fb069\"), Grass).Name = \"Loma\"\n\twedge(m, V3(10, 6, 14), cf * CF(0, 3, 32) * ANG(0, rad(180), 0), C.stone, Concrete).Name = \"Rampa\"\n\tlocal wall = hex(\"#e9e2cf\")\n\tfor i = 0, 7 do\n\t\tlocal a = rad(i * 45)\n\t\tif i ~= 0 then\n\t\t\tpart(m, V3(24, 5, 2), cf * CF(0, 8.5, -10) * ANG(0, a, 0) * CF(0, 0, 31), wall, Concrete).Name = \"Muralla\"\n\t\tend\n\tend\n\tfor _, a in { 135, 225 } do\n\t\tlocal p = cf * CF(0, 6, -10) * ANG(0, rad(a), 0) * CF(0, 0, 31)\n\t\tcyl(m, 3, 9, p * CF(0, 4.5, 0), wall, Concrete).Name = \"Garita\"\n\t\tBuild.stack(m, p * CF(0, 9, 0), 3.6, 0.5, 3.4, 3, C.roof, Enum.Material.Slate)\n\tend\n\tcannon(m, cf * CF(-10, 6, -30) * ANG(0, 0, 0))\n\tcannon(m, cf * CF(10, 6, -30))\n\tpart(m, V3(12, 7, 9), cf * CF(0, 9.5, -14), wall, Concrete).Name = \"Cuartel\"\n\tcyl(m, 0.3, 14, cf * CF(0, 20, -14), C.gray, Enum.Material.Metal)\n\tBuild.flag(m, cf * CF(3.6, 25, -14), 7, 4)\n\treturn V3(-24, 8, -34)\nend\n\n-- Ocotepeque: bosque nublado de Montecristo.\nLandmarks.bosque = function(m, cf, rng)\n\tfor _ = 1, 14 do\n\t\tBuild.tree(m, \"pine\", (cf * CF(rng(-66, 66), 0, rng(-60, 6))).Position, rng(0.9, 1.6))\n\tend\n\tfor _, o in { V3(-4, 7, 16), V3(4, 7, 16), V3(-4, 7, 24), V3(4, 7, 24) } do\n\t\tpart(m, V3(0.8, 14, 0.8), cf * CF(o), C.darkWood, Wood)\n\tend\n\tpart(m, V3(11, 0.8, 11), cf * CF(0, 14, 20), C.wood, Enum.Material.WoodPlanks).Name = \"Mirador\"\n\tlocal ladder = Instance.new(\"TrussPart\")\n\tladder.Name = \"Escalera\"\n\tladder.Anchored = true\n\tladder.Size = V3(2, 16, 2)\n\tladder.CFrame = cf * CF(6.5, 8, 20)\n\tladder.Color = C.darkWood\n\tladder.Parent = m\n\tpart(m, V3(11, 0.5, 0.5), cf * CF(0, 16.6, 14.7), C.darkWood, Wood)\n\tBuild.ghost(ball(m, 1.6, cf * CF(-3, 15.6, 17), hex(\"#1faa59\"))).Name = \"Quetzal\"\n\tlocal trunk = cyl(m, 3.4, 26, cf * CF(-30, 13, -20), hex(\"#5b4630\"), Wood)\n\ttrunk.Name = \"ArbolGigante\"\n\tBuild.ghost(ball(m, 26, cf * CF(-30, 30, -20), hex(\"#1f5f3a\"), Grass))\n\treturn V3(-30, 2, -25)\nend\n\n-- Olancho: Cuevas de Talgua, las calaveras brillantes.\nLandmarks.cuevas = function(m, cf, _rng)\n\tlocal rock = hex(\"#8a8578\")\n\tpart(m, V3(60, 30, 8), cf * CF(0, 15, -44), rock, Rock)\n\tpart(m, V3(8, 30, 40), cf * CF(-26, 15, -24), rock, Rock)\n\tpart(m, V3(8, 30, 40), cf * CF(26, 15, -24), rock, Rock)\n\tpart(m, V3(60, 8, 44), cf * CF(0, 34, -26), rock, Rock).Name = \"Techo\"\n\tpart(m, V3(16, 16, 6), cf * CF(-14, 22, -5), rock, Rock)\n\tpart(m, V3(16, 16, 6), cf * CF(14, 22, -5), rock, Rock)\n\tpart(m, V3(12, 14, 6), cf * CF(-16, 7, -5), rock, Rock)\n\tpart(m, V3(12, 14, 6), cf * CF(16, 7, -5), rock, Rock)\n\tBuild.stack(m, cf * CF(-36, 0, -30), 16, 6, 22, 4, rock, Rock)\n\tBuild.stack(m, cf * CF(36, 0, -30), 16, 6, 22, 4, rock, Rock)\n\tlocal glow = { \"#7df9ff\", \"#b4f8c8\", \"#fbe7c6\" }\n\tfor i, o in { V3(-14, 0, -30), V3(10, 0, -36), V3(-4, 0, -38), V3(16, 0, -22), V3(-18, 0, -16) } do\n\t\tlocal crystal = Build.ghost(part(m, V3(1.4, 4 + i % 3, 1.4), cf * CF(o) * CF(0, 2, 0) * ANG(rad(12), rad(i * 40), rad(8)), hex(glow[i % 3 + 1]), Enum.Material.Neon))\n\t\tcrystal.Name = \"Cristal\"\n\tend\n\tlocal light = Instance.new(\"PointLight\")\n\tlight.Range = 30\n\tlight.Color = hex(\"#7df9ff\")\n\tlight.Parent = part(m, V3(1, 1, 1), cf * CF(0, 12, -26), C.white, nil, { Transparency = 1, CanCollide = false, CanQuery = false })\n\tfor i = 0, 3 do\n\t\tBuild.stack(m, cf * CF(-10 + i * 7, 0, -28 - (i % 2) * 8), 1.4, 0.3, 4 + i, 3, hex(\"#a39d8d\"), Rock)\n\tend\n\tBuild.sign(m, cf * CF(20, 0, 8) * ANG(0, rad(180), 0), 10, 2.6, \"Cuevas de Talgua\", { color = C.navy }, 3)\n\treturn V3(18, 2, -38)\nend\n\n-- Santa Bárbara: taller de artesanías de junco.\nLandmarks.artesania = function(m, cf, _rng)\n\tfor _, o in { V3(-14, 5, -18), V3(14, 5, -18), V3(-14, 5, 0), V3(14, 5, 0) } do\n\t\tpart(m, V3(1, 10, 1), cf * CF(o), C.darkWood, Wood)\n\tend\n\tpart(m, V3(32, 1, 22), cf * CF(0, 10.5, -9), hex(\"#d9b36a\"), Enum.Material.WoodPlanks).Name = \"Techo\"\n\tpart(m, V3(20, 0.6, 5), cf * CF(0, 3, -6), C.wood, Wood).Name = \"Mesa\"\n\tfor _, x in { -9, 9 } do\n\t\tdeco(m, V3(0.8, 3, 4.4), cf * CF(x, 1.5, -6), C.darkWood, Wood)\n\tend\n\tlocal junco = hex(\"#e6cf8b\")\n\tfor i = 0, 3 do\n\t\tlocal p = cf * CF(-7.5 + i * 5, 3.3, -6)\n\t\tBuild.ghost(cyl(m, 2, 0.2, p * CF(0, 0.1, 0), junco, Enum.Material.Fabric)).Name = \"Sombrero\"\n\t\tBuild.ghost(cyl(m, 1, 1, p * CF(0, 0.7, 0), junco, Enum.Material.Fabric))\n\tend\n\tfor i = 0, 2 do\n\t\tcyl(m, 1.8, 2.6, cf * CF(-20 + i * 4.4, 1.3, 6), hex(\"#c9a66b\"), Enum.Material.Fabric).Name = \"Canasta\"\n\tend\n\tpart(m, V3(12, 8, 0.6), cf * CF(0, 5, -17), C.wood, Wood).Name = \"Estante\"\n\tfor i = 0, 2 do\n\t\tBuild.ghost(cyl(m, 1.6, 0.3, cf * CF(-4 + i * 4, 6, -16.4) * ANG(rad(90), 0, 0), junco, Enum.Material.Fabric))\n\tend\n\tBuild.figure(m, cf * CF(0, 0.4, -11), { skin = hex(\"#a56b43\"), shirt = C.white, pants = hex(\"#8d6e63\"), hair = C.black }, 1)\n\tBuild.house(m, cf * CF(40, 0, -10) * ANG(0, rad(90), 0), 14, 9, 12, hex(\"#e76f51\"), C.roof)\n\tBuild.tree(m, \"pine\", (cf * CF(-46, 0, -30)).Position, 1)\n\treturn V3(3, 2, -19.5)\nend\n\n-- Valle: Isla del Tigre, el volcán de Amapala.\nLandmarks.volcan = function(m, cf, _rng)\n\twater(m, V3(190, 0.4, 60), cf * CF(0, 0.25, 30))\n\tBuild.stack(m, cf * CF(0, 0, -22), 42, 8, 48, 8, hex(\"#4f8f4a\"), Grass, hex(\"#6b4a2b\"))\n\tBuild.ghost(cyl(m, 6, 1, cf * CF(0, 48.2, -22), hex(\"#3b2414\"), Rock)).Name = \"Crater\"\n\tboat(m, cf * CF(-30, 0.3, 34) * ANG(0, rad(80), 0), C.yellow)\n\tboat(m, cf * CF(26, 0.3, 40) * ANG(0, rad(-60), 0), C.blue)\n\tBuild.tree(m, \"palm\", (cf * CF(-52, 0, 8)).Position, 1)\n\tBuild.tree(m, \"palm\", (cf * CF(54, 0, 4)).Position, 1.1)\n\tBuild.sign(m, cf * CF(18, 0, 26) * ANG(0, rad(180), 0), 10, 2.6, \"Amapala · Isla del Tigre\", { color = C.navy }, 3)\n\treturn V3(0, 2, -68)\nend\n\n-- Yoro: la Lluvia de Peces.\nLandmarks.lluvia = function(m, cf, rng)\n\tfor i = 0, 3 do\n\t\tBuild.ghost(ball(m, 26 - (i % 2) * 6, cf * CF(-18 + i * 12, 46 + (i % 2) * 3, -14), hex(\"#6c757d\"), Enum.Material.SmoothPlastic)).Name = \"Nube\"\n\tend\n\tfor i = 1, 12 do\n\t\tlocal p = cf * CF(rng(-30, 30), rng(8, 38), rng(-30, 2))\n\t\tdeco(m, V3(0.15, 3, 0.15), p, hex(\"#bde0fe\"), Enum.Material.Neon, { Transparency = 0.4 }).Name = \"Gota\"\n\t\tif i % 2 == 0 then\n\t\t\tdeco(m, V3(0.5, 1, 1.8), p * CF(2, 1, 1) * ANG(rad(60), 0, 0), hex(\"#cfd8dc\"), Enum.Material.Metal).Name = \"Pez\"\n\t\tend\n\tend\n\tfor _ = 1, 10 do\n\t\tdeco(m, V3(0.5, 0.6, 1.8), cf * CF(rng(-34, 34), 0.3, rng(-34, 6)) * ANG(0, rng(0, 6), rad(90)), hex(\"#cfd8dc\"), Enum.Material.Metal).Name = \"Pez\"\n\tend\n\tBuild.house(m, cf * CF(40, 0, -20) * ANG(0, rad(90), 0), 13, 9, 12, C.white, C.roof)\n\tBuild.tree(m, \"round\", (cf * CF(-46, 0, -30)).Position, 1.1)\n\tBuild.sign(m, cf * CF(-20, 0, 20) * ANG(0, rad(180), 0), 10, 2.6, \"🐟 La Lluvia de Peces\", { color = C.navy }, 3)\n\treturn V3(-50, 2, -36)\nend\n\nreturn Landmarks\n"},{"path":"src/server/World/Lobby.luau","code":"--!strict\n-- Lobby inspirado en Tegucigalpa: parque central, catedral, estatua, pulpería, bandera, casas del cerro y terminal.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Config = require(Shared.Config)\nlocal GameData = require(Shared.GameData)\nlocal Build = require(script.Parent.Build)\nlocal HondurasMap = require(script.Parent.HondurasMap)\n\nlocal C = Build.C\nlocal hex = Build.hex\nlocal V3 = Vector3.new\nlocal CF = CFrame.new\nlocal rad = math.rad\n\nlocal Lobby = {}\n\nexport type Result = {\n\tportals: { [string]: ProximityPrompt },\n\tmapPrompts: { [string]: ProximityPrompt },\n\tshopPrompt: ProximityPrompt,\n\tterminalPrompt: ProximityPrompt,\n\tdanceFloor: Part,\n\tspawn: SpawnLocation,\n}\n\nlocal HOUSE_COLORS = { \"#ff7a3d\", \"#ffc93c\", \"#00a3d7\", \"#ff5d9e\", \"#2ea44f\", \"#7b5cff\", \"#e63946\", \"#19b5c8\", \"#f4a261\" }\nlocal PORTAL_COLORS = {\n\tcarrera = \"#e63946\",\n\tfutbol = \"#2ea44f\",\n\tferia = \"#ff5d9e\",\n\texploradores = \"#7b5cff\",\n\tpulperia = \"#ffc93c\",\n}\n\nlocal function ground(folder: Instance)\n\tBuild.part(folder, V3(380, 4, 420), CF(0, -2, 10), hex(\"#7cc36a\"), Enum.Material.Grass).Name = \"Suelo\"\n\tBuild.part(folder, V3(170, 0.4, 118), CF(0, 0, -34), hex(\"#d9d2c0\"), Enum.Material.Cobblestone).Name = \"Plaza\"\n\t-- calles alrededor del parque\n\tBuild.part(folder, V3(200, 0.3, 14), CF(0, 0, 34), C.asphalt, Enum.Material.Asphalt).Name = \"Calle\"\n\tBuild.part(folder, V3(14, 0.3, 140), CF(93, 0, -30), C.asphalt, Enum.Material.Asphalt).Name = \"Calle\"\n\tBuild.walls(folder, CF(0, 0, 10), 372, 412, 60)\nend\n\nlocal function cathedral(parent: Instance, cf: CFrame)\n\tlocal m = Build.model(parent, \"Catedral\")\n\tlocal wall = hex(\"#f4ecd8\")\n\tBuild.part(m, V3(44, 26, 34), cf * CF(0, 13, 0), wall, Enum.Material.Concrete).Name = \"Nave\"\n\tBuild.part(m, V3(28, 34, 3), cf * CF(0, 17, 18), wall, Enum.Material.Concrete).Name = \"Fachada\"\n\tBuild.wedge(m, V3(3, 6, 14), cf * CF(-7, 37, 18) * CFrame.Angles(0, rad(-90), 0), wall, Enum.Material.Concrete)\n\tBuild.wedge(m, V3(3, 6, 14), cf * CF(7, 37, 18) * CFrame.Angles(0, rad(90), 0), wall, Enum.Material.Concrete)\n\tfor _, x in { -21, 21 } do\n\t\tBuild.part(m, V3(11, 40, 11), cf * CF(x, 20, 14), wall, Enum.Material.Concrete).Name = \"Torre\"\n\t\tBuild.deco(m, V3(5, 7, 0.4), cf * CF(x, 31, 19.7), hex(\"#3b3026\"))\n\t\tBuild.ball(m, 11, cf * CF(x, 41, 14), hex(\"#e9dcc0\"), Enum.Material.Concrete)\n\t\tBuild.deco(m, V3(0.6, 5, 0.6), cf * CF(x, 48.5, 14), C.gold, Enum.Material.Metal)\n\t\tBuild.deco(m, V3(2.6, 0.6, 0.6), cf * CF(x, 49.5, 14), C.gold, Enum.Material.Metal)\n\tend\n\tBuild.deco(m, V3(9, 14, 0.5), cf * CF(0, 7, 19.7), C.darkWood, Enum.Material.Wood).Name = \"Puerta\"\n\tBuild.ghost(Build.cyl(m, 3.4, 0.5, cf * CF(0, 24, 19.7) * CFrame.Angles(rad(90), 0, 0), hex(\"#7fd0f2\"), Enum.Material.Glass))\n\tfor _, x in { -9, 9 } do\n\t\tBuild.cyl(m, 1, 20, cf * CF(x, 10, 20.4), hex(\"#fffaf0\"), Enum.Material.Marble)\n\tend\n\tBuild.part(m, V3(34, 1, 6), cf * CF(0, 0.5, 23), C.stone, Enum.Material.Concrete).Name = \"Gradas\"\n\tBuild.part(m, V3(38, 0.5, 4), cf * CF(0, 0.25, 27), C.stone, Enum.Material.Concrete)\n\tBuild.sign(m, cf * CF(26, 0, 30), 12, 3, \"Catedral de San Miguel Arcángel\", { color = C.navy }, 2)\nend\n\nlocal function kiosk(parent: Instance, cf: CFrame)\n\tlocal m = Build.model(parent, \"Kiosko\")\n\tBuild.cyl(m, 10, 1.6, cf * CF(0, 0.8, 0), hex(\"#e8e0cf\"), Enum.Material.Concrete)\n\tBuild.part(m, V3(6, 0.8, 4), cf * CF(0, 0.4, 11), C.stone, Enum.Material.Concrete)\n\tfor i = 0, 7 do\n\t\tlocal a = rad(i * 45 + 22.5)\n\t\tlocal p = cf * CF(math.sin(a) * 8.6, 0, math.cos(a) * 8.6)\n\t\tBuild.cyl(m, 0.45, 9, p * CF(0, 6.1, 0), C.white, Enum.Material.Metal)\n\t\tBuild.deco(m, V3(6.6, 1.2, 0.3), cf * CFrame.Angles(0, a + rad(22.5), 0) * CF(0, 2.6, 8.4), hex(\"#2c6e49\"), Enum.Material.Metal)\n\tend\n\tBuild.stack(m, cf * CF(0, 10.6, 0), 11, 2, 5, 4, C.roof, Enum.Material.Slate)\n\tBuild.ghost(Build.ball(m, 2.4, cf * CF(0, 16.4, 0), C.gold, Enum.Material.Metal))\nend\n\nlocal function statue(parent: Instance, cf: CFrame)\n\tlocal m = Build.model(parent, \"Estatua\")\n\tlocal bronze = hex(\"#5f7f6a\")\n\tBuild.part(m, V3(10, 1, 14), cf * CF(0, 0.5, 0), C.stone, Enum.Material.Concrete)\n\tBuild.part(m, V3(6, 8, 10), cf * CF(0, 5, 0), hex(\"#d8d2c2\"), Enum.Material.Marble).Name = \"Pedestal\"\n\t-- caballo\n\tBuild.part(m, V3(2.4, 3, 7), cf * CF(0, 13, 0), bronze, Enum.Material.Metal)\n\tfor _, o in { V3(-0.8, 10.5, -2.6), V3(0.8, 10.5, -2.6), V3(-0.8, 10.5, 2.6), V3(0.8, 10.5, 2.6) } do\n\t\tBuild.deco(m, V3(0.8, 3, 0.8), cf * CF(o), bronze, Enum.Material.Metal)\n\tend\n\tBuild.deco(m, V3(1.4, 3.4, 1.6), cf * CF(0, 15.2, -3.6) * CFrame.Angles(rad(-25), 0, 0), bronze, Enum.Material.Metal)\n\tBuild.deco(m, V3(1.2, 1.4, 2.6), cf * CF(0, 16.8, -4.9), bronze, Enum.Material.Metal)\n\tBuild.deco(m, V3(0.5, 2.6, 0.5), cf * CF(0, 13.4, 3.9) * CFrame.Angles(rad(35), 0, 0), bronze, Enum.Material.Metal)\n\t-- jinete\n\tBuild.figure(m, cf * CF(0, 13.4, 0.4), { skin = bronze, shirt = bronze, pants = bronze, hair = bronze }, 0.9)\n\tlocal plaque = Build.deco(m, V3(4.6, 2.4, 0.3), cf * CF(0, 5, -5.1), hex(\"#3b3026\"), Enum.Material.Metal)\n\tBuild.text(plaque, \"Parque Central\\nTegucigalpa\", { color = C.gold, face = Enum.NormalId.Front })\nend\n\nlocal function fountain(parent: Instance, cf: CFrame)\n\tlocal m = Build.model(parent, \"Fuente\")\n\tBuild.cyl(m, 8, 1.4, cf * CF(0, 0.7, 0), C.stone, Enum.Material.Concrete)\n\tBuild.ghost(Build.cyl(m, 7, 0.4, cf * CF(0, 1.5, 0), C.water, Enum.Material.Glass, { Transparency = 0.25 }))\n\tBuild.cyl(m, 1, 5, cf * CF(0, 3, 0), C.stone, Enum.Material.Concrete)\n\tBuild.cyl(m, 3, 0.6, cf * CF(0, 5.6, 0), C.stone, Enum.Material.Concrete)\n\tBuild.ghost(Build.ball(m, 2, cf * CF(0, 6.6, 0), C.water, Enum.Material.Glass, { Transparency = 0.2 }))\nend\n\nlocal function pulperia(parent: Instance, cf: CFrame): ProximityPrompt\n\tlocal m = Build.model(parent, \"PulperiaDonaTona\")\n\tlocal wall = hex(\"#ffd166\")\n\tBuild.part(m, V3(28, 13, 20), cf * CF(0, 6.5, 10), wall, Enum.Material.Concrete).Name = \"Local\"\n\tBuild.part(m, V3(30, 1, 23), cf * CF(0, 13.5, 9.5), C.roof, Enum.Material.Slate).Name = \"Techo\"\n\tBuild.deco(m, V3(28.2, 2.4, 0.3), cf * CF(0, 1.2, -0.1), C.blue, Enum.Material.Concrete)\n\t-- ventana mostrador y toldo de rayas\n\tBuild.deco(m, V3(14, 6, 0.4), cf * CF(-4, 6.4, -0.1), hex(\"#3a2a1d\"))\n\tBuild.part(m, V3(15, 1, 3), cf * CF(-4, 3.4, -1.4), C.wood, Enum.Material.Wood).Name = \"Mostrador\"\n\tfor i = 0, 5 do\n\t\tBuild.deco(m, V3(2.5, 0.4, 5), cf * CF(-10.25 + i * 2.5, 10.6, -2.2) * CFrame.Angles(rad(-18), 0, 0), if i % 2 == 0 then C.red else C.white, Enum.Material.Fabric)\n\tend\n\tBuild.deco(m, V3(4, 8, 0.4), cf * CF(9, 4, -0.1), C.darkWood, Enum.Material.Wood).Name = \"Puerta\"\n\tlocal board = Build.part(m, V3(22, 3.4, 0.5), cf * CF(0, 15.6, -1.4), C.navy, Enum.Material.Wood)\n\tBuild.text(board, \"Pulpería Doña Toña\", { color = C.yellow, face = Enum.NormalId.Front })\n\t-- Doña Toña y sus productos\n\tBuild.figure(m, cf * CF(-4, 0.4, 2) * CFrame.Angles(0, rad(180), 0), { skin = hex(\"#a56b43\"), shirt = C.pink, pants = C.purple, hair = hex(\"#3b2414\") }, 1.15)\n\tlocal goods = { \"#ff7a3d\", \"#ffc93c\", \"#2ea44f\", \"#e63946\", \"#ffffff\", \"#8d6e63\" }\n\tfor i, g in goods do\n\t\tBuild.ghost(Build.ball(m, 1.2, cf * CF(-10.5 + i * 1.9, 4.5, -1.6), hex(g)))\n\tend\n\tfor i = 0, 1 do\n\t\tBuild.part(m, V3(3, 2.4, 3), cf * CF(13.5, 1.2, -3 - i * 3.4), C.wood, Enum.Material.WoodPlanks).Name = \"Caja\"\n\tend\n\tlocal counter = Build.part(m, V3(6, 3, 2), cf * CF(-4, 3, -3.2), C.white, nil, { Transparency = 1, CanCollide = false })\n\tcounter.Name = \"Tienda\"\n\tBuild.label(counter, \"🛍️ Tienda\", 9, C.yellow, 10)\n\treturn Build.prompt(counter, \"Comprar\", \"Pulpería Doña Toña\", 0, 12)\nend\n\nlocal function hillside(parent: Instance)\n\tlocal m = Build.folder(parent, \"CasasDelCerro\")\n\tlocal rng = Build.rng(504)\n\tfor tier = 0, 2 do\n\t\tlocal x = -128 - tier * 22\n\t\tlocal h = (tier + 1) * 8\n\t\tBuild.part(m, V3(22, h, 300), CF(x, h / 2, -40), hex(\"#8fb86a\"), Enum.Material.Grass).Name = \"Terraza\"\n\t\tfor i = 0, 6 do\n\t\t\tlocal z = -170 + i * 42 + rng(-6, 6)\n\t\t\tlocal color = hex(HOUSE_COLORS[(tier * 3 + i) % #HOUSE_COLORS + 1])\n\t\t\tlocal w, hh, d = 13 + rng(0, 4), 8 + rng(0, 4), 12\n\t\t\tBuild.house(m, CF(x, h, z) * CFrame.Angles(0, rad(-90), 0), w, hh, d, color, if i % 3 == 0 then hex(\"#7d8791\") else C.roof)\n\t\tend\n\tend\n\tBuild.sign(m, CF(-112, 0, 16) * CFrame.Angles(0, rad(-90), 0), 12, 3, \"Barrio El Cerro\", { color = C.red }, 3)\nend\n\nlocal function busStop(parent: Instance, cf: CFrame): ProximityPrompt\n\tlocal m = Build.model(parent, \"Terminal\")\n\tfor _, o in { V3(-7, 4, -3), V3(7, 4, -3), V3(-7, 4, 3), V3(7, 4, 3) } do\n\t\tBuild.cyl(m, 0.4, 8, cf * CF(o), C.darkGray, Enum.Material.Metal)\n\tend\n\tBuild.part(m, V3(16, 0.6, 8), cf * CF(0, 8.3, 0), C.blue, Enum.Material.Metal).Name = \"Techo\"\n\tBuild.bench(m, cf * CF(0, 0, 1.5), C.blue)\n\tlocal board = Build.part(m, V3(12, 2.4, 0.4), cf * CF(0, 10, -3.6), C.yellow, Enum.Material.Metal)\n\tBuild.text(board, \"🚌 Terminal\", { color = C.black, face = Enum.NormalId.Front })\n\tBuild.text(board, \"🚌 Terminal\", { color = C.black, face = Enum.NormalId.Back })\n\t-- bus amarillo\n\tlocal b = cf * CF(0, 0, 12)\n\tBuild.part(m, V3(24, 8, 8), b * CF(0, 5.5, 0), C.yellow, Enum.Material.Metal).Name = \"Bus\"\n\tBuild.deco(m, V3(20, 2.6, 8.2), b * CF(-1, 7, 0), hex(\"#bfe6f5\"), Enum.Material.Glass)\n\tBuild.deco(m, V3(24.2, 0.8, 8.2), b * CF(0, 4, 0), C.black)\n\tBuild.part(m, V3(4, 5, 8), b * CF(13.5, 4, 0), C.yellow, Enum.Material.Metal)\n\tfor _, o in { V3(-8, 1.5, 4), V3(8, 1.5, 4), V3(-8, 1.5, -4), V3(8, 1.5, -4) } do\n\t\tBuild.ghost(Build.cyl(m, 1.5, 1, b * CF(o) * CFrame.Angles(rad(90), 0, 0), C.black))\n\tend\n\tlocal side = Build.deco(m, V3(12, 1.6, 0.2), b * CF(0, 2.6, -4.15), C.yellow)\n\tBuild.text(side, \"Tegucigalpa · Honduras\", { color = C.red, face = Enum.NormalId.Front })\n\tlocal spot = Build.part(m, V3(4, 4, 4), cf * CF(0, 2, -6), C.white, nil, { Transparency = 1, CanCollide = false })\n\tspot.Name = \"Mapa\"\n\tBuild.label(spot, \"🗺️ Viajar\", 6, C.white, 9)\n\treturn Build.prompt(spot, \"Ver mapa\", \"Terminal\", 0, 12)\nend\n\nlocal function danceFloor(parent: Instance, cf: CFrame): Part\n\tlocal m = Build.model(parent, \"PistaDeBaile\")\n\tlocal colors = { \"#e63946\", \"#ffc93c\", \"#00a3d7\", \"#ff5d9e\", \"#2ea44f\", \"#7b5cff\" }\n\tfor ix = 0, 3 do\n\t\tfor iz = 0, 3 do\n\t\t\tlocal tile = Build.part(m, V3(6, 0.5, 6), cf * CF(-9 + ix * 6, 0.25, -9 + iz * 6), hex(colors[(ix + iz * 2) % #colors + 1]), Enum.Material.Neon)\n\t\t\ttile.Name = \"Losa\"\n\t\tend\n\tend\n\tfor _, x in { -14, 14 } do\n\t\tBuild.part(m, V3(3, 6, 3), cf * CF(x, 3, -13), C.black, Enum.Material.Metal).Name = \"Bocina\"\n\t\tBuild.ghost(Build.cyl(m, 1.1, 0.3, cf * CF(x, 4, -11.4) * CFrame.Angles(rad(90), 0, 0), C.darkGray))\n\tend\n\tBuild.sign(m, cf * CF(0, 0, -15), 14, 3, \"💃 Pista de punta\", { color = C.pink }, 6)\n\tlocal zone = Build.part(m, V3(24, 8, 24), cf * CF(0, 4.5, 0), C.white, nil, { Transparency = 1, CanCollide = false, CanQuery = false })\n\tzone.Name = \"Zona\"\n\treturn zone\nend\n\nlocal function hills(parent: Instance)\n\tlocal m = Build.folder(parent, \"Cerros\")\n\tBuild.stack(m, CF(150, 0, -170), 46, 12, 44, 6, hex(\"#6fae5e\"), Enum.Material.Grass, hex(\"#4f8f4a\"))\n\t-- Cristo del Picacho a lo lejos\n\tBuild.part(m, V3(5, 6, 5), CF(150, 47, -170), C.stone, Enum.Material.Concrete)\n\tBuild.figure(m, CF(150, 50, -170) * CFrame.Angles(0, rad(180), 0), { skin = C.white, shirt = C.white, pants = C.white }, 2.6)\n\tBuild.stack(m, CF(-60, 0, -190), 40, 14, 30, 5, hex(\"#79b866\"), Enum.Material.Grass, hex(\"#5a9a50\"))\n\tBuild.stack(m, CF(60, 0, -196), 34, 10, 24, 4, hex(\"#84c070\"), Enum.Material.Grass)\nend\n\nfunction Lobby.build(parent: Instance): Result\n\tlocal folder = Build.folder(parent, \"Lobby\")\n\tground(folder)\n\tcathedral(folder, CF(0, 0, -124))\n\tstatue(folder, CF(0, 0, -30))\n\tkiosk(folder, CF(-44, 0, -34))\n\tfountain(folder, CF(44, 0, -34))\n\tlocal shopPrompt = pulperia(folder, CF(116, 0, -40) * CFrame.Angles(0, rad(90), 0))\n\thillside(folder)\n\tlocal terminalPrompt = busStop(folder, CF(150, 0, 20) * CFrame.Angles(0, rad(90), 0))\n\tlocal floor = danceFloor(folder, CF(152, 0, 96))\n\thills(folder)\n\n\t-- bandera\n\tBuild.cyl(folder, 0.5, 30, CF(-58, 15, 18), C.gray, Enum.Material.Metal).Name = \"Asta\"\n\tBuild.flag(folder, CF(-49.5, 25, 18), 16, 9)\n\n\t-- entrada al parque\n\tlocal arch = Build.model(folder, \"Entrada\")\n\tfor _, x in { -13, 13 } do\n\t\tBuild.part(arch, V3(2, 14, 2), CF(x, 7, 22), C.blue, Enum.Material.Concrete)\n\tend\n\tlocal top = Build.part(arch, V3(30, 4, 1.2), CF(0, 15, 22), C.white, Enum.Material.Concrete)\n\tBuild.text(top, \"MUNDO CATRUCHO\", { color = C.blue, face = Enum.NormalId.Back })\n\tBuild.text(top, \"¡Bienvenidos, catrachos!\", { color = C.blue, face = Enum.NormalId.Front })\n\n\t-- portales de minijuegos frente a la catedral\n\tlocal portals: { [string]: ProximityPrompt } = {}\n\tlocal slots = { carrera = CF(-68, 0, -86), futbol = CF(-44, 0, -90), feria = CF(44, 0, -90), exploradores = CF(68, 0, -86) }\n\tfor _, info in GameData.minigames do\n\t\tlocal cf = slots[info.id]\n\t\tif info.id == \"pulperia\" then\n\t\t\tcf = CF(78, 0, -4) * CFrame.Angles(0, rad(-90), 0)\n\t\tend\n\t\tif cf then\n\t\t\tlocal glow = Build.portal(folder, cf, hex(PORTAL_COLORS[info.id] or \"#00a3d7\"), info.name, info.icon)\n\t\t\tlocal prompt = Build.prompt(glow, \"Jugar\", info.name, 0.3, 12)\n\t\t\tprompt:SetAttribute(\"Minijuego\", info.id)\n\t\t\tportals[info.id] = prompt\n\t\tend\n\tend\n\n\t-- bancas, faroles y árboles\n\tfor _, b in { CF(-22, 0, -8), CF(22, 0, -8), CF(-22, 0, -62) * CFrame.Angles(0, rad(180), 0), CF(22, 0, -62) * CFrame.Angles(0, rad(180), 0), CF(-66, 0, -34) * CFrame.Angles(0, rad(90), 0), CF(66, 0, -34) * CFrame.Angles(0, rad(-90), 0) } do\n\t\tBuild.bench(folder, b)\n\tend\n\tfor _, p in { V3(-30, 0, 14), V3(30, 0, 14), V3(-76, 0, -70), V3(76, 0, -70), V3(-20, 0, -80), V3(20, 0, -80) } do\n\t\tBuild.lamp(folder, p)\n\tend\n\tlocal trees = Build.folder(folder, \"Arboles\")\n\tfor _, p in { V3(-70, 0, 8), V3(70, 0, 8), V3(-78, 0, -30), V3(-60, 0, -60), V3(60, 0, -60), V3(-100, 0, 40), V3(176, 0, 130), V3(-150, 0, 150), V3(176, 0, -20), V3(140, 0, -110) } do\n\t\tBuild.tree(trees, \"round\", p, 1.1)\n\tend\n\tfor _, p in { V3(-24, 0, -34), V3(24, 0, -52), V3(-126, 0, 190), V3(126, 0, 196), V3(-170, 0, 80), V3(170, 0, 70) } do\n\t\tBuild.tree(trees, \"palm\", p, 1)\n\tend\n\n\t-- punto de aparición\n\tlocal spawn = Instance.new(\"SpawnLocation\")\n\tspawn.Name = \"Aparicion\"\n\tspawn.Anchored = true\n\tspawn.Size = V3(12, 1, 12)\n\tspawn.CFrame = CF(Config.World.LobbySpawn.X, 0.5, Config.World.LobbySpawn.Z)\n\tspawn.Color = C.blue\n\tspawn.Material = Enum.Material.SmoothPlastic\n\tspawn.TopSurface = Enum.SurfaceType.Smooth\n\tspawn.Neutral = true\n\tspawn.Duration = 0\n\tspawn.Parent = folder\n\tBuild.deco(folder, V3(12, 0.1, 4), spawn.CFrame * CF(0, 0.55, 0), C.white)\n\n\t-- lempiritas regadas por el parque\n\tlocal coins = Build.folder(folder, \"Monedas\")\n\tlocal rng = Build.rng(1821)\n\tlocal blocked = { V3(0, 2.4, -30), V3(-44, 2.4, -34), V3(44, 2.4, -34) }\n\tlocal placed = 0\n\twhile placed < 24 do\n\t\tlocal pos = V3(rng(-80, 80), 2.4, rng(-82, 16))\n\t\tlocal free = true\n\t\tfor _, b in blocked do\n\t\t\tfree = free and (pos - b).Magnitude > 14\n\t\tend\n\t\tif free then\n\t\t\tBuild.coin(coins, pos)\n\t\t\tplaced += 1\n\t\tend\n\tend\n\n\tlocal mapPrompts = HondurasMap.build(folder, Config.World.MapOrigin, Config.World.MapScale)\n\treturn {\n\t\tportals = portals,\n\t\tmapPrompts = mapPrompts,\n\t\tshopPrompt = shopPrompt,\n\t\tterminalPrompt = terminalPrompt,\n\t\tdanceFloor = floor,\n\t\tspawn = spawn,\n\t}\nend\n\nreturn Lobby\n"},{"path":"src/server/World/Zones.luau","code":"--!strict\n-- Las 18 zonas de departamento, generadas desde departments.json:\n-- paleta por bioma + lugar emblemático por tipo + rótulo con el dato cultural + recuerdo escondido + monedas.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal Config = require(Shared.Config)\nlocal GameData = require(Shared.GameData)\nlocal Types = require(Shared.Types)\nlocal Build = require(script.Parent.Build)\nlocal Landmarks = require(script.Parent.Landmarks)\n\nlocal C = Build.C\nlocal hex = Build.hex\nlocal V3 = Vector3.new\nlocal CF = CFrame.new\nlocal rad = math.rad\n\nlocal Zones = {}\n\ntype Biome = { ground: string, material: Enum.Material, around: string, tree: string, path: string }\n\nlocal BIOMES: { [string]: Biome } = {\n\tcosta = { ground = \"#f1dca7\", material = Enum.Material.Sand, around = \"#2b9fd6\", tree = \"palm\", path = \"#d9c48a\" },\n\tisla = { ground = \"#f6e6b4\", material = Enum.Material.Sand, around = \"#19b5c8\", tree = \"palm\", path = \"#e2cf96\" },\n\tsur = { ground = \"#d9b77a\", material = Enum.Material.Ground, around = \"#c9a66b\", tree = \"dry\", path = \"#c29b5c\" },\n\tvalle = { ground = \"#8fce6a\", material = Enum.Material.Grass, around = \"#6aa84f\", tree = \"round\", path = \"#cdbf9b\" },\n\tlago = { ground = \"#79c267\", material = Enum.Material.Grass, around = \"#3a86ff\", tree = \"round\", path = \"#cdbf9b\" },\n\tmontana = { ground = \"#7fb069\", material = Enum.Material.Grass, around = \"#5d8a4e\", tree = \"pine\", path = \"#b9a57c\" },\n\tcapital = { ground = \"#9ccc80\", material = Enum.Material.Grass, around = \"#6aa84f\", tree = \"round\", path = \"#d9d2c0\" },\n\tselva = { ground = \"#3f8f4f\", material = Enum.Material.LeafyGrass, around = \"#2d6a4f\", tree = \"jungle\", path = \"#8a6f47\" },\n\tbosque = { ground = \"#4f7f3f\", material = Enum.Material.LeafyGrass, around = \"#3b5f33\", tree = \"pine\", path = \"#8a6f47\" },\n}\n\nlocal COIN_SPOTS = {\n\tV3(0, 2.4, 60), V3(0, 2.4, 50), V3(0, 2.4, 40), V3(0, 2.4, 30),\n\tV3(-40, 2.4, 45), V3(40, 2.4, 45), V3(-62, 2.4, 30), V3(62, 2.4, 30),\n\tV3(-80, 2.4, 0), V3(80, 2.4, 0), V3(-84, 2.4, -40), V3(84, 2.4, -40),\n}\n\nexport type Zone = {\n\tdept: Types.Department,\n\tcframe: CFrame, -- centro de la zona, a nivel del suelo\n\tarrival: CFrame, -- dónde aparece el jugador\n\tmodel: Model,\n\treturnPrompt: ProximityPrompt,\n\tcollectPrompt: ProximityPrompt,\n}\n\nfunction Zones.cframeFor(index: number): CFrame\n\tlocal W = Config.World\n\tlocal col = (index - 1) % W.ZoneColumns\n\tlocal row = (index - 1) // W.ZoneColumns\n\tlocal x = (col - (W.ZoneColumns - 1) / 2) * W.ZoneSpacing\n\treturn CF(W.ZonesOrigin + V3(x, 0, row * W.ZoneSpacing))\nend\n\nlocal function buildZone(parent: Instance, index: number, dept: Types.Department): Zone\n\tlocal size = Config.World.ZoneSize\n\tlocal cf = Zones.cframeFor(index)\n\tlocal biome = BIOMES[dept.biome] or BIOMES.valle\n\tlocal rng = Build.rng(index * 7919)\n\tlocal model = Build.model(parent, dept.id)\n\tmodel:SetAttribute(\"Dept\", dept.id)\n\n\tBuild.part(model, V3(size, 6, size), cf * CF(0, -3, 0), hex(biome.ground), biome.material).Name = \"Suelo\"\n\tBuild.deco(model, V3(size + 140, 1, size + 140), cf * CF(0, -5, 0), hex(biome.around), Enum.Material.SmoothPlastic).Name = \"Alrededor\"\n\tBuild.part(model, V3(8, 0.3, 64), cf * CF(0, 0.05, 52), hex(biome.path), Enum.Material.Ground).Name = \"Camino\"\n\tBuild.walls(model, cf, size, size, 70)\n\n\t-- lugar emblemático según landmark.kind\n\tlocal builder = Landmarks[dept.landmark.kind]\n\tlocal landmark = Build.model(model, \"Lugar\")\n\tlocal center = cf * CF(0, 0, -20)\n\tlocal hide = V3(0, 2, -60)\n\tif builder then\n\t\thide = builder(landmark, center, rng)\n\telse\n\t\twarn(`[Zonas] Sin constructor para \"{dept.landmark.kind}\"`)\n\t\tBuild.stack(landmark, center, 20, 6, 20, 4, hex(dept.colors[1]))\n\tend\n\n\t-- rótulos: bienvenida y dato cultural\n\tlocal accent, accent2 = hex(dept.colors[1]), hex(dept.colors[2])\n\tlocal welcome = Build.sign(model, cf * CF(-17, 0, 58) * CFrame.Angles(0, rad(180), 0), 20, 8, `{dept.name}\\nCabecera: {dept.cabecera}\\n📍 {dept.landmark.name}`, { color = C.white, bg = accent }, 3)\n\twelcome.Material = Enum.Material.SmoothPlastic\n\tlocal fact = Build.sign(model, cf * CF(17, 0, 58) * CFrame.Angles(0, rad(180), 0), 20, 8, `¿Sabías que…?\\n{dept.fact}`, { color = C.black, bg = C.cream }, 3)\n\tfact.Name = \"Dato\"\n\n\t-- vegetación del bioma en la orilla\n\tlocal trees = Build.folder(model, \"Arboles\")\n\tlocal placed = 0\n\twhile placed < 8 do\n\t\tlocal a = rng(0, math.pi * 2)\n\t\tlocal r = rng(80, 92)\n\t\tlocal x, z = math.cos(a) * r, math.sin(a) * r\n\t\tif z < 50 or math.abs(x) > 40 then\n\t\t\tBuild.tree(trees, biome.tree, (cf * CF(x, 0, z)).Position, rng(0.9, 1.3))\n\t\t\tplaced += 1\n\t\tend\n\tend\n\n\t-- monedas\n\tlocal coins = Build.folder(model, \"Monedas\")\n\tfor _, spot in COIN_SPOTS do\n\t\tBuild.coin(coins, cf * spot)\n\tend\n\n\t-- recuerdo escondido del departamento\n\tlocal spot = center * CF(hide)\n\tlocal gift = Build.part(model, V3(1.6, 1.6, 1.6), spot * CFrame.Angles(rad(45), rad(30), 0), accent2, Enum.Material.Neon, { CanCollide = false })\n\tgift.Name = \"Recuerdo\"\n\tgift:SetAttribute(\"Dept\", dept.id)\n\tlocal sparkle = Instance.new(\"Sparkles\")\n\tsparkle.SparkleColor = accent2\n\tsparkle.Parent = gift\n\tlocal collectPrompt = Build.prompt(gift, \"Recoger\", dept.collectible, 0.3, 10)\n\n\t-- plataforma de regreso\n\tlocal pad = Build.pad(model, cf * CF(0, 0, 88), C.blue, 4)\n\tBuild.label(pad, \"🏠 Volver al lobby\", 4, C.white, 12)\n\tlocal returnPrompt = Build.prompt(pad, \"Volver\", \"Lobby\", 0, 12)\n\n\treturn {\n\t\tdept = dept,\n\t\tcframe = cf,\n\t\tarrival = cf * CF(0, 4, 74),\n\t\tmodel = model,\n\t\treturnPrompt = returnPrompt,\n\t\tcollectPrompt = collectPrompt,\n\t}\nend\n\n-- Construye todas las zonas. Devuelve la tabla por id de departamento.\nfunction Zones.build(parent: Instance): { [string]: Zone }\n\tlocal folder = Build.folder(parent, \"Departamentos\")\n\tlocal zones: { [string]: Zone } = {}\n\tfor index, dept in GameData.departments do\n\t\tzones[dept.id] = buildZone(folder, index, dept)\n\tend\n\treturn zones\nend\n\nreturn Zones\n"},{"path":"src/shared/Config.luau","code":"--!strict\n-- Constantes del juego que no viven en los JSON (posiciones, límites, anti-trampa).\nlocal Config = {}\n\nConfig.DataStore = {\n\tName = \"MundoCatrucho_v1\",\n\tLeaderboardPrefix = \"MC_Top_v1_\",\n\tAutosaveSeconds = 60,\n\tRetries = 4,\n\tLockSeconds = 120,\n}\n\nConfig.StartCoins = 100\nConfig.ProfileVersion = 1\n\n-- Dónde se construye cada cosa (studs). El mundo se genera por código al iniciar el servidor.\nConfig.World = {\n\tLobbySpawn = Vector3.new(0, 4, 34),\n\tMapOrigin = Vector3.new(-110, 0.6, 64), -- esquina NO del mapa pisable\n\tMapScale = 0.22, -- studs por unidad del viewBox 1000x599\n\tZonesOrigin = Vector3.new(0, 0, 2400),\n\tZoneSpacing = 420,\n\tZoneSize = 200,\n\tZoneColumns = 6,\n\tCarrera = Vector3.new(-2000, 60, 0),\n\tFutbol = Vector3.new(2000, 0, 0),\n\tFeria = Vector3.new(0, 0, -2000),\n\tPulperia = Vector3.new(2000, 0, -2000),\n}\n\n-- Límites que el servidor aplica a lo que manda el cliente.\nConfig.Limits = {\n\tCoinPickupsPerSecond = 4,\n\tCoinPickupDistance = 14,\n\tPromptDistance = 18,\n\tTravelCooldown = 1.5,\n\tEmoteCooldown = 1.2,\n\tKickCooldown = 0.45,\n\tKickDistance = 9,\n\tShotCooldown = 0.45,\n\tMaxRunSpeed = 26, -- studs/s; WalkSpeed 16 con margen para lag y saltos\n}\n\nConfig.Carrera = { Length = 480, Countdown = 3 }\nConfig.Futbol = { WaitSeconds = 8, MaxPlayers = 8 }\nConfig.Feria = { Lanes = 4, SessionSeconds = 180 }\nConfig.Pulperia = { Stations = 3, Patience = 14 }\n\nreturn Config\n"},{"path":"src/shared/Content/Explorer.luau","code":"--!strict\n-- Objetos escondidos de \"Exploradores de Honduras\": 5 por sitio (minigames.json: rules.sites).\n-- offset: posición dentro de la zona del departamento (x, y, z en studs desde su centro).\nexport type Object = { id: string, site: string, name: string, icon: string, fact: string, offset: Vector3 }\n\nlocal V = Vector3.new\n\nlocal objects: { Object } = {\n\t{ id = \"copan_estela\", site = \"copan\", name = \"Estela maya\", icon = \"🗿\", offset = V(-39, 2, 13), fact = \"Las estelas de Copán son retratos en piedra de los reyes mayas, como 18 Conejo.\" },\n\t{ id = \"copan_guara\", site = \"copan\", name = \"Pluma de guara\", icon = \"🦜\", offset = V(5, 21.6, -30), fact = \"La guara roja es el ave nacional de Honduras y vuela libre en Copán Ruinas.\" },\n\t{ id = \"copan_pelota\", site = \"copan\", name = \"Pelota de hule\", icon = \"⚫\", offset = V(48, 2, -6), fact = \"En el juego de pelota maya se usaba una pelota de hule macizo que no se tocaba con las manos.\" },\n\t{ id = \"copan_vasija\", site = \"copan\", name = \"Vasija de barro\", icon = \"🏺\", offset = V(-14, 2, -57), fact = \"Los mayas de Copán tomaban cacao en vasijas de barro pintadas.\" },\n\t{ id = \"copan_glifo\", site = \"copan\", name = \"Glifo tallado\", icon = \"🔣\", offset = V(-68, 2, -55), fact = \"La Escalinata de los Jeroglíficos de Copán tiene el texto maya más largo que se conoce.\" },\n\n\t{ id = \"yojoa_pez\", site = \"cortes\", name = \"Pez del lago\", icon = \"🐟\", offset = V(0, 2.6, -2), fact = \"El Lago de Yojoa es el lago natural más grande de Honduras.\" },\n\t{ id = \"yojoa_remo\", site = \"cortes\", name = \"Remo de lancha\", icon = \"🛶\", offset = V(14, 2.6, -10), fact = \"Los pescadores del lago salen en lancha al amanecer.\" },\n\t{ id = \"yojoa_frito\", site = \"cortes\", name = \"Pescado frito\", icon = \"🍽️\", offset = V(-63, 2, 10), fact = \"En la orilla del lago hay comedores que sirven pescado frito con tajadas de plátano.\" },\n\t{ id = \"yojoa_garza\", site = \"cortes\", name = \"Pluma de garza\", icon = \"🪶\", offset = V(47, 2, -40), fact = \"En el Lago de Yojoa se han contado más de 400 especies de aves.\" },\n\t{ id = \"yojoa_orquidea\", site = \"cortes\", name = \"Orquídea\", icon = \"🌸\", offset = V(3, 2.4, -31), fact = \"La orquídea Rhyncholaelia digbyana es la flor nacional de Honduras.\" },\n\n\t{ id = \"roatan_estrella\", site = \"islas\", name = \"Estrella de mar\", icon = \"⭐\", offset = V(-30, 1.6, -40), fact = \"Roatán está junto al Arrecife Mesoamericano, el segundo arrecife de coral más grande del mundo.\" },\n\t{ id = \"roatan_tortuga\", site = \"islas\", name = \"Tortuga carey\", icon = \"🐢\", offset = V(34, 1.6, -52), fact = \"La tortuga carey anida en las Islas de la Bahía y está en peligro de extinción.\" },\n\t{ id = \"roatan_mascara\", site = \"islas\", name = \"Máscara de buceo\", icon = \"🤿\", offset = V(-59, 2, 10), fact = \"Roatán y Utila son de los lugares más famosos del mundo para aprender a bucear.\" },\n\t{ id = \"roatan_coco\", site = \"islas\", name = \"Coco\", icon = \"🥥\", offset = V(59, 2, 15), fact = \"Con leche de coco se hacen el pan de coco y la sopa de caracol de la costa.\" },\n\t{ id = \"roatan_tambor\", site = \"islas\", name = \"Tambor garífuna\", icon = \"🥁\", offset = V(0, 2.8, -29), fact = \"El pueblo garífuna llegó a Roatán en 1797; su música, la punta, se toca con tambores.\" },\n}\n\nlocal Explorer = {}\nExplorer.objects = objects\nExplorer.byId = {} :: { [string]: Object }\nfor _, o in objects do\n\tExplorer.byId[o.id] = o\nend\n\nExplorer.siteNames = {\n\tcopan = \"Copán Ruinas\",\n\tcortes = \"Lago de Yojoa\",\n\tislas = \"Roatán\",\n} :: { [string]: string }\n\nreturn Explorer\n"},{"path":"src/shared/GameData.luau","code":"--!strict\n-- Única puerta a los JSON de shared/data (Rojo los convierte en ModuleScripts dentro de Shared.Data).\nlocal Types = require(script.Parent.Types)\nlocal Data = script.Parent.Data\n\nlocal departmentsFile = require(Data.departments) :: any\nlocal minigames = require(Data.minigames) :: any\nlocal progress = require(Data.progress) :: any\nlocal rewards = require(Data.rewards) :: any\nlocal shop = require(Data.shop) :: any\n\nlocal GameData = {}\n\nGameData.viewBox = departmentsFile.viewBox :: { number }\nGameData.departments = departmentsFile.departments :: { Types.Department }\nGameData.minigames = minigames :: { Types.MinigameInfo }\nGameData.rewards = rewards :: Types.RewardsData\nGameData.shop = shop :: Types.ShopData\nGameData.achievements = progress.achievements :: { Types.Achievement }\nGameData.missions = progress.missions :: { Types.Mission }\nGameData.dailyCount = progress.dailyCount :: number\nGameData.bots = progress.bots :: { string }\n\nlocal function index<T>(list: { T }): { [string]: T }\n\tlocal out = {}\n\tfor _, v in list do\n\t\tout[(v :: any).id] = v\n\tend\n\treturn out\nend\n\nGameData.departmentById = index(GameData.departments)\nGameData.minigameById = index(GameData.minigames)\nGameData.itemById = index(GameData.shop.items)\nGameData.achievementById = index(GameData.achievements)\nGameData.missionById = index(GameData.missions)\n\n-- Categoría de la tienda -> campo del avatar.\nGameData.slotByCat = {\n\tcabello = \"hair\",\n\trostro = \"face\",\n\tcamisa = \"shirt\",\n\tpantalon = \"pants\",\n\tsombrero = \"hat\",\n\taccesorio = \"acc\",\n} :: { [string]: string }\n\n-- Campo de color -> lista permitida en shop.json.\nGameData.colorFields = {\n\tskin = \"skin\",\n\thairColor = \"hairColors\",\n\tshirtColor = \"palette\",\n\tpantsColor = \"palette\",\n\thatColor = \"palette\",\n\taccColor = \"palette\",\n} :: { [string]: string }\n\nGameData.categories = { \"cabello\", \"rostro\", \"camisa\", \"pantalon\", \"sombrero\", \"accesorio\", \"emote\" }\nGameData.categoryNames = {\n\tcabello = \"Cabello\",\n\trostro = \"Rostro\",\n\tcamisa = \"Camisas\",\n\tpantalon = \"Pantalones\",\n\tsombrero = \"Sombreros\",\n\taccesorio = \"Accesorios\",\n\temote = \"Emotes\",\n} :: { [string]: string }\n\nfunction GameData.rules(gameId: string): { [string]: any }\n\tlocal info = GameData.minigameById[gameId]\n\treturn if info then info.rules else {}\nend\n\nreturn GameData\n"},{"path":"src/shared/Logic/Achievements.luau","code":"--!strict\n-- Logros de progress.json. Las condiciones viven aquí (el JSON solo trae nombre, icono y premio).\nlocal GameData = require(script.Parent.Parent.GameData)\nlocal Types = require(script.Parent.Parent.Types)\nlocal Progression = require(script.Parent.Progression)\nlocal Shop = require(script.Parent.Shop)\n\nlocal Achievements = {}\n\nlocal function count(set: { [string]: boolean }): number\n\tlocal n = 0\n\tfor _ in set do\n\t\tn += 1\n\tend\n\treturn n\nend\nAchievements.count = count\n\nlocal function stars(profile: Types.Profile, gameId: string): number\n\tlocal b = profile.best[gameId]\n\treturn if b then b.stars else 0\nend\n\nlocal RULES: { [string]: (Types.Profile) -> boolean } = {\n\tprimer_paso = function(_p)\n\t\treturn true\n\tend,\n\tprimera_victoria = function(p)\n\t\treturn p.stats.wins >= 1\n\tend,\n\trayo = function(p)\n\t\treturn stars(p, \"carrera\") >= 3\n\tend,\n\tgoleador = function(p)\n\t\treturn p.stats.goals >= 3\n\tend,\n\tpunteria = function(p)\n\t\treturn stars(p, \"feria\") >= 3\n\tend,\n\texplorador = function(p)\n\t\treturn stars(p, \"exploradores\") >= 1\n\tend,\n\tpulpero = function(p)\n\t\treturn stars(p, \"pulperia\") >= 3\n\tend,\n\tviajero = function(p)\n\t\treturn count(p.visited) >= 5\n\tend,\n\tcatracho_de_corazon = function(p)\n\t\treturn count(p.visited) >= #GameData.departments\n\tend,\n\tcoleccionista = function(p)\n\t\treturn count(p.collected) >= 9\n\tend,\n\ta_la_moda = function(p)\n\t\treturn p.stats.purchases >= 5\n\tend,\n\ttraje_tipico = function(p)\n\t\treturn Shop.tradCount(p.avatar) >= 3\n\tend,\n\tnivel_5 = function(p)\n\t\treturn p.level >= 5\n\tend,\n\tbailarin = function(p)\n\t\treturn p.stats.emotes >= 10\n\tend,\n}\nAchievements.rules = RULES\n\n-- Otorga los logros recién cumplidos (con sus monedas) y devuelve sus ids.\nfunction Achievements.check(profile: Types.Profile): { string }\n\tlocal fresh = {}\n\tfor _, a in GameData.achievements do\n\t\tlocal rule = RULES[a.id]\n\t\tif rule and not profile.achievements[a.id] and rule(profile) then\n\t\t\tprofile.achievements[a.id] = true\n\t\t\tProgression.addCoins(profile, a.coins)\n\t\t\ttable.insert(fresh, a.id)\n\t\tend\n\tend\n\treturn fresh\nend\n\nreturn Achievements\n"},{"path":"src/shared/Logic/FeriaMath.luau","code":"--!strict\n-- Matemática de la feria: el servidor decide los aciertos con esto, el cliente solo dibuja.\nlocal FeriaMath = {}\n\nFeriaMath.Gravity = 60 -- gravedad \"de feria\" para la argolla (studs/s^2)\nFeriaMath.RingAngle = math.rad(40)\nFeriaMath.RingSpeedMin = 16\nFeriaMath.RingSpeedMax = 36\n\n-- Rayo contra un disco. Devuelve la distancia al centro si pega dentro del radio.\nfunction FeriaMath.rayDisc(origin: Vector3, dir: Vector3, center: Vector3, normal: Vector3, radius: number): (number?, Vector3?)\n\tlocal denom = dir:Dot(normal)\n\tif math.abs(denom) < 1e-4 then\n\t\treturn nil, nil\n\tend\n\tlocal t = (center - origin):Dot(normal) / denom\n\tif t <= 0 then\n\t\treturn nil, nil\n\tend\n\tlocal hit = origin + dir * t\n\tlocal d = (hit - center).Magnitude\n\tif d > radius then\n\t\treturn nil, nil\n\tend\n\treturn d, hit\nend\n\n-- Puntos de la diana según qué tan cerca del centro pegó.\nfunction FeriaMath.targetPoints(distance: number, radius: number, moving: boolean): number\n\tlocal f = distance / radius\n\tlocal base = if f <= 0.3 then 30 elseif f <= 0.65 then 20 else 10\n\treturn base + (if moving then 10 else 0)\nend\n\nfunction FeriaMath.ringSpeed(power: number): number\n\tlocal p = math.clamp(power, 0, 1)\n\treturn FeriaMath.RingSpeedMin + (FeriaMath.RingSpeedMax - FeriaMath.RingSpeedMin) * p\nend\n\n-- Dónde cae la argolla sobre la mesa (plano y = planeY) y cuánto tarda.\nfunction FeriaMath.ringLanding(origin: Vector3, dir: Vector3, power: number, planeY: number): (Vector3, number, Vector3)\n\tlocal flat = Vector3.new(dir.X, 0, dir.Z)\n\tif flat.Magnitude < 1e-3 then\n\t\tflat = Vector3.new(0, 0, -1)\n\tend\n\tflat = flat.Unit\n\tlocal speed = FeriaMath.ringSpeed(power)\n\tlocal vy = speed * math.sin(FeriaMath.RingAngle)\n\tlocal vh = speed * math.cos(FeriaMath.RingAngle)\n\tlocal g = FeriaMath.Gravity\n\tlocal drop = origin.Y - planeY\n\tlocal t = (vy + math.sqrt(vy * vy + 2 * g * math.max(0, drop))) / g\n\tlocal land = Vector3.new(origin.X, planeY, origin.Z) + flat * (vh * t)\n\treturn land, t, flat * vh + Vector3.new(0, vy, 0)\nend\n\n-- Rayo contra caja alineada a los ejes. Devuelve la distancia de entrada.\nfunction FeriaMath.rayBox(origin: Vector3, dir: Vector3, center: Vector3, half: Vector3): number?\n\tlocal tmin, tmax = 0, math.huge\n\tlocal o = { origin.X, origin.Y, origin.Z }\n\tlocal d = { dir.X, dir.Y, dir.Z }\n\tlocal c = { center.X, center.Y, center.Z }\n\tlocal h = { half.X, half.Y, half.Z }\n\tfor i = 1, 3 do\n\t\tif math.abs(d[i]) < 1e-6 then\n\t\t\tif o[i] < c[i] - h[i] or o[i] > c[i] + h[i] then\n\t\t\t\treturn nil\n\t\t\tend\n\t\telse\n\t\t\tlocal t1 = (c[i] - h[i] - o[i]) / d[i]\n\t\t\tlocal t2 = (c[i] + h[i] - o[i]) / d[i]\n\t\t\tif t1 > t2 then\n\t\t\t\tt1, t2 = t2, t1\n\t\t\tend\n\t\t\ttmin, tmax = math.max(tmin, t1), math.min(tmax, t2)\n\t\t\tif tmin > tmax then\n\t\t\t\treturn nil\n\t\t\tend\n\t\tend\n\tend\n\treturn tmin\nend\n\n-- Pirámide de latas 4-3-2-1. Índices por fila de abajo hacia arriba: 1-4, 5-7, 8-9, 10.\nFeriaMath.CanRows = { 4, 3, 2, 1 }\n\n-- La lata (fila r, pos i) se apoya en (r-1, i) y (r-1, i+1).\nfunction FeriaMath.canSupports(index: number): { number }\n\tlocal start = 1\n\tfor r, n in FeriaMath.CanRows do\n\t\tif index < start + n then\n\t\t\tif r == 1 then\n\t\t\t\treturn {}\n\t\t\tend\n\t\t\tlocal i = index - start + 1\n\t\t\tlocal below = start - FeriaMath.CanRows[r - 1]\n\t\t\treturn { below + i - 1, below + i }\n\t\tend\n\t\tstart += n\n\tend\n\treturn {}\nend\n\n-- Latas que caen al pegarle a `hit`: ella y todas las que pierden un apoyo.\nfunction FeriaMath.cansKnocked(hit: number, standing: { boolean }): { number }\n\tlocal fallen = {}\n\tif not standing[hit] then\n\t\treturn fallen\n\tend\n\tlocal down = table.clone(standing)\n\tdown[hit] = false\n\ttable.insert(fallen, hit)\n\tfor index = 1, #standing do\n\t\tif down[index] then\n\t\t\tfor _, s in FeriaMath.canSupports(index) do\n\t\t\t\tif not down[s] then\n\t\t\t\t\tdown[index] = false\n\t\t\t\t\ttable.insert(fallen, index)\n\t\t\t\t\tbreak\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\treturn fallen\nend\n\nreturn FeriaMath\n"},{"path":"src/shared/Logic/Missions.luau","code":"--!strict\n-- Misiones diarias: 3 por día, elegidas con el mismo algoritmo que la versión web.\nlocal GameData = require(script.Parent.Parent.GameData)\nlocal Types = require(script.Parent.Parent.Types)\nlocal Progression = require(script.Parent.Progression)\n\nlocal Missions = {}\n\nlocal U32 = 4294967296\nlocal HONDURAS_OFFSET = -6 * 3600\n\n-- \"2026-11-9\" en hora de Honduras (UTC-6), sin ceros, como la web.\nfunction Missions.dateKey(now: number): string\n\tlocal t = os.date(\"!*t\", now + HONDURAS_OFFSET) :: any\n\treturn `{t.year}-{t.month}-{t.day}`\nend\n\nfunction Missions.pickDaily(date: string): { Types.DailyMission }\n\tlocal h = 0\n\tfor i = 1, #date do\n\t\th = (h * 31 + string.byte(date, i)) % U32\n\tend\n\tlocal pool = {}\n\tfor _, m in GameData.missions do\n\t\ttable.insert(pool, m.id)\n\tend\n\tlocal out: { Types.DailyMission } = {}\n\twhile #out < GameData.dailyCount and #pool > 0 do\n\t\th = (h * 1664525 + 1013904223) % U32\n\t\tlocal id = table.remove(pool, (h % #pool) + 1) :: string\n\t\ttable.insert(out, { id = id, progress = 0, claimed = false })\n\tend\n\treturn out\nend\n\n-- Renueva las misiones si cambió el día. Devuelve true si las renovó.\nfunction Missions.ensureToday(profile: Types.Profile, now: number): boolean\n\tlocal date = Missions.dateKey(now)\n\tif profile.daily.date == date and #profile.daily.missions > 0 then\n\t\treturn false\n\tend\n\tprofile.daily = { date = date, missions = Missions.pickDaily(date) }\n\treturn true\nend\n\n-- Avanza las misiones del tipo dado. Devuelve las que quedaron completas con este avance.\nfunction Missions.bump(profile: Types.Profile, kind: string, amount: number, target: string?): { Types.Mission }\n\tlocal done = {}\n\tif amount ~= amount or amount <= 0 then\n\t\treturn done\n\tend\n\tfor _, dm in profile.daily.missions do\n\t\tlocal m = GameData.missionById[dm.id]\n\t\tif not m or m.type ~= kind or (m.target ~= nil and m.target ~= target) then\n\t\t\tcontinue\n\t\tend\n\t\tlocal before = dm.progress\n\t\tif kind == \"score\" then\n\t\t\tdm.progress = math.min(m.count, math.max(dm.progress, math.floor(amount)))\n\t\telse\n\t\t\tdm.progress = math.min(m.count, dm.progress + math.floor(amount))\n\t\tend\n\t\tif before < m.count and dm.progress >= m.count then\n\t\t\ttable.insert(done, m)\n\t\tend\n\tend\n\treturn done\nend\n\nfunction Missions.claim(profile: Types.Profile, id: string): (boolean, Types.Mission?)\n\tlocal m = GameData.missionById[id]\n\tif not m then\n\t\treturn false, nil\n\tend\n\tfor _, dm in profile.daily.missions do\n\t\tif dm.id == id then\n\t\t\tif dm.claimed or dm.progress < m.count then\n\t\t\t\treturn false, nil\n\t\t\tend\n\t\t\tdm.claimed = true\n\t\t\tProgression.addCoins(profile, m.coins)\n\t\t\tProgression.addXp(profile, m.xp)\n\t\t\treturn true, m\n\t\tend\n\tend\n\treturn false, nil\nend\n\nreturn Missions\n"},{"path":"src/shared/Logic/Polygon.luau","code":"--!strict\n-- Geometría de los contornos de departments.json: relleno por franjas horizontales (scanline).\nexport type Ring = { { number } }\nexport type Span = { y: number, x0: number, x1: number }\n\nlocal Polygon = {}\n\nfunction Polygon.bounds(rings: { Ring }): (number, number, number, number)\n\tlocal minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge\n\tfor _, ring in rings do\n\t\tfor _, p in ring do\n\t\t\tminX, maxX = math.min(minX, p[1]), math.max(maxX, p[1])\n\t\t\tminY, maxY = math.min(minY, p[2]), math.max(maxY, p[2])\n\t\tend\n\tend\n\treturn minX, minY, maxX, maxY\nend\n\nfunction Polygon.area(ring: Ring): number\n\tlocal a = 0\n\tfor i = 1, #ring do\n\t\tlocal p, q = ring[i], ring[i % #ring + 1]\n\t\ta += p[1] * q[2] - q[1] * p[2]\n\tend\n\treturn math.abs(a) / 2\nend\n\n-- Cruces del eje y con los bordes de todos los anillos, ordenados.\nlocal function crossings(rings: { Ring }, y: number): { number }\n\tlocal xs = {}\n\tfor _, ring in rings do\n\t\tfor i = 1, #ring do\n\t\t\tlocal p, q = ring[i], ring[i % #ring + 1]\n\t\t\tlocal y0, y1 = p[2], q[2]\n\t\t\tif (y0 <= y and y1 > y) or (y1 <= y and y0 > y) then\n\t\t\t\ttable.insert(xs, p[1] + (y - y0) / (y1 - y0) * (q[1] - p[1]))\n\t\t\tend\n\t\tend\n\tend\n\ttable.sort(xs)\n\treturn xs\nend\n\nfunction Polygon.contains(rings: { Ring }, x: number, y: number): boolean\n\tlocal inside = false\n\tfor _, cx in crossings(rings, y) do\n\t\tif cx > x then\n\t\t\tbreak\n\t\tend\n\t\tinside = not inside\n\tend\n\treturn inside\nend\n\n-- Franjas de alto `step` que cubren el polígono. Cada franja va centrada en y.\nfunction Polygon.scanlines(rings: { Ring }, step: number, minWidth: number?): { Span }\n\tlocal spans: { Span } = {}\n\tlocal _, minY, _, maxY = Polygon.bounds(rings)\n\tlocal y = math.floor(minY / step) * step + step / 2\n\twhile y < maxY do\n\t\tlocal xs = crossings(rings, y)\n\t\tfor i = 1, #xs - 1, 2 do\n\t\t\tif xs[i + 1] - xs[i] >= (minWidth or 0) then\n\t\t\t\ttable.insert(spans, { y = y, x0 = xs[i], x1 = xs[i + 1] })\n\t\t\tend\n\t\tend\n\t\ty += step\n\tend\n\treturn spans\nend\n\nreturn Polygon\n"},{"path":"src/shared/Logic/Profiles.luau","code":"--!strict\n-- Forma del perfil y todas las operaciones que lo cambian. Funciones puras: fáciles de probar.\nlocal GameData = require(script.Parent.Parent.GameData)\nlocal Config = require(script.Parent.Parent.Config)\nlocal Types = require(script.Parent.Parent.Types)\nlocal Progression = require(script.Parent.Progression)\nlocal Rewards = require(script.Parent.Rewards)\nlocal Missions = require(script.Parent.Missions)\nlocal Shop = require(script.Parent.Shop)\n\nlocal Profiles = {}\n\nlocal function copyAvatar(a: Types.Avatar): Types.Avatar\n\treturn table.clone(a)\nend\n\nfunction Profiles.fresh(now: number): Types.Profile\n\tlocal date = Missions.dateKey(now)\n\treturn {\n\t\tversion = Config.ProfileVersion,\n\t\tcoins = Config.StartCoins,\n\t\txp = 0,\n\t\tlevel = 1,\n\t\towned = {},\n\t\tavatar = copyAvatar(GameData.shop.defaultAvatar),\n\t\tvisited = {},\n\t\tcollected = {},\n\t\tachievements = {},\n\t\tfacts = {},\n\t\tstats = { played = 0, wins = 0, goals = 0, pickups = 0, emotes = 0, purchases = 0, coinsEarned = 0 },\n\t\tbest = {},\n\t\tdaily = { date = date, missions = Missions.pickDaily(date) },\n\t\tsettings = { sfx = true, uiScale = 1, lowFx = false, names = true },\n\t\tcreated = now,\n\t\tlastSeen = now,\n\t}\nend\n\nlocal function num(v: any, default: number, min: number, max: number): number\n\tif typeof(v) ~= \"number\" or v ~= v then\n\t\treturn default\n\tend\n\treturn math.clamp(math.floor(v), min, max)\nend\n\nlocal function set(raw: any, valid: { [string]: any }?): { [string]: boolean }\n\tlocal out = {}\n\tif typeof(raw) == \"table\" then\n\t\tfor k, v in raw do\n\t\t\tif typeof(k) == \"string\" and v == true and (valid == nil or valid[k] ~= nil) then\n\t\t\t\tout[k] = true\n\t\t\tend\n\t\tend\n\tend\n\treturn out\nend\n\n-- Repara lo que venga del DataStore: datos viejos, campos que faltan o valores corruptos.\nfunction Profiles.reconcile(raw: any, now: number): Types.Profile\n\tlocal p = Profiles.fresh(now)\n\tif typeof(raw) ~= \"table\" then\n\t\treturn p\n\tend\n\tp.coins = num(raw.coins, p.coins, 0, 1e9)\n\tp.level = num(raw.level, 1, 1, GameData.rewards.level.max)\n\tp.xp = num(raw.xp, 0, 0, Progression.need(p.level))\n\tp.created = num(raw.created, now, 0, now)\n\tp.owned = set(raw.owned, GameData.itemById)\n\tp.visited = set(raw.visited, GameData.departmentById)\n\tp.collected = set(raw.collected, GameData.departmentById)\n\tp.achievements = set(raw.achievements, GameData.achievementById)\n\tp.facts = set(raw.facts, nil)\n\tif typeof(raw.stats) == \"table\" then\n\t\tfor k, default in p.stats :: any do\n\t\t\t(p.stats :: any)[k] = num(raw.stats[k], default, 0, 1e9)\n\t\tend\n\tend\n\tif typeof(raw.best) == \"table\" then\n\t\tfor id in GameData.minigameById do\n\t\t\tlocal b = raw.best[id]\n\t\t\tif typeof(b) == \"table\" then\n\t\t\t\tp.best[id] = {\n\t\t\t\t\tscore = num(b.score, 0, 0, 1e9),\n\t\t\t\t\tstars = num(b.stars, 0, 0, 3),\n\t\t\t\t\tlabel = if typeof(b.label) == \"string\" then string.sub(b.label, 1, 24) else \"\",\n\t\t\t\t}\n\t\t\tend\n\t\tend\n\tend\n\tif typeof(raw.avatar) == \"table\" then\n\t\tShop.applyAvatar(p, raw.avatar)\n\tend\n\tif typeof(raw.settings) == \"table\" then\n\t\tProfiles.setSettings(p, raw.settings)\n\tend\n\tlocal daily = raw.daily\n\tif typeof(daily) == \"table\" and daily.date == p.daily.date and typeof(daily.missions) == \"table\" then\n\t\tfor _, dm in p.daily.missions do\n\t\t\tfor _, saved in daily.missions do\n\t\t\t\tif typeof(saved) == \"table\" and saved.id == dm.id then\n\t\t\t\t\tlocal m = GameData.missionById[dm.id]\n\t\t\t\t\tdm.progress = num(saved.progress, 0, 0, m.count)\n\t\t\t\t\tdm.claimed = saved.claimed == true\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\treturn p\nend\n\nfunction Profiles.setSettings(profile: Types.Profile, changes: any): boolean\n\tif typeof(changes) ~= \"table\" then\n\t\treturn false\n\tend\n\tlocal s = profile.settings\n\tfor _, k in { \"sfx\", \"lowFx\", \"names\" } do\n\t\tif typeof(changes[k]) == \"boolean\" then\n\t\t\t(s :: any)[k] = changes[k]\n\t\tend\n\tend\n\tif typeof(changes.uiScale) == \"number\" and changes.uiScale == changes.uiScale then\n\t\ts.uiScale = math.clamp(math.floor(changes.uiScale * 10 + 0.5) / 10, 0.8, 1.3)\n\tend\n\treturn true\nend\n\n-- Registra una partida terminada y devuelve lo ganado.\nfunction Profiles.recordMinigame(profile: Types.Profile, gameId: string, result: Types.Result): Types.Summary\n\tlocal stars = math.clamp(math.floor(result.stars), 0, 3)\n\tlocal reward = Rewards.forMinigame(result.won, stars)\n\tprofile.stats.played += 1\n\tif result.won then\n\t\tprofile.stats.wins += 1\n\tend\n\tlocal goals = result.goals or 0\n\tif goals > 0 then\n\t\tprofile.stats.goals = math.max(profile.stats.goals, goals)\n\tend\n\tlocal prev = profile.best[gameId]\n\tlocal isBest = false\n\tif not prev or result.score > prev.score then\n\t\tisBest = result.score > 0\n\t\tprofile.best[gameId] = {\n\t\t\tscore = result.score,\n\t\t\tstars = math.max(stars, if prev then prev.stars else 0),\n\t\t\tlabel = result.label,\n\t\t}\n\telseif stars > prev.stars then\n\t\tprev.stars = stars\n\tend\n\tProgression.addCoins(profile, reward.coins)\n\tlocal leveledUp = Progression.addXp(profile, reward.xp)\n\tMissions.bump(profile, \"play\", 1, gameId)\n\tif result.won then\n\t\tMissions.bump(profile, \"win\", 1, gameId)\n\tend\n\tif goals > 0 then\n\t\tMissions.bump(profile, \"goals\", goals, gameId)\n\tend\n\tMissions.bump(profile, \"score\", result.score, gameId)\n\treturn {\n\t\tid = gameId,\n\t\twon = result.won,\n\t\tstars = stars,\n\t\tscore = result.score,\n\t\tlabel = result.label,\n\t\tcoins = reward.coins,\n\t\txp = reward.xp,\n\t\tleveledUp = leveledUp,\n\t\tnewAchievements = {},\n\t\tisBest = isBest,\n\t}\nend\n\n-- Primera visita a un departamento: premio y misión. Devuelve true si era la primera.\nfunction Profiles.visit(profile: Types.Profile, deptId: string): boolean\n\tif not GameData.departmentById[deptId] or profile.visited[deptId] then\n\t\treturn false\n\tend\n\tprofile.visited[deptId] = true\n\tlocal r = GameData.rewards.world.firstVisit\n\tProgression.addCoins(profile, r.coins)\n\tProgression.addXp(profile, r.xp)\n\tMissions.bump(profile, \"visit\", 1)\n\treturn true\nend\n\nfunction Profiles.collect(profile: Types.Profile, deptId: string): boolean\n\tif not GameData.departmentById[deptId] or profile.collected[deptId] then\n\t\treturn false\n\tend\n\tprofile.collected[deptId] = true\n\tlocal r = GameData.rewards.world.collectible\n\tProgression.addCoins(profile, r.coins)\n\tProgression.addXp(profile, r.xp)\n\tMissions.bump(profile, \"collect\", 1)\n\treturn true\nend\n\nfunction Profiles.pickupCoin(profile: Types.Profile)\n\tProgression.addCoins(profile, GameData.rewards.world.coinPickup)\n\tprofile.stats.pickups += 1\n\tMissions.bump(profile, \"pickup\", 1)\nend\n\nfunction Profiles.useEmote(profile: Types.Profile, emoteId: any): boolean\n\tif typeof(emoteId) ~= \"string\" then\n\t\treturn false\n\tend\n\tlocal item = GameData.itemById[emoteId]\n\tif not item or item.cat ~= \"emote\" or not Shop.owns(profile, emoteId) then\n\t\treturn false\n\tend\n\tprofile.stats.emotes += 1\n\tMissions.bump(profile, \"emote\", 1)\n\treturn true\nend\n\nreturn Profiles\n"},{"path":"src/shared/Logic/Progression.luau","code":"--!strict\n-- XP, niveles y monedas. need(n) = base + (n-1)*perLevel, igual que la versión web.\nlocal GameData = require(script.Parent.Parent.GameData)\nlocal Types = require(script.Parent.Parent.Types)\n\nlocal Progression = {}\n\nfunction Progression.need(level: number): number\n\tlocal L = GameData.rewards.level\n\treturn L.base + (math.max(1, level) - 1) * L.perLevel\nend\n\nfunction Progression.addCoins(profile: Types.Profile, n: number)\n\tif n ~= n or math.abs(n) == math.huge then\n\t\treturn\n\tend\n\tn = math.floor(n)\n\tprofile.coins = math.max(0, profile.coins + n)\n\tif n > 0 then\n\t\tprofile.stats.coinsEarned += n\n\tend\nend\n\n-- Suma XP y sube de nivel las veces que haga falta. Devuelve true si subió.\nfunction Progression.addXp(profile: Types.Profile, n: number): boolean\n\tif n ~= n or n <= 0 or n == math.huge then\n\t\treturn false\n\tend\n\tlocal L = GameData.rewards.level\n\tlocal up = false\n\tprofile.xp += math.floor(n)\n\twhile profile.level < L.max and profile.xp >= Progression.need(profile.level) do\n\t\tprofile.xp -= Progression.need(profile.level)\n\t\tprofile.level += 1\n\t\tProgression.addCoins(profile, GameData.rewards.levelUp.coins)\n\t\tup = true\n\tend\n\tif profile.level >= L.max then\n\t\tprofile.xp = math.min(profile.xp, Progression.need(L.max))\n\tend\n\treturn up\nend\n\n-- XP total acumulada, para ordenar jugadores.\nfunction Progression.totalXp(profile: Types.Profile): number\n\tlocal total = profile.xp\n\tfor level = 1, profile.level - 1 do\n\t\ttotal += Progression.need(level)\n\tend\n\treturn total\nend\n\nreturn Progression\n"},{"path":"src/shared/Logic/RateLimiter.luau","code":"--!strict\n-- Cubeta de fichas por clave (jugador). Sirve para limitar remotos y recogidas.\nexport type Limiter = {\n\tallow: (self: Limiter, key: any, cost: number?) -> boolean,\n\tforget: (self: Limiter, key: any) -> (),\n}\n\nlocal RateLimiter = {}\n\n-- rate: fichas por segundo; burst: máximo acumulado.\nfunction RateLimiter.new(rate: number, burst: number, clock: (() -> number)?): Limiter\n\tlocal now = clock or os.clock\n\tlocal buckets: { [any]: { tokens: number, at: number } } = {}\n\tlocal self = {} :: Limiter\n\n\tfunction self:allow(key: any, cost: number?): boolean\n\t\tlocal t = now()\n\t\tlocal b = buckets[key]\n\t\tif not b then\n\t\t\tb = { tokens = burst, at = t }\n\t\t\tbuckets[key] = b\n\t\tend\n\t\tb.tokens = math.min(burst, b.tokens + (t - b.at) * rate)\n\t\tb.at = t\n\t\tlocal c = cost or 1\n\t\tif b.tokens >= c then\n\t\t\tb.tokens -= c\n\t\t\treturn true\n\t\tend\n\t\treturn false\n\tend\n\n\tfunction self:forget(key: any)\n\t\tbuckets[key] = nil\n\tend\n\n\treturn self\nend\n\nreturn RateLimiter\n"},{"path":"src/shared/Logic/Rewards.luau","code":"--!strict\n-- Convierte lo que midió el servidor en resultado (estrellas, victoria) y recompensa.\nlocal GameData = require(script.Parent.Parent.GameData)\nlocal Types = require(script.Parent.Parent.Types)\n\nlocal Rewards = {}\n\nfunction Rewards.starsFor(value: number, bronze: number, silver: number, gold: number, lowerIsBetter: boolean?): number\n\tlocal function ok(t: number): boolean\n\t\tif lowerIsBetter then\n\t\t\treturn value <= t\n\t\tend\n\t\treturn value >= t\n\tend\n\treturn if ok(gold) then 3 elseif ok(silver) then 2 elseif ok(bronze) then 1 else 0\nend\n\nfunction Rewards.fmtTime(seconds: number): string\n\tlocal s = math.max(0, seconds)\n\tlocal whole = math.floor(s)\n\treturn string.format(\"%d:%02d.%02d\", whole // 60, whole % 60, math.floor((s - whole) * 100))\nend\n\nfunction Rewards.fmtClock(seconds: number): string\n\tlocal s = math.max(0, math.ceil(seconds))\n\treturn string.format(\"%d:%02d\", s // 60, s % 60)\nend\n\n-- Monedas y XP de una partida: igual que la web (las estrellas solo cuentan si ganó).\nfunction Rewards.forMinigame(won: boolean, stars: number): Types.Amount\n\tlocal R = GameData.rewards.minigame\n\tlocal s = math.clamp(math.floor(stars), 0, 3)\n\tif won then\n\t\treturn { coins = R.win.coins + s * R.perStar.coins, xp = R.win.xp + s * R.perStar.xp }\n\tend\n\treturn { coins = R.lose.coins, xp = R.lose.xp }\nend\n\n-- raw: medidas del servidor.\n--   carrera { finished, time }   futbol { teamGoals, rivalGoals, goals }\n--   feria / pulperia { points }  exploradores { found }\nfunction Rewards.evaluate(gameId: string, raw: { [string]: any }): Types.Result\n\tlocal rules = GameData.rules(gameId)\n\tif gameId == \"carrera\" then\n\t\tlocal time = raw.time :: number\n\t\tlocal won = raw.finished == true and time <= rules.timeLimit\n\t\tif not won then\n\t\t\treturn { won = false, stars = 0, score = 0, label = \"Sin terminar\" }\n\t\tend\n\t\treturn {\n\t\t\twon = true,\n\t\t\tstars = Rewards.starsFor(time, rules.bronze, rules.silver, rules.gold, true),\n\t\t\tscore = math.floor((rules.timeLimit - time) * 1000 + 0.5),\n\t\t\tlabel = Rewards.fmtTime(time),\n\t\t}\n\telseif gameId == \"futbol\" then\n\t\tlocal team, rival, goals = raw.teamGoals :: number, raw.rivalGoals :: number, raw.goals :: number\n\t\tlocal gold = rules.goldGoals :: number\n\t\treturn {\n\t\t\twon = team > rival,\n\t\t\tstars = Rewards.starsFor(team, math.ceil(gold / 3), math.ceil(gold * 2 / 3), gold),\n\t\t\tscore = goals,\n\t\t\tlabel = `{team} - {rival}`,\n\t\t\tgoals = goals,\n\t\t}\n\telseif gameId == \"exploradores\" then\n\t\tlocal found = raw.found :: number\n\t\tlocal total = #rules.sites * rules.objectsPerSite\n\t\tlocal stars = Rewards.starsFor(found, rules.bronze, rules.silver, rules.gold)\n\t\treturn { won = stars >= 1, stars = stars, score = found, label = `{found}/{total}` }\n\telse -- feria, pulperia: puntos contra umbrales\n\t\tlocal points = math.max(0, raw.points :: number)\n\t\tlocal stars = Rewards.starsFor(points, rules.bronze, rules.silver, rules.gold)\n\t\treturn { won = stars >= 1, stars = stars, score = points, label = `{points} pts` }\n\tend\nend\n\n-- Texto de una marca guardada en el ranking (el score de carrera son ms sobrantes).\nfunction Rewards.scoreLabel(gameId: string, score: number): string\n\tif gameId == \"carrera\" then\n\t\treturn Rewards.fmtTime(GameData.rules(\"carrera\").timeLimit - score / 1000)\n\telseif gameId == \"futbol\" then\n\t\treturn `{score} goles`\n\telseif gameId == \"exploradores\" then\n\t\treturn `{score} objetos`\n\tend\n\treturn `{score} pts`\nend\n\nreturn Rewards\n"},{"path":"src/shared/Logic/Sanity.luau","code":"--!strict\n-- Chequeos de cordura. Los minijuegos corren en el servidor; esto es la segunda red por si algo se cuela.\nlocal GameData = require(script.Parent.Parent.GameData)\nlocal Config = require(script.Parent.Parent.Config)\n\nlocal Sanity = {}\n\nfunction Sanity.isNumber(v: any): boolean\n\treturn typeof(v) == \"number\" and v == v and math.abs(v) ~= math.huge\nend\n\nfunction Sanity.isString(v: any, maxLen: number): boolean\n\treturn typeof(v) == \"string\" and #v > 0 and #v <= maxLen\nend\n\nfunction Sanity.isVector(v: any): boolean\n\treturn typeof(v) == \"Vector3\" and v.X == v.X and v.Y == v.Y and v.Z == v.Z and v.Magnitude < 1e6\nend\n\n-- Dirección de tiro: vector válido dentro de un cono alrededor del frente del puesto.\nfunction Sanity.aimDirection(v: any, forward: Vector3, minDot: number): Vector3?\n\tif not Sanity.isVector(v) or v.Magnitude < 0.01 then\n\t\treturn nil\n\tend\n\tlocal unit = (v :: Vector3).Unit\n\tif unit:Dot(forward) < minDot then\n\t\treturn nil\n\tend\n\treturn unit\nend\n\n-- Tiempo mínimo creíble para recorrer `distance` studs.\nfunction Sanity.minTravelTime(distance: number): number\n\treturn distance / Config.Limits.MaxRunSpeed\nend\n\nSanity.FeriaMaxPoints = 240 + 240 + 150 -- hulera 6x40, argollas 6x40, latas 10x10 + 50\n\n-- ¿Son creíbles estas medidas para el tiempo real que duró la partida en el servidor?\nfunction Sanity.validate(gameId: string, raw: { [string]: any }, elapsed: number): (boolean, string?)\n\tlocal rules = GameData.rules(gameId)\n\tif not GameData.minigameById[gameId] then\n\t\treturn false, \"minijuego desconocido\"\n\tend\n\tif not Sanity.isNumber(elapsed) or elapsed < 0 then\n\t\treturn false, \"tiempo inválido\"\n\tend\n\tif gameId == \"carrera\" then\n\t\tif raw.finished then\n\t\t\tlocal time = raw.time\n\t\t\tif not Sanity.isNumber(time) or time <= 0 then\n\t\t\t\treturn false, \"tiempo inválido\"\n\t\t\tend\n\t\t\tif time < Sanity.minTravelTime(Config.Carrera.Length) then\n\t\t\t\treturn false, \"carrera demasiado rápida\"\n\t\t\tend\n\t\t\tif time > elapsed + 1 then\n\t\t\t\treturn false, \"tiempo no coincide con el servidor\"\n\t\t\tend\n\t\tend\n\t\treturn true, nil\n\telseif gameId == \"futbol\" then\n\t\tfor _, k in { \"teamGoals\", \"rivalGoals\", \"goals\" } do\n\t\t\tlocal v = raw[k]\n\t\t\tif not Sanity.isNumber(v) or v < 0 or v % 1 ~= 0 then\n\t\t\t\treturn false, \"marcador inválido\"\n\t\t\tend\n\t\tend\n\t\tif raw.goals > raw.teamGoals then\n\t\t\treturn false, \"más goles que su equipo\"\n\t\tend\n\t\tif raw.teamGoals + raw.rivalGoals > elapsed / 2 + 1 then\n\t\t\treturn false, \"demasiados goles\"\n\t\tend\n\t\tif elapsed < rules.duration - 5 then\n\t\t\treturn false, \"partido incompleto\"\n\t\tend\n\t\treturn true, nil\n\telseif gameId == \"exploradores\" then\n\t\tlocal found = raw.found\n\t\tif not Sanity.isNumber(found) or found < 0 or found % 1 ~= 0 then\n\t\t\treturn false, \"conteo inválido\"\n\t\tend\n\t\tif found > #rules.sites * rules.objectsPerSite then\n\t\t\treturn false, \"más objetos de los que existen\"\n\t\tend\n\t\tif found > elapsed + 1 then\n\t\t\treturn false, \"objetos demasiado rápido\"\n\t\tend\n\t\treturn true, nil\n\telse\n\t\tlocal points = raw.points\n\t\tif not Sanity.isNumber(points) or points < 0 or points % 1 ~= 0 then\n\t\t\treturn false, \"puntaje inválido\"\n\t\tend\n\t\tif gameId == \"feria\" then\n\t\t\tlocal shots = #rules.booths * rules.shotsPerBooth\n\t\t\tif points > Sanity.FeriaMaxPoints then\n\t\t\t\treturn false, \"puntaje imposible\"\n\t\t\tend\n\t\t\tif points > 0 and elapsed < shots * Config.Limits.ShotCooldown * 0.5 then\n\t\t\t\treturn false, \"feria demasiado rápida\"\n\t\t\tend\n\t\telseif gameId == \"pulperia\" then\n\t\t\tif points > (elapsed / 2 + 1) * 40 then\n\t\t\t\treturn false, \"puntaje imposible\"\n\t\t\tend\n\t\tend\n\t\treturn true, nil\n\tend\nend\n\nreturn Sanity\n"},{"path":"src/shared/Logic/Shop.luau","code":"--!strict\n-- Compras y cambios de avatar. Se ejecuta solo en el servidor; el cliente lo usa para pintar botones.\nlocal GameData = require(script.Parent.Parent.GameData)\nlocal Types = require(script.Parent.Parent.Types)\n\nlocal Shop = {}\n\nfunction Shop.owns(profile: Types.Profile, itemId: string): boolean\n\tlocal item = GameData.itemById[itemId]\n\tif not item then\n\t\treturn false\n\tend\n\treturn item.price == 0 or profile.owned[itemId] == true\nend\n\n-- \"ok\" | \"no\" (no existe) | \"ya\" (ya lo tiene) | \"caro\" (no alcanza)\nfunction Shop.buy(profile: Types.Profile, itemId: any): string\n\tif typeof(itemId) ~= \"string\" then\n\t\treturn \"no\"\n\tend\n\tlocal item = GameData.itemById[itemId]\n\tif not item then\n\t\treturn \"no\"\n\tend\n\tif Shop.owns(profile, itemId) then\n\t\treturn \"ya\"\n\tend\n\tif profile.coins < item.price then\n\t\treturn \"caro\"\n\tend\n\tprofile.coins -= item.price\n\tprofile.owned[itemId] = true\n\tprofile.stats.purchases += 1\n\treturn \"ok\"\nend\n\nlocal function contains(list: { string }, value: string): boolean\n\treturn table.find(list, value) ~= nil\nend\n\n-- ¿Se puede poner este valor en este campo del avatar?\nfunction Shop.validField(profile: Types.Profile, field: string, value: any): boolean\n\tif typeof(value) ~= \"string\" then\n\t\treturn false\n\tend\n\tlocal listName = GameData.colorFields[field]\n\tif listName then\n\t\treturn contains((GameData.shop :: any)[listName], value)\n\tend\n\tlocal item = GameData.itemById[value]\n\tif not item or GameData.slotByCat[item.cat] ~= field then\n\t\treturn false\n\tend\n\treturn Shop.owns(profile, value)\nend\n\n-- Aplica solo los campos válidos. Devuelve cuántos cambió y cuántos rechazó.\nfunction Shop.applyAvatar(profile: Types.Profile, changes: any): (number, number)\n\tlocal changed, rejected = 0, 0\n\tif typeof(changes) ~= \"table\" then\n\t\treturn 0, 1\n\tend\n\tlocal avatar = profile.avatar :: any\n\tfor field in GameData.shop.defaultAvatar :: any do\n\t\tlocal value = changes[field]\n\t\tif value == nil then\n\t\t\tcontinue\n\t\tend\n\t\tif Shop.validField(profile, field, value) then\n\t\t\tif avatar[field] ~= value then\n\t\t\t\tavatar[field] = value\n\t\t\t\tchanged += 1\n\t\t\tend\n\t\telse\n\t\t\trejected += 1\n\t\tend\n\tend\n\treturn changed, rejected\nend\n\n-- Prendas tradicionales puestas a la vez (logro \"Traje típico\").\nfunction Shop.tradCount(avatar: Types.Avatar): number\n\tlocal n = 0\n\tfor _, id in { avatar.shirt, avatar.pants, avatar.hat, avatar.acc } do\n\t\tlocal item = GameData.itemById[id]\n\t\tif item and item.trad then\n\t\t\tn += 1\n\t\tend\n\tend\n\treturn n\nend\n\nfunction Shop.ownedEmotes(profile: Types.Profile): { Types.ShopItem }\n\tlocal out = {}\n\tfor _, item in GameData.shop.items do\n\t\tif item.cat == \"emote\" and Shop.owns(profile, item.id) then\n\t\t\ttable.insert(out, item)\n\t\tend\n\tend\n\treturn out\nend\n\nreturn Shop\n"},{"path":"src/shared/Net.luau","code":"--!strict\n-- Un solo módulo de red para servidor y cliente.\n-- El servidor crea ReplicatedStorage.Remotes; el cliente solo espera a que existan.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal Net = {}\n\n-- servidor -> cliente\nNet.Events = {\n\tProfileSync = \"ProfileSync\", -- (perfil)\n\tToast = \"Toast\", -- (texto, icono?)\n\tOpenPanel = \"OpenPanel\", -- (panelId)\n\tMinigameState = \"MinigameState\", -- (estado del HUD)\n\tMinigameResult = \"MinigameResult\", -- (resumen con recompensas)\n\tEmotePlay = \"EmotePlay\", -- (userId, emoteId, segundos)\n\tEffect = \"Effect\", -- (tipo, datos) efectos visuales\n\t-- cliente -> servidor (todo validado y con límite de frecuencia)\n\tEmoteRequest = \"EmoteRequest\", -- (emoteId)\n\tFutbolKick = \"FutbolKick\", -- ()\n\tFeriaShoot = \"FeriaShoot\", -- (dirección: Vector3, fuerza: number)\n\tMinigameQuit = \"MinigameQuit\", -- ()\n}\n\n-- cliente -> servidor con respuesta\nNet.Functions = {\n\tShopBuy = \"ShopBuy\", -- (itemId) -> { ok, code }\n\tAvatarSet = \"AvatarSet\", -- (cambios) -> { ok }\n\tTravelTo = \"TravelTo\", -- (deptId | \"lobby\") -> { ok, msg? }\n\tMinigameStart = \"MinigameStart\", -- (gameId) -> { ok, msg? }\n\tClaimMission = \"ClaimMission\", -- (missionId) -> { ok }\n\tGetLeaderboard = \"GetLeaderboard\", -- (gameId) -> { entries }\n\tSettingsSet = \"SettingsSet\", -- (cambios) -> { ok }\n\tRoomCreate = \"RoomCreate\", -- () -> { ok, code?, msg? }\n\tRoomJoin = \"RoomJoin\", -- (code) -> { ok, msg? }\n\tRoomInfo = \"RoomInfo\",\n\tGetProfile = \"GetProfile\", -- () -> { private, code? }\n\tExplorerTravel = \"ExplorerTravel\", -- (siteId) -> { ok }\n}\n\nlocal FOLDER = \"Remotes\"\n\nlocal function folder(): Instance\n\tif RunService:IsServer() then\n\t\tlocal f = ReplicatedStorage:FindFirstChild(FOLDER)\n\t\tif not f then\n\t\t\tlocal created = Instance.new(\"Folder\")\n\t\t\tcreated.Name = FOLDER\n\t\t\tcreated.Parent = ReplicatedStorage\n\t\t\tf = created\n\t\tend\n\t\treturn f :: Instance\n\tend\n\treturn ReplicatedStorage:WaitForChild(FOLDER)\nend\n\nlocal function get(name: string, className: string): Instance\n\tlocal f = folder()\n\tif RunService:IsServer() then\n\t\tlocal r = f:FindFirstChild(name)\n\t\tif not r then\n\t\t\tlocal created = Instance.new(className) :: Instance\n\t\t\tcreated.Name = name\n\t\t\tcreated.Parent = f\n\t\t\tr = created\n\t\tend\n\t\treturn r :: Instance\n\tend\n\treturn f:WaitForChild(name)\nend\n\n-- Crea todos los remotos. Solo servidor, una vez, antes de que entren jugadores.\nfunction Net.setup()\n\tassert(RunService:IsServer(), \"Net.setup es solo para el servidor\")\n\tfor _, name in Net.Events do\n\t\tget(name :: string, \"RemoteEvent\")\n\tend\n\tfor _, name in Net.Functions do\n\t\tget(name :: string, \"RemoteFunction\")\n\tend\nend\n\nfunction Net.event(name: string): RemoteEvent\n\tassert(Net.Events[name], \"Evento desconocido: \" .. name)\n\treturn get(name :: string, \"RemoteEvent\") :: RemoteEvent\nend\n\nfunction Net.func(name: string): RemoteFunction\n\tassert(Net.Functions[name], \"Función desconocida: \" .. name)\n\treturn get(name :: string, \"RemoteFunction\") :: RemoteFunction\nend\n\nreturn Net\n"},{"path":"src/shared/Types.luau","code":"--!strict\n-- Tipos compartidos por servidor y cliente.\n\nexport type Avatar = {\n\tskin: string,\n\thair: string,\n\thairColor: string,\n\tface: string,\n\tshirt: string,\n\tshirtColor: string,\n\tpants: string,\n\tpantsColor: string,\n\that: string,\n\thatColor: string,\n\tacc: string,\n\taccColor: string,\n}\n\nexport type ShopItem = { id: string, cat: string, name: string, price: number, tint: boolean?, trad: boolean? }\nexport type ShopData = {\n\tskin: { string },\n\tpalette: { string },\n\thairColors: { string },\n\titems: { ShopItem },\n\tdefaultAvatar: Avatar,\n}\n\nexport type Department = {\n\tid: string,\n\tname: string,\n\tcabecera: string,\n\tbiome: string,\n\tlandmark: { kind: string, name: string },\n\tcolors: { string },\n\tfact: string,\n\tcollectible: string,\n\tmap: { center: { number }, rings: { { { number } } } },\n}\n\nexport type MinigameInfo = {\n\tid: string,\n\tname: string,\n\tplace: string,\n\ticon: string,\n\tdesc: string,\n\tbonus: boolean?,\n\trules: { [string]: any },\n}\n\nexport type Amount = { coins: number, xp: number }\nexport type RewardsData = {\n\tcurrency: string,\n\tlevel: { base: number, perLevel: number, max: number },\n\tminigame: { lose: Amount, win: Amount, perStar: Amount },\n\tworld: { coinPickup: number, collectible: Amount, firstVisit: Amount },\n\tlevelUp: { coins: number },\n}\n\nexport type Achievement = { id: string, name: string, desc: string, icon: string, coins: number }\nexport type Mission = {\n\tid: string,\n\ttext: string,\n\ttype: string,\n\ttarget: string?,\n\tcount: number,\n\tcoins: number,\n\txp: number,\n}\n\nexport type Best = { score: number, stars: number, label: string }\nexport type DailyMission = { id: string, progress: number, claimed: boolean }\nexport type Settings = { sfx: boolean, uiScale: number, lowFx: boolean, names: boolean }\nexport type Stats = {\n\tplayed: number,\n\twins: number,\n\tgoals: number,\n\tpickups: number,\n\temotes: number,\n\tpurchases: number,\n\tcoinsEarned: number,\n}\n\n-- Perfil guardado en DataStore. Los conjuntos son diccionarios id -> true.\nexport type Profile = {\n\tversion: number,\n\tcoins: number,\n\txp: number,\n\tlevel: number,\n\towned: { [string]: boolean },\n\tavatar: Avatar,\n\tvisited: { [string]: boolean },\n\tcollected: { [string]: boolean },\n\tachievements: { [string]: boolean },\n\tfacts: { [string]: boolean },\n\tstats: Stats,\n\tbest: { [string]: Best },\n\tdaily: { date: string, missions: { DailyMission } },\n\tsettings: Settings,\n\tcreated: number,\n\tlastSeen: number,\n}\n\n-- Resultado de una partida ya evaluado con las reglas de minigames.json.\nexport type Result = {\n\twon: boolean,\n\tstars: number,\n\tscore: number,\n\tlabel: string,\n\tgoals: number?,\n}\n\nexport type Summary = {\n\tid: string,\n\twon: boolean,\n\tstars: number,\n\tscore: number,\n\tlabel: string,\n\tcoins: number,\n\txp: number,\n\tleveledUp: boolean,\n\tnewAchievements: { string },\n\tisBest: boolean,\n}\n\nreturn {}\n"},{"path":"docs/verificacion.md","code":"# Verificación de la entrega\n\nHerramientas disponibles: Rojo 7.7.1, luau-lsp 1.70.1 y Lune 0.10.4. Se reutilizaron los binarios de `/tmp/claude-1000/roblox-tools`. No se descargaron paquetes nuevos.\n\nComando reproducible ejecutado desde `catrucho/roblox`:\n\n```bash\n./scripts/verify.sh\n```\n\nEl script ejecuta estos comandos exactos, con `TOOLS=/tmp/claude-1000/roblox-tools`:\n\n```bash\n\"$TOOLS/rojo/rojo\" sourcemap --output sourcemap.json\n\"$TOOLS/luau-lsp/luau-lsp\" analyze --platform roblox --definitions \"$TOOLS/dl/globalTypes.d.luau\" --sourcemap sourcemap.json src\n\"$TOOLS/rojo/rojo\" build -o MundoCatrucho.rbxl\n\"$TOOLS/lune/lune\" run tests/run.luau\nwc -c MundoCatrucho.rbxl\n```\n\nResultado final: 18 pruebas aprobadas y `MundoCatrucho.rbxl` de 106,049 bytes.\n\nEl análisis tiene cero errores y cero advertencias de código. El mensaje de luau-lsp sobre `didChangeWatchedFiles` pertenece al modo sin editor. Los detalles están en `analyze.txt`.\n\nLas pruebas comprueban módulos y scripts del archivo real, igualdad de los cinco JSON, fórmula y límites de XP, premios, misiones, compras, visitas, recuerdos, reconciliación, marcadores, límites de frecuencia, polígonos y matemática de feria. También construyen el lobby y los 18 departamentos con Lune: 2,624 piezas base.\n\nLas pruebas del DataService real simulan los servicios de Roblox. Comprueban guardado, respaldo en memoria y rechazo de un candado activo de otro servidor. Los mensajes de API desactivada y perfil ocupado son fallos provocados por las pruebas. Consultá `tests.txt` para el total.\n\n## Estado de los minijuegos\n\n| Juego | Implementación |\n| --- | --- |\n| Carrera Catrucha | 480 studs, saltos, plataformas móviles, obstáculos rojos, cuatro puestos ordenados, regreso al puesto al caer, límite de 120 segundos y medallas por tiempo. Partidas individuales simultáneas. |\n| Fútbol de Barrio | Cancha, pelota física del servidor, goles, ocho segundos para ingresar, equipos equilibrados y partido de dos minutos. Hasta ocho jugadores. Un bot sencillo cubre cada equipo sin humanos. |\n| Feria Catracha | Cuatro espacios individuales, seis tiros por puesto: hulera, argollas y tumbalatas. Acertar depende de rayos o trayectoria calculados en el servidor. Puntos, premios y límite de tres minutos. |\n| Exploradores de Honduras | Quince objetos en Copán, Yojoa y Roatán, viajes entre sitios, datos culturales guardados, medallas por hallazgos y límite de cuatro minutos. |\n| La Pulpería | Tres turnos individuales, cuatro productos, pedidos con catorce segundos de paciencia, puntos y turno de noventa segundos. |\n\nLas cinco implementaciones tienen inicio, estado, cierre, salida sin premio y limpieza. La lógica está implementada; ninguna partida se ejecutó dentro de Roblox Studio.\n\n## Pendiente de probar en Studio\n\n- Arranque de los scripts con los servicios del motor y eventos reales.\n- Distancias de salto y transporte sobre plataformas móviles. Puede necesitar ajuste para latencia y personajes móviles.\n- Física de pelota, goles, balance de bots y competencia con varios clientes.\n- Apuntado desde la cámara, fuerza de argollas y legibilidad de blancos.\n- Acceso físico a los recuerdos y objetos elevados.\n- Tamaño de interfaz en celulares pequeños, áreas seguras y controles táctiles.\n- Aspecto R6 y R15, emotes, tipografía y símbolos.\n- Rendimiento en dispositivos modestos. El conteo de piezas no mide rendimiento.\n- Guardado persistente, cierres de servidores y rankings con servicios reales.\n- ReserveServer, MemoryStore, códigos y TeleportAsync en una experiencia publicada.\n\nLune comprueba estructura y lógica con servicios simulados. No sustituye la física, las conexiones multijugador ni la interfaz de Roblox.\n"},{"path":"tests/run.luau","code":"--!nonstrict\nlocal fs = require(\"@lune/fs\")\nlocal luau = require(\"@lune/luau\")\nlocal roblox = require(\"@lune/roblox\")\nlocal serde = require(\"@lune/serde\")\nlocal task = require(\"@lune/task\")\nlocal root = roblox.deserializePlace(fs.readFile(\"MundoCatrucho.rbxl\"))\nlocal total = 0\nlocal function test(name, fn)\n\tfn(); total += 1; print(\"✓ \" .. name)\nend\nlocal function equal(a, b) assert(a == b, `esperado {b}, recibido {a}`) end\nlocal function signal()\n\tlocal callbacks = {}\n\treturn { Connect = function(_, fn) table.insert(callbacks, fn); return { Disconnect = function() end } end,\n\t\tfire = function(_, ...) for _, fn in callbacks do fn(...) end end }\nend\nroblox.implementMethod(\"Instance\", \"WaitForChild\", function(self, name) return assert(self:FindFirstChild(name), name) end)\nlocal tagged = {}\nlocal services = {\n\tReplicatedStorage = root.ReplicatedStorage,\n\tCollectionService = { AddTag = function(_, item, tag) tagged[item] = tag end },\n}\nlocal fakeGame = { JobId = \"prueba\", GetService = function(_, name) return assert(services[name], name) end }\nlocal cache = {}\nlocal function loadModule(module)\n\tif cache[module] then return cache[module] end\n\tlocal env = table.clone(roblox)\n\tenv.script = module; env.game = fakeGame; env.workspace = root.Workspace; env.require = loadModule; env.task = task\n\tenv.warn = function(...) print(...) end\n\tlocal value = luau.load(module.Source, { environment = env, injectGlobals = true, debugName = module:GetFullName() })()\n\tcache[module] = value\n\treturn value\nend\nlocal shared = root.ReplicatedStorage.Shared\nlocal modules = shared.Logic\nlocal Data = loadModule(shared.GameData)\nlocal Profiles = loadModule(modules.Profiles)\nlocal Progression = loadModule(modules.Progression)\nlocal Rewards = loadModule(modules.Rewards)\nlocal Missions = loadModule(modules.Missions)\nlocal Shop = loadModule(modules.Shop)\nlocal Sanity = loadModule(modules.Sanity)\nlocal RateLimiter = loadModule(modules.RateLimiter)\nlocal Polygon = loadModule(modules.Polygon)\nlocal FeriaMath = loadModule(modules.FeriaMath)\nlocal function fresh() return Profiles.fresh(1794225600) end\n\ntest(\"Lugar: scripts ejecutables y cinco JSON originales\", function()\n\tequal(root.ServerScriptService.Server.Main.ClassName, \"Script\")\n\tequal(root.StarterPlayer.StarterPlayerScripts.Client.Main.ClassName, \"LocalScript\")\n\tfor _, name in { \"departments\", \"minigames\", \"rewards\", \"shop\", \"progress\" } do\n\t\tlocal expected = serde.decode(\"json\", fs.readFile(\"../shared/data/\" .. name .. \".json\"))\n\t\tlocal function same(a, b)\n\t\t\tif type(a) ~= \"table\" then equal(a, b); return end\n\t\t\tfor k, v in a do same(v, b[k]) end\n\t\t\tfor k in b do assert(a[k] ~= nil) end\n\t\tend\n\t\tsame(loadModule(shared.Data[name]), expected)\n\tend\n\tequal(#Data.departments, 18)\nend)\ntest(\"XP: fórmula y subida múltiple con premio\", function()\n\tfor level = 1, 50 do equal(Progression.need(level), Data.rewards.level.base + (level - 1) * Data.rewards.level.perLevel) end\n\tlocal p = fresh(); Progression.addXp(p, 275)\n\tequal(p.level, 3); equal(p.xp, 25); equal(p.coins, 200); equal(Progression.totalXp(p), 275)\nend)\ntest(\"XP y monedas rechazan NaN e infinito\", function()\n\tlocal p = fresh(); Progression.addXp(p, 0/0); Progression.addCoins(p, math.huge); equal(p.coins, 100); equal(p.xp, 0)\nend)\ntest(\"XP respeta nivel máximo\", function()\n\tlocal p = fresh(); Progression.addXp(p, 1e8); equal(p.level, Data.rewards.level.max); equal(p.xp, Progression.need(p.level))\nend)\ntest(\"Premios: victoria, derrota y medallas\", function()\n\tequal(Rewards.forMinigame(false, 3).coins, Data.rewards.minigame.lose.coins)\n\tequal(Rewards.forMinigame(true, 3).coins, Data.rewards.minigame.win.coins + 3 * Data.rewards.minigame.perStar.coins)\n\tequal(Rewards.evaluate(\"carrera\", { finished = true, time = 50 }).stars, 3)\n\tequal(Rewards.evaluate(\"carrera\", { finished = false, time = 120 }).score, 0)\n\tequal(Rewards.evaluate(\"feria\", { points = 400 }).stars, 3)\n\tequal(Rewards.evaluate(\"exploradores\", { found = 15 }).stars, 3)\nend)\ntest(\"Misiones: tres distintas, deterministas y renovación\", function()\n\tlocal p = fresh(); equal(#p.daily.missions, 3)\n\tlocal ids = {}; for _, m in p.daily.missions do assert(not ids[m.id]); ids[m.id] = true end\n\tlocal other = fresh(); for i, m in p.daily.missions do equal(m.id, other.daily.missions[i].id) end\n\tassert(not Missions.ensureToday(p, 1794225600)); assert(Missions.ensureToday(p, 1794312000))\nend)\ntest(\"Misiones: tipo, destino, avance y cobro único\", function()\n\tlocal p = fresh(); p.daily.missions = { { id = \"m_carrera\", progress = 0, claimed = false } }\n\tMissions.bump(p, \"win\", 1, \"feria\"); equal(p.daily.missions[1].progress, 0)\n\tMissions.bump(p, \"win\", 1, \"carrera\"); assert(Missions.claim(p, \"m_carrera\")); assert(not Missions.claim(p, \"m_carrera\"))\nend)\ntest(\"Tienda: saldo, propiedad, duplicados y categoría\", function()\n\tlocal p = fresh(); local item\n\tfor _, candidate in Data.shop.items do if candidate.price > 0 and candidate.cat ~= \"emote\" then item = candidate; break end end\n\tp.coins = 0; equal(Shop.buy(p, item.id), \"caro\"); equal(Shop.buy(p, {}), \"no\")\n\tp.coins = item.price; equal(Shop.buy(p, item.id), \"ok\"); equal(p.coins, 0); equal(Shop.buy(p, item.id), \"ya\")\n\tassert(Shop.validField(p, Data.slotByCat[item.cat], item.id)); assert(not Shop.validField(p, \"skin\", \"#badbad\"))\n\tassert(not Shop.validField(fresh(), Data.slotByCat[item.cat], item.id))\nend)\ntest(\"Visitas y recuerdos se premian una sola vez\", function()\n\tlocal p = fresh(); local id = Data.departments[1].id\n\tassert(Profiles.visit(p, id)); assert(not Profiles.visit(p, id)); assert(Profiles.collect(p, id)); assert(not Profiles.collect(p, id))\n\tequal(p.coins, 100 + Data.rewards.world.firstVisit.coins + Data.rewards.world.collectible.coins)\nend)\ntest(\"Perfil: reconcilia datos corruptos\", function()\n\tlocal p = Profiles.reconcile({ coins = -20, level = 1e5, owned = { falso = true }, avatar = { shirt = \"hack\" } }, 1794225600)\n\tequal(p.coins, 0); equal(p.level, 50); equal(p.owned.falso, nil); equal(p.avatar.shirt, Data.shop.defaultAvatar.shirt)\nend)\ntest(\"Cordura: tiempos, goles, puntos y vectores inválidos\", function()\n\tassert(not Sanity.validate(\"carrera\", { finished = true, time = 1 }, 30))\n\tassert(Sanity.validate(\"carrera\", { finished = true, time = 40 }, 40))\n\tassert(not Sanity.validate(\"futbol\", { teamGoals = 2, rivalGoals = 0, goals = 3 }, 120))\n\tassert(not Sanity.validate(\"futbol\", { teamGoals = 1, rivalGoals = 0, goals = 1 }, 10))\n\tassert(not Sanity.validate(\"feria\", { points = 9999 }, 180))\n\tassert(not Sanity.validate(\"feria\", { points = -1 }, 180))\n\tassert(not Sanity.validate(\"exploradores\", { found = 16 }, 240))\n\tassert(not Sanity.isVector(roblox.Vector3.new(0/0, 0, 0)))\nend)\ntest(\"Límite de llamadas y limpieza\", function()\n\tlocal clock = 0; local limiter = RateLimiter.new(2, 2, function() return clock end)\n\tassert(limiter:allow(\"a\")); assert(limiter:allow(\"a\")); assert(not limiter:allow(\"a\"))\n\tclock = 0.5; assert(limiter:allow(\"a\")); limiter:forget(\"a\"); assert(limiter:allow(\"a\"))\nend)\ntest(\"Mapa: contornos y franjas\", function()\n\tfor _, dept in Data.departments do\n\t\tassert(#Polygon.scanlines(dept.map.rings, 8) > 0)\n\t\tassert(Polygon.area(dept.map.rings[1]) > 0)\n\tend\nend)\ntest(\"Feria: rayos, argolla y caída de latas\", function()\n\tlocal V = roblox.Vector3.new\n\tequal(FeriaMath.targetPoints(0, 2, false), 30)\n\tassert(FeriaMath.rayDisc(V(0, 0, 0), V(0, 0, -1), V(0, 0, -10), V(0, 0, 1), 2))\n\tassert(not FeriaMath.rayDisc(V(0, 0, 0), V(1, 0, 0), V(0, 0, -10), V(0, 0, 1), 2))\n\tlocal fallen = FeriaMath.cansKnocked(1, table.create(10, true)); assert(#fallen > 1)\n\tlocal landing, time = FeriaMath.ringLanding(V(0, 5, 0), V(0, 0, -1), 0.5, 0); assert(time > 0); assert(landing.Z < -10)\nend)\n\ntest(\"Mundo: lobby, 18 zonas y recuerdos generados\", function()\n\tlocal world = roblox.Instance.new(\"Folder\"); world.Name = \"PruebaMundo\"; world.Parent = root.Workspace\n\tlocal lobby = loadModule(root.ServerScriptService.Server.World.Lobby).build(world)\n\tassert(lobby.spawn:IsA(\"SpawnLocation\")); local count = 0\n\tfor _ in lobby.mapPrompts do count += 1 end; equal(count, 18)\n\tlocal zones = loadModule(root.ServerScriptService.Server.World.Zones).build(world)\n\tcount = 0\n\tfor _, zone in zones do\n\t\tcount += 1; assert(zone.collectPrompt); assert(zone.returnPrompt)\n\tend\n\tequal(count, 18)\n\tlocal parts = 0; for _, item in world:GetDescendants() do if item:IsA(\"BasePart\") then parts += 1 end end\n\tassert(parts < 7000); print(`Piezas del mundo base: {parts}`)\nend)\n\n-- DataStore y jugadores simulados; se ejecuta DataService real.\nlocal document, fail, calls = nil, false, 0\nservices.DataStoreService = {\n\tGetDataStore = function() return { UpdateAsync = function(_, _, transform)\n\t\tcalls += 1; if fail then error(\"API desactivada\") end\n\t\tlocal value = transform(document); if value ~= nil then document = value end\n\t\treturn document\n\tend } end,\n\tGetRequestBudgetForRequestType = function() return 100 end,\n}\nservices.RunService = { IsStudio = function() return true end }\nlocal player = { UserId = 42, Name = \"Catracho\", IsDescendantOf = function() return true end }\nservices.Players = { PlayerAdded = signal(), PlayerRemoving = signal(), GetPlayers = function() return { player } end }\nfakeGame.BindToClose = function() end\nlocal DataService = loadModule(root.ServerScriptService.Server.Services.DataService)\ntest(\"DataService: carga, guarda y renueva candado sin cambios\", function()\n\tDataService.start(); task.wait(0.05)\n\tassert(DataService.get(player)); DataService.get(player).coins = 777; DataService.markDirty(player)\n\tassert(DataService.saveNow(player)); equal(document.data.coins, 777); equal(document.lock.job, \"prueba\")\nend)\ntest(\"DataService: API apagada conserva perfil en memoria\", function()\n\tfail = true; assert(DataService.saveNow(player)); assert(DataService.isMemoryOnly())\n\tservices.Players.PlayerRemoving:fire(player)\n\tservices.Players.PlayerAdded:fire(player)\n\tequal(DataService.get(player).coins, 777)\nend)\ntest(\"DataService: nunca toma un candado activo de otro servidor\", function()\n\tfail = false\n\tdocument = { data = { coins = 321 }, lock = { job = \"otro-servidor\", at = os.time() } }\n\tservices.RunService = { IsStudio = function() return false end }\n\tlocal kicked = false\n\tlocal visitor = { UserId = 43, Name = \"Visitante\", IsDescendantOf = function() return true end,\n\t\tKick = function() kicked = true end }\n\tservices.Players = { PlayerAdded = signal(), PlayerRemoving = signal(), GetPlayers = function() return { visitor } end }\n\tcache[root.ServerScriptService.Server.Services.DataService] = nil\n\tlocal independent = loadModule(root.ServerScriptService.Server.Services.DataService)\n\tindependent.start(); task.wait(16)\n\tassert(kicked); equal(independent.get(visitor), nil); equal(document.lock.job, \"otro-servidor\"); equal(document.data.coins, 321)\nend)\nprint(`{total} pruebas aprobadas`)\n-- Lune termina tareas perpetuas de autoguardado al salir.\nrequire(\"@lune/process\").exit(0)\n"}]};
